#: The nine function codes the handler's ``evaluate`` admits
#: [common/acas022.cbl:L338-L358]. Codes 32, 33 and 34 are absent because this
#: handler does not dispatch them - see ``N-codes-32-33-dead``. Code 6
#: (delete-all) is spare and unused, so there is no delete-all verb.
#:
#: ANOMALY ``N-codes-32-33-dead``, with its locator: the vocabulary declares
#: ``88 fn-Read-By-Batch value 32. *> 08/02/17 for OTM3/5 (sl095/pl095)`` and
#: ``88 fn-Read-By-Cust value 33. *> 09/02/17 for OTM3 (sl110, 120, 190)``
#: [copybooks/wsfnctn.cob:L103-L104], yet a census of all seventeen handler
#: programs finds only four extended-code dispatches - ``acas012`` -> 31,
#: ``acas016`` -> 34, ``acas022`` -> 31 (here, [common/acas022.cbl:L343-L345])
#: and ``acas026`` -> 31. Neither ``acas019`` nor ``acas029``, the two OTM
#: handlers the comments name, dispatches 32 or 33 at all, so both codes are
#: dead vocabulary. Recorded, never implemented: adding a verb no frozen
#: program dispatches would be new behaviour.
SUPPORTED_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {
        int(FileFunction.OPEN),  # 1
        int(FileFunction.CLOSE),  # 2
        int(FileFunction.READ_NEXT),  # 3
        int(FileFunction.READ_INDEXED),  # 4
        int(FileFunction.WRITE),  # 5
        int(FileFunction.RE_WRITE),  # 7
        int(FileFunction.DELETE),  # 8
        int(FileFunction.START),  # 9
        int(FileFunction.READ_BY_NAME),  # 31
    }
)

#: The verbs whose key guard runs before dispatch [common/acas022.cbl:L298-L312].
#: ``fn-read-indexed`` and ``fn-start`` share the 998 arm; ``fn-delete`` has its
#: own 996 arm.
_KEY_GUARD_998_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {int(FileFunction.READ_INDEXED), int(FileFunction.START)}
)
_KEY_GUARD_996_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {int(FileFunction.DELETE)}
)

#: The only key number either program admits, enforced by the guard above.
ONLY_KEY_NUMBER: Final[int] = 1


# =====================================================================
# KEY METADATA AND CURSORS
# =====================================================================

#: The ONE key of reference this table declares
#: [common/purchMT.scb:L228-L230] and [common/purchMT.cbl:L227-L237]:
#: ``'PURCH-KEY'``, offset ``0001``, length ``0007``, type ``'STR'``. Exactly one
#: entry, which is why ``File-Key-No`` may only ever be 1 and why the guard at
#: [common/acas022.cbl:L301] and [common/acas022.cbl:L307] rejects anything else.
#: ANOMALY ``N-kortype``: ``KOR-Type`` carries ``'STR'`` while its own comment
#: says "Not used currently"; and the group is declared ``Table-Of-Keynames`` but
#: redefined ``table-of-keynames`` with ``keyOfReference`` in lower case.
KEY_OF_REFERENCE: Final[KeyOfReference] = key_of_reference(TABLE, ONLY_KEY_NUMBER)

#: ``03 keyOfReference occurs 1`` [common/purchMT.cbl:L232] - the OCCURS count is
#: 1, and everything about ``File-Key-No`` follows from it. Asserted rather than
#: commented, so that a dictionary or metadata change which added a second key
#: fails here instead of quietly making the guard at
#: [common/acas022.cbl:L301] wrong.
if len(TABLE_OF_KEYNAMES[TABLE]) != ONLY_KEY_NUMBER:  # pragma: no cover
    raise LookupError(
        f"{TABLE} declares {len(TABLE_OF_KEYNAMES[TABLE])} keys of reference; "
        f"[common/purchMT.cbl:L232] declares `occurs 1`"
    )

#: ``PRIMARY KEY (`PURCH-KEY`)`` [mysql/ACASDB.sql:L676]. Here the key of
#: reference and the primary key are the same column, unlike ``GLPOSTING-REC``.
PRIMARY_KEY_COLUMN: Final[str] = TABLE_PRIMARY_KEYS[TABLE]

#: ``ba040``'s hard-coded self-positioning relation and low key
#: [common/purchMT.cbl:L521-L522], held as data by ``dal/cursor_state.py`` so
#: that the per-bridge disagreement survives as data rather than as code.
_SEQUENTIAL_START: Final = SEQUENTIAL_READ_START[TABLE]

#: ``ba140``'s ordering, from the same data source
#: [common/purchMT.cbl:L1010-L1037]. ONE term, ``PURCH-NAME`` ascending, on
#: cursor slot 2.
NAME_ORDER: Final[ExtraReadOrder] = EXTRA_READ_ORDERS[TABLE][
    FileFunction.READ_BY_NAME
]

#: ``ba140`` writes its low key UNQUOTED - ``"0000000"`` is a COBOL literal
#: delimited by ``"``, so the token that reaches the statement text is the bare
#: ``0000000`` [common/purchMT.cbl:L1030]. ``ba040`` writes ``'"0000000"'`` and
#: so reaches the statement text WITH the quotes [common/purchMT.cbl:L522].
#: ANOMALY ``N-lowkey-quoting-split``. This constant is inlined into the
#: statement text rather than bound, because unlike a key value it is a constant
#: written into the frozen source and carries no caller data; binding it would
#: quote it and silently repair the divergence. AMBIGUITY
#: ``Q-purch-numeric-lowkey`` records the measurement this needs.
_NAME_ORDER_LOW_KEY: Final[str] = "0000000"

#: ``01  DAL-Data.`` declares TWO cursor flags
#: [common/purchMT.cbl:L244-L254]: ``Most-Cursor-Set`` for the key-ordered walk
#: and ``Most-Cursor-Set-2`` under the comment "Special for selective read
#: next." They are never collapsed into one: ``ba040``/``ba041`` drive slot 1 and
#: ``ba140``/``ba141`` drive slot 2, and each is set and cleared independently -
#: except by ``ba998-Free``, which clears slot 1 only (``N-free-clears-slot-1``
#: ``-only``).
_KEY_ORDER_SLOT: Final[CursorSlot] = CursorSlot.PRIMARY
_NAME_ORDER_SLOT: Final[CursorSlot] = CursorSlot.SECONDARY

#: ANOMALY ``N-single-result-pointer-two-cursors``. There are TWO cursor flags
#: but only ONE result pointer: ``01 TP-PULEDGER-REC USAGE POINTER``
#: [common/purchMT.cbl:L283]. Every paragraph that runs a query stores into that
#: one pointer - ``MOVE WS-MYSQL-RESULT TO TP-PULEDGER-REC``
#: [common/purchMT.cbl:L547, :L700, :L849, :L1054] - and every fetch reads it
#: back [common/purchMT.cbl:L592, :L714, :L1096]. So a name-ordered walk started
#: while a key-ordered walk is live DESTROYS the first walk's result while
#: leaving its flag set, and the next slot-1 fetch then returns rows in NAME
#: order; a read-indexed in the middle of either walk does the same and then
#: frees the pointer outright. The rows a caller reads therefore depend on what
#: another verb did in between, which is a database-observable difference and not
#: a bookkeeping one. It is reproduced by keeping the store in ONE place and the
#: two flags in another, exactly as the frozen source does.
_RESULT_POINTER: Final[CursorState] = CursorState(
    table_name=TABLE, slot=_KEY_ORDER_SLOT
)

#: The relation each ``Access-Type`` selects [common/purchMT.cbl:L800-L811].
#: Reproduced here only to document that ANOMALY
#: ``N-access-type-9-dead-in-bridge`` applies - the ``when 9`` arm is dead
#: because the guard at [common/purchMT.cbl:L780] rejects 9 before the
#: ``evaluate`` runs - and that there is NO ``when other``, so an out-of-range
#: value would leave ``MOST-Relation`` as spaces. The live mapping is applied by
#: ``dal/cursor_state.py``; ``Access-Type`` is passed through unmodified because
#: the facade deliberately does not zero it, so 5..9 IS the relation.
_START_RELATIONS: Final[Mapping[int, str]] = {
    int(AccessType.EQUAL_TO): "=  ",  # [common/purchMT.cbl:L802]
    int(AccessType.LESS_THAN): "<  ",  # [common/purchMT.cbl:L804]
    int(AccessType.GREATER_THAN): ">  ",  # [common/purchMT.cbl:L806]
    int(AccessType.NOT_LESS_THAN): ">= ",  # [common/purchMT.cbl:L808]
    int(AccessType.NOT_GREATER_THAN): "<= ",  # DEAD [common/purchMT.cbl:L810]
}

# =====================================================================
# THE 29 COLUMNS, FROM THE DATA DICTIONARY
# =====================================================================
# Agent Action Plan section 0.8.1, verbatim: "Data dictionary first. ... every
# Python field definition cites its entry. This ordering is a directive, not a
# preference - it is what prevents fields being transcribed by eye."
#
# Nothing below transcribes a picture clause. Every width, scale, sign and drift
# comes from ``loader``, whose entries are generated from the authoritative
# triple - copybook field, bridge host variable, and column definition.


@dataclasses.dataclass(frozen=True, slots=True)
class _ColumnBinding:
    """One column's complete transfer contract, derived from the dictionary.

    Attributes:
        column: The MySQL column name, hyphens included.
        ordinal: Its 1-based position in ``mysql/ACASDB.sql``.
        attribute: The dotted path to the value on :class:`WsPurchRecord`. Dotted
            for the two group members - ``quarters.turnover_q1`` - because the
            record models the copybook's group structure and the bridge does not.
        host_variable: The ``HV-`` name, which is also the attribute name on
            :class:`HostVariables` in lower case with hyphens as underscores.
        kind: ``"char"``, ``"int"`` or ``"decimal"`` - the host variable's own
            storage class, NOT the copybook's.
        digits: The host variable's total digit count; zero for character fields.
        scale: The host variable's fraction digit count.
        width: The host variable's character length; zero for numeric fields.
        signed: Whether the HOST VARIABLE is signed. Twelve of these are False
            where the copybook field is signed - that is ``N-signloss-twelve``.
        copybook_signed: Whether the COPYBOOK field is signed, so the loss is
            visible in the data rather than only in prose.
        copybook_usage: The copybook field's usage - ``ALPHANUMERIC``,
            ``DISPLAY``, ``COMP``, ``COMP-3``, ``BINARY-CHAR``, ``BINARY-LONG``
            or ``GROUP``. It governs the unload, because a ``MOVE`` back into the
            record is bounded by the RECEIVING field, not by the host variable.
        copybook_digits: The copybook field's digit count, or zero where it has
            no picture clause. ``BINARY-CHAR`` and ``BINARY-LONG`` have none -
            their capacity is the C storage width instead, held in
            :data:`_BINARY_STORAGE_BYTES`.
        copybook_scale: The copybook field's fraction digits.
        copybook_width: The copybook field's character length, zero for numerics.
        edit_start: 1-based start of the window sliced out of ``WS-MYSQL-EDIT``;
            zero for character fields, which are trimmed instead.
        edit_length: That window's length.
        citation: ``loader.cite(key)`` - the copybook, bridge and column
            locators for this field, in one string.
        drift_details: ``loader.drift_for(key).details``, empty when the four
            views agree.
    """

    column: str
    ordinal: int
    attribute: str
    host_variable: str
    kind: str
    digits: int
    scale: int
    width: int
    signed: bool
    copybook_signed: bool
    copybook_usage: str
    copybook_digits: int
    copybook_scale: int
    copybook_width: int
    edit_start: int
    edit_length: int
    citation: str
    drift_details: str

    @property
    def field(self) -> str:
        """The :class:`HostVariables` attribute name for this column."""
        return self.host_variable.lower().replace("-", "_")

    @property
    def sign_lost_at_bridge(self) -> bool:
        """True when the copybook signs the field and the host variable does not.

        This is the predicate that selects the twelve fields of
        ``N-signloss-twelve`` - computed from the dictionary rather than from a
        hand-written list, so a dictionary regeneration cannot silently drop one.
        """
        return self.copybook_signed and not self.signed


#: Where each column's value comes from on :class:`WsPurchRecord`, and the edit
#: window the bridge slices for it. The record attribute names are the ONLY
#: hand-written entries here - every other property of every column is read from
#: the dictionary below. Two of them are dotted because the copybook groups them
#: and the bridge does not:
#:
#: * ``PURCH-ADDRESS`` is a GROUP of ``Purch-Addr1`` and ``Purch-Addr2``, 48
#:   characters each [copybooks/wspl.cob:L23-L25], which the bridge flattens to
#:   ``pic x(96)`` [common/purchMT.cbl:L338] - ANOMALY ``N-address-flattened``.
#:   It is handled by :func:`_group_concatenation` rather than by a plain
#:   attribute read, and the dictionary records the same derivation.
#: * ``TURNOVER-Q1..Q4`` live under the ``Quarters`` group
#:   [copybooks/wspl.cob:L45-L49]. Note the case change: the copybook writes
#:   ``Turnover-q1`` and the column writes ``TURNOVER-Q1``.
#:
#: ``PURCH-CREATE-DAT``'s record attribute keeps the copybook's spelling,
#: ``purch_create_date``, because ``records/purchase_ledger.py`` models the
#: copybook; only the host variable and the column carry the truncated
#: ``Dat`` - ANOMALY ``N-create-date-rename``
#: [common/purchMT.cbl:L352].
_RECORD_ATTRIBUTES: Final[Mapping[str, str]] = {
    "PURCH-KEY": "ws_purch_key",
    "PURCH-STATUS": "purch_status",
    "PURCH-NOTES-TAG": "purch_notes_tag",
    "PURCH-NAME": "purch_name",
    "PURCH-ADDRESS": "purch_address",
    "PURCH-PHONE": "purch_phone",
    "PURCH-EXT": "purch_ext",
    "PURCH-FAX": "purch_fax",
    "PURCH-EMAIL": "purch_email",
    "PURCH-DISCOUNT": "purch_discount",
    "PURCH-CREDIT": "purch_credit",
    "PURCH-SORTCODE": "purch_sortcode",
    "PURCH-ACCOUNTNO": "purch_accountno",
    "PURCH-LIMIT": "purch_limit",
    "PURCH-ACTIVETY": "purch_activety",
    "PURCH-LAST-INV": "purch_last_inv",
    "PURCH-LAST-PAY": "purch_last_pay",
    "PURCH-AVERAGE": "purch_average",
    "PURCH-CREATE-DAT": "purch_create_date",
    "PURCH-PAY-ACTIVETY": "purch_pay_activety",
    "PURCH-PAY-AVERAGE": "purch_pay_average",
    "PURCH-PAY-WORST": "purch_pay_worst",
    "PURCH-CURRENT": "purch_current",
    "PURCH-LAST": "purch_last",
    "TURNOVER-Q1": "quarters.turnover_q1",
    "TURNOVER-Q2": "quarters.turnover_q2",
    "TURNOVER-Q3": "quarters.turnover_q3",
    "TURNOVER-Q4": "quarters.turnover_q4",
    "PURCH-UNAPPLIED": "purch_unapplied",
}

#: The five windows sliced out of ``WS-MYSQL-EDIT``, as ``(start, length)`` pairs
#: keyed by the host variable's declared integer-digit count. The bridge chooses
#: the window per column and its choices are consistent with the declared digits
#: everywhere EXCEPT ``PURCH-CREDIT``, which is ``9(08)`` at the host variable
#: and ``mediumint(2)`` at the column and still gets the eight-digit window
#: [common/purchMT.cbl:L1415] - ANOMALY ``N-editwindow``.
#:
#: ``WS-MYSQL-EDIT`` is ``PIC -Z(18)9.9(9)``
#: [common/purchMT.cbl:L215], so the integer field ends at position 20 and each
#: window is that many characters back from it. NONE of them includes position 1,
#: which is the sign - ANOMALY ``N-sign-dropped-by-edit-window``.
_INTEGER_WINDOW_BY_DIGITS: Final[Mapping[int, tuple[int, int]]] = {
    2: (19, 2),  # PURCH-DISCOUNT [common/purchMT.cbl:L1398]
    3: (18, 3),  # PURCH-STATUS, PURCH-NOTES-TAG [:L1320, :L1332]
    8: (13, 8),  # PURCH-CREDIT, PURCH-SORTCODE, the money [:L1415, :L1427, :L1559]
    10: (11, 10),  # the ten wide integers from [:L1439]
}

#: ``STRING WS-MYSQL-EDIT(22:02)`` - the fraction window, the same for every
#: scaled column, and NOT trimmed [common/purchMT.cbl:L1404, L1565].
_FRACTION_WINDOW: Final[tuple[int, int]] = (22, 2)


def _dictionary_bindings() -> tuple[_ColumnBinding, ...]:
    """Build the 29 column bindings from ``loader``, in COLUMN-ORDINAL order.

    Rule R-5's field-level traceability is mechanised here rather than
    hand-maintained: the loop reads every property it needs from the dictionary
    entry and hand-writes nothing except the record attribute name, which the
    dictionary cannot know because it describes COBOL, not Python.

    Returns:
        The bindings, ordered by ``column.ordinal`` so that the tuple IS the
        table's column order and every later ordering can be derived from it.

    Raises:
        LookupError: If the dictionary does not describe exactly the 29 columns
            the frozen schema declares, or names one this module has no record
            attribute for. Failing at import is deliberate: a silently short
            column list would produce an ``INSERT`` that omits a ``NOT NULL``
            column, which section 3.16 of this module's specification forbids.
    """
    entries = loader.entries_for_table(TABLE)
    if len(entries) != _EXPECTED_COLUMN_COUNT:
        raise LookupError(
            f"{TABLE} is declared with {_EXPECTED_COLUMN_COUNT} columns in "
            f"mysql/ACASDB.sql:L646-L677 but the data dictionary describes "
            f"{len(entries)}; regenerate data_dictionary/"
            f"acas_posting_dictionary.json before using this module."
        )
    bindings: list[_ColumnBinding] = []
    for entry in sorted(entries, key=lambda item: item.column.ordinal):
        column = entry.column.name
        attribute = _RECORD_ATTRIBUTES.get(column)
        if attribute is None:
            raise LookupError(
                f"the data dictionary names column {column} for {TABLE}, which "
                f"acas_posting/records/purchase_ledger.py does not carry; the "
                f"record module and copybooks/wspl.cob must be reconciled "
                f"before this module can transfer it."
            )
        host_variable = entry.bridge_host_variable
        drift = loader.drift_for(entry.key)
        if host_variable.usage == "ALPHANUMERIC":
            kind = "char"
            edit_start, edit_length = 0, 0
        elif host_variable.scale:
            kind = "decimal"
            edit_start, edit_length = _INTEGER_WINDOW_BY_DIGITS[
                host_variable.integer_digits
            ]
        else:
            kind = "int"
            edit_start, edit_length = _INTEGER_WINDOW_BY_DIGITS[
                host_variable.integer_digits
            ]
        copybook = entry.copybook
        bindings.append(
            _ColumnBinding(
                column=column,
                ordinal=entry.column.ordinal,
                attribute=attribute,
                host_variable=host_variable.name,
                kind=kind,
                digits=host_variable.digits or 0,
                scale=host_variable.scale or 0,
                width=host_variable.character_length or 0,
                signed=bool(host_variable.signed),
                copybook_signed=bool(copybook is not None and copybook.signed),
                copybook_usage=(
                    "GROUP" if copybook is None else str(copybook.usage)
                ),
                copybook_digits=(
                    0 if copybook is None else (copybook.digits or 0)
                ),
                copybook_scale=(
                    0 if copybook is None else (copybook.scale or 0)
                ),
                copybook_width=(
                    0 if copybook is None else (copybook.character_length or 0)
                ),
                edit_start=edit_start,
                edit_length=edit_length,
                citation=loader.cite(entry.key),
                drift_details=drift.details or "",
            )
        )
    return tuple(bindings)


#: The C storage width of the two picture-less binary usages the copybook
#: declares. ``binary-char`` [copybooks/wspl.cob:L31] is one signed byte and
#: ``binary-long`` [copybooks/wspl.cob:L32-L42] is four, so a value moved back
#: into one of them is bounded by that width rather than by a digit count. The
#: copybook's own comments record what these fields used to be - "were pic 99"
#: and "all these were pic 9(8) comp" - which is how a two-digit field came to
#: hold a value an eight-digit host variable can produce.
_BINARY_STORAGE_BYTES: Final[Mapping[str, int]] = {
    "BINARY-CHAR": 1,
    "BINARY-SHORT": 2,
    "BINARY-LONG": 4,
    "BINARY-DOUBLE": 8,
}


#: ``mysql/ACASDB.sql:L646-L677`` declares 29 columns for this table, every one
#: ``NOT NULL``.
_EXPECTED_COLUMN_COUNT: Final[int] = 29

#: The 29 bindings in column order - the single list every statement, the load
#: and the unload are all driven from.
_BINDINGS: Final[tuple[_ColumnBinding, ...]] = _dictionary_bindings()

#: The column names in table-ordinal order. Every ``INSERT`` and ``UPDATE``
#: names all of them, in this order.
COLUMN_ORDER: Final[tuple[str, ...]] = tuple(
    binding.column for binding in _BINDINGS
)

#: The order ``bb000-HV-Load`` moves the record into the host variables
#: [common/purchMT.cbl:L1212-L1240] - 29 moves, one per column.
HV_LOAD_ORDER: Final[tuple[str, ...]] = COLUMN_ORDER

#: The order ``bb100-UnloadHVs`` moves them back
#: [common/purchMT.cbl:L1259-L1287] - 29 moves, the same order.
HV_UNLOAD_ORDER: Final[tuple[str, ...]] = COLUMN_ORDER

# THE SYMMETRY, CHECKED RATHER THAN ASSERTED IN PROSE. This bridge is the only
# one in the folder whose load order, unload order and column order are the same
# list; recording where the frozen code is right is what makes the thirty-odd
# recorded defects credible. If a dictionary regeneration ever reordered the
# columns, this would fail at import rather than silently produce a statement
# whose placeholders no longer line up with its values.
if not (HV_LOAD_ORDER == HV_UNLOAD_ORDER == COLUMN_ORDER):  # pragma: no cover
    raise LookupError(
        "purchMT's load order [common/purchMT.cbl:L1212-L1240], unload order "
        "[common/purchMT.cbl:L1259-L1287] and column order "
        "[mysql/ACASDB.sql:L646-L677] must be the same list"
    )

#: The twelve columns of ``N-signloss-twelve``, selected by the dictionary's own
#: signedness drift rather than by a hand-written list:
#: ``PURCH-CREDIT`` through ``PURCH-PAY-WORST``
#: [copybooks/wspl.cob:L31-L42] -> [common/purchMT.cbl:L295-L306].
SIGN_LOSS_COLUMNS: Final[tuple[str, ...]] = tuple(
    binding.column for binding in _BINDINGS if binding.sign_lost_at_bridge
)

#: The eight signed ``decimal(10,2)`` money columns. ``PURCH-DISCOUNT`` is
#: scaled too but is unsigned at every layer, so it is not one of these.
MONEY_COLUMNS: Final[tuple[str, ...]] = tuple(
    binding.column
    for binding in _BINDINGS
    if binding.kind == "decimal" and binding.signed
)

#: Every character column and the width its host variable declares, so that a
#: value shorter than the column is space-padded rather than sent short - the
#: ``initialize``-first invariant of section 3.16.
CHARACTER_HOST_VARIABLE_WIDTHS: Final[Mapping[str, int]] = {
    binding.column: binding.width
    for binding in _BINDINGS
    if binding.kind == "char"
}

#: The window each numeric column is rendered through, for the record and for
#: tests. Character columns are absent because they are trimmed, not windowed.
EDIT_WINDOWS: Final[Mapping[str, tuple[int, int]]] = {
    binding.column: (binding.edit_start, binding.edit_length)
    for binding in _BINDINGS
    if binding.kind != "char"
}

#: Copybook fields that reach the database NOWHERE, recorded as deliberate
#: omissions per rule R-5's "Deliberate omissions are recorded as omissions".
#: Each maps to why it is absent. Adding a column for any of them would be
#: schema evolution, which rule R-3 forbids.
OMITTED_COPYBOOK_FIELDS: Final[Mapping[str, str]] = {
    "Purch-Addr1": (
        "flattened into PURCH-ADDRESS by the bridge "
        "[common/purchMT.cbl:L338]; no host variable, no column "
        "[copybooks/wspl.cob:L24]"
    ),
    "Purch-Addr2": (
        "flattened into PURCH-ADDRESS by the bridge "
        "[common/purchMT.cbl:L338]; no host variable, no column "
        "[copybooks/wspl.cob:L25]"
    ),
    "PTurnover-q": (
        "an OCCURS 4 redefinition of the four named quarters; the redefinition "
        "has no host variable and no column, and the bridge's own record buffer "
        "omits it entirely [copybooks/wspl.cob:L50-L51]"
    ),
    "Purch-Stats-Date": (
        "N-stats-date-write-nowhere: present in BOTH record layouts and stored "
        "nowhere - absent from the host-variable group "
        "[common/purchMT.cbl:L285-L313], the load "
        "[common/purchMT.cbl:L1211-L1240], the unload "
        "[common/purchMT.cbl:L1257-L1287] and the schema "
        "[mysql/ACASDB.sql:L646-L677], while being declared in BOTH record "
        "layouts [copybooks/wspl.cob:L53]"
    ),
    "filler": (
        "twelve bytes of record padding with no host variable and no column "
        "[copybooks/wspl.cob:L54]"
    ),
    "Array-k": (
        "N-dead-redefine: part of a key redefinition that is commented out in "
        "the frozen copybook and is not revived "
        "[copybooks/wspl.cob:L15-L17]"
    ),
    "Check-Digit": (
        "N-dead-redefine: the second half of the same commented-out key "
        "redefinition [copybooks/wspl.cob:L15-L17]"
    ),
}


# =====================================================================
# ``WS-MYSQL-EDIT`` - THE EDITED FIELD EVERY NUMERIC VALUE PASSES THROUGH
# =====================================================================

#: ``01  WS-MYSQL-EDIT      PIC -Z(18)9.9(9).`` [common/purchMT.cbl:L215].
EDIT_PICTURE: Final[str] = "-Z(18)9.9(9)"

#: Position 1 holds the sign. A SINGLE ``-`` is simple insertion, not floating
#: insertion (which needs at least two sign symbols), so it stays here and never
#: moves next to the first significant digit. No window slices it - which is
#: ANOMALY ``N-sign-dropped-by-edit-window`` and AMBIGUITY
#: ``Q-purch-money-sign``.
_EDIT_SIGN_POSITION: Final[int] = 1

#: Positions 2..19 are the eighteen ``Z`` positions - zero-suppressed, so a
#: leading zero renders as a space.
_EDIT_SUPPRESSED_DIGITS: Final[int] = 18

#: Position 20 is the ``9`` - the units digit, never suppressed, which is why a
#: value of zero still renders as ``"0"`` in every window rather than as spaces.
_EDIT_INTEGER_DIGITS: Final[int] = _EDIT_SUPPRESSED_DIGITS + 1

#: Positions 22..30 are the nine fraction digits, never suppressed.
_EDIT_FRACTION_DIGITS: Final[int] = 9

#: The whole field: sign + 19 integer digits + ``.`` + 9 fraction digits.
_EDIT_WIDTH: Final[int] = 1 + _EDIT_INTEGER_DIGITS + 1 + _EDIT_FRACTION_DIGITS


def _ws_mysql_edit(value: Decimal | int) -> str:
    """Render one numeric host variable into the bridge's edited field.

    Reproduces ``MOVE HV-<name> TO WS-MYSQL-EDIT`` for the field declared at
    [common/purchMT.cbl:L215], from the picture clause rather than from a guess:

    * The sign goes to position 1 and NOWHERE else, because ``PIC -Z(18)9.9(9)``
      uses ONE ``-`` and one sign symbol is simple insertion.
    * The eighteen ``Z`` positions suppress leading zeros to spaces.
    * The ``9`` at position 20 always prints, so zero renders as ``"0"``.
    * The nine fraction digits are zero-filled, never suppressed.
    * A value too wide for nineteen integer digits loses its HIGH-ORDER digits,
      which is what a COBOL ``MOVE`` to a shorter numeric field does.

    Everything is done in :class:`~decimal.Decimal` and :class:`int`. No binary
    approximation is used anywhere, per rule R-2 - ``scaleb`` and
    ``to_integral_value`` are exact, and the truncation is ``ROUND_DOWN`` because
    an un-``ROUNDED`` COBOL store truncates toward zero.

    Args:
        value: The host variable's value. An :class:`int` for the binary fields
            and a :class:`~decimal.Decimal` for the scaled ones; never a binary
            approximation of a real number.

    Returns:
        The thirty-character image, exactly as ``WS-MYSQL-EDIT`` would hold it.
    """
    magnitude = Decimal(value)
    negative = magnitude < 0
    if negative:
        # Negate rather than take a magnitude function, so that no banned
        # numeric helper is used and the operation stays exact.
        magnitude = -magnitude
    total_digits = _EDIT_INTEGER_DIGITS + _EDIT_FRACTION_DIGITS
    units = int(
        magnitude.scaleb(_EDIT_FRACTION_DIGITS).to_integral_value(
            rounding=ROUND_DOWN
        )
    )
    # ``[-total_digits:]`` is the high-order truncation a COBOL MOVE performs
    # when the sending field is wider than the receiving one.
    digits = f"{units:0{total_digits}d}"[-total_digits:]
    integer_part = digits[:_EDIT_INTEGER_DIGITS]
    fraction_part = digits[_EDIT_INTEGER_DIGITS:]
    suppressed = integer_part[:_EDIT_SUPPRESSED_DIGITS].lstrip("0")
    return (
        ("-" if negative else " ")
        + suppressed.rjust(_EDIT_SUPPRESSED_DIGITS)
        + integer_part[_EDIT_SUPPRESSED_DIGITS]
        + "."
        + fraction_part
    )


def _edit_window(image: str, start: int, length: int) -> str:
    """Slice ``WS-MYSQL-EDIT(start:length)`` out of a rendered image.

    COBOL reference modification is 1-based and inclusive of ``start``, so this
    is ``image[start - 1 : start - 1 + length]``. The five windows the bridge
    uses are held in :data:`_INTEGER_WINDOW_BY_DIGITS` and
    :data:`_FRACTION_WINDOW`, each traced to the statement that slices it.

    Args:
        image: A thirty-character image from :func:`_ws_mysql_edit`.
        start: The 1-based start position.
        length: The number of characters.

    Returns:
        The window's contents, spaces included.

    Raises:
        ValueError: If the window falls outside the field. This can only happen
            if a window constant is edited to disagree with the picture clause,
            which is a coding error in this module rather than a data condition.
    """
    if start < 1 or length < 1 or start - 1 + length > _EDIT_WIDTH:
        raise ValueError(
            f"WS-MYSQL-EDIT({start}:{length}) falls outside the "
            f"{_EDIT_WIDTH}-character field declared as {EDIT_PICTURE} at "
            f"[common/purchMT.cbl:L215]"
        )
    return image[start - 1 : start - 1 + length]


def _trim(text: str) -> str:
    """``FUNCTION TRIM (x)`` - remove leading AND trailing spaces.

    The form the bridge uses on every numeric window, for example
    ``FUNCTION TRIM (WS-MYSQL-EDIT(13:08))`` [common/purchMT.cbl:L1559]. Zero
    suppression leaves the window's leading positions as spaces, so both ends
    have to go.
    """
    return text.strip(" ")


def _trim_trailing(text: str) -> str:
    """``FUNCTION TRIM (x, TRAILING)`` - remove trailing spaces only.

    The form the bridge uses on every character host variable
    [common/purchMT.cbl:L1309, L1342, L1351, L1360, L1369, L1378, L1387]. A
    LEADING space in a name or an address is data and is kept.
    """
    return text.rstrip(" ")


def _ws_file_key(text: str) -> str:
    """Fit one log literal into ``WS-File-Key pic x(64)``.

    [copybooks/wsfnctn.cob:L52] declares the field 64 characters wide, so a
    COBOL ``MOVE`` of a longer literal truncates on the right and a shorter one
    pads with spaces. Both are reproduced, because the field's contents are
    compared when two runs' logs are diffed.

    Args:
        text: The literal the frozen source moves into the field.

    Returns:
        Exactly :data:`WS_FILE_KEY_WIDTH` characters.
    """
    return text[:WS_FILE_KEY_WIDTH].ljust(WS_FILE_KEY_WIDTH)


# =====================================================================
# ``MOVE`` INTO A HOST VARIABLE - WHERE THE SIGN AND THE DIGITS ARE LOST
# =====================================================================


def _move_to_unsigned_host_variable(value: int, binding: _ColumnBinding) -> int:
    """Reproduce a signed binary field's ``MOVE`` into an UNSIGNED host variable.

    ANOMALY ``N-signloss-twelve``, the largest instance in the checkout and the
    purchase twin of Agent Action Plan anomaly #11. Twelve consecutive fields are
    declared signed in the copybook [copybooks/wspl.cob:L31-L42] and unsigned in
    the bridge [common/purchMT.cbl:L295-L306], and their columns are unsigned
    too. Agent Action Plan section 0.6.2, verbatim: "a negative value computed in
    COBOL loses its sign **at the bridge**, not at the database - so the Python
    data-access layer must reproduce the bridge's conversion, not merely write
    the computed value and let MySQL complain."

    Two effects, in the order COBOL applies them:

    1. THE SIGN IS DISCARDED. A ``MOVE`` to an unsigned numeric field stores the
       absolute value; there is nowhere for the sign to go. The value is NOT
       clamped, NOT rejected and NOT re-signed. AMBIGUITY ``Q-3``, already
       carried by this table's dictionary entries, records that the C interface's
       own conversion must be measured to confirm the resulting stored value.
    2. HIGH-ORDER DIGITS ARE TRUNCATED to the host variable's declared width.
       No compile line in the repository passes a truncation flag, so the
       compiler's default applies and a ``COMP`` field holds exactly its declared
       digits.

    ``PURCH-CREDIT`` passes through all FOUR of its declared widths in order -
    ``binary-char`` and its plus-or-minus 127 range
    [copybooks/wspl.cob:L31], ``pic 99 comp`` in the bridge's own record buffer
    [common/purchMT.cbl:L344], ``PIC 9(08) COMP`` at the host variable
    [common/purchMT.cbl:L295], then ``mediumint(2) unsigned`` at the column.
    Anomaly ``N-credit-four-widths``. ``PURCH-SORTCODE`` narrows the other way,
    eight digits at both COBOL layers - ``binary-long``
    [copybooks/wspl.cob:L32] and ``pic 9(8) comp`` in the bridge's own record
    buffer [common/purchMT.cbl:L345] - into an unsigned eight-digit host variable
    [common/purchMT.cbl:L296] and then a ``mediumint(6) unsigned`` column
    [mysql/ACASDB.sql:L646-L677]: anomaly ``N-sortcode-narrowing``. A sort code
    above 999999 therefore cannot be stored. Neither field is validated against
    its column; rule R-3 forbids added validation, so the narrowing is left to
    the database exactly as the frozen bridge leaves it.

    ANOMALY ``N-sortcode-case-drift``: the two COBOL layers do not even spell the
    field the same way - ``Purch-SortCode`` with a capital C
    [copybooks/wspl.cob:L32] against ``Purch-Sortcode`` with a lower-case c
    [common/purchMT.cbl:L345]. COBOL is case-insensitive so nothing breaks, and
    the name is NOT normalised here; it is one more trace of the bridge's record
    buffer having been hand-edited rather than regenerated.

    Args:
        value: The record field's value, signed as the copybook declares it.
        binding: The column's contract, whose ``digits`` is the host variable's
            declared width.

    Returns:
        The unsigned value the host variable would hold.
    """
    magnitude = -value if value < 0 else value
    if binding.signed:  # pragma: no cover - unreachable for this table
        # Every one of this table's binary host variables is declared unsigned
        # within the group at [common/purchMT.cbl:L285-L313]; only the eight
        # scaled ones carry an ``S``. The check stands so that a dictionary
        # regeneration which introduced a signed binary field would fail loudly
        # here rather than lose its sign silently.
        raise ValueError(
            f"{binding.host_variable} is declared signed in the host-variable "
            f"group at [common/purchMT.cbl:L285-L313]; the unsigned narrowing "
            f"of anomaly N-signloss-twelve does not apply to it"
        )
    return magnitude % (10**binding.digits)


def _move_to_scaled_host_variable(
    value: Decimal, binding: _ColumnBinding
) -> Decimal:
    """Reproduce a packed-decimal field's ``MOVE`` into a ``COMP`` host variable.

    ANOMALY ``N-money-width-truncation``. The bridge's own hard-coded record
    buffer declares seven money fields ONE DIGIT WIDER than its own host
    variables: ``s9(9)v99`` at [common/purchMT.cbl:L356-L357] and in the
    ``Quarters`` and ``Purch-Unapplied`` block, against ``S9(08)V9(02)`` at
    [common/purchMT.cbl:L307-L313] - and the copybook agrees with the HOST
    VARIABLE, not with the bridge's record [copybooks/wspl.cob:L43-L52]. So a
    nine-digit value in the bridge's buffer is truncated to eight digits HERE,
    before any statement is built. The host variable is NOT widened to nine
    digits to make the disagreement go away.

    Because ``WsPurchRecord`` models the copybook, a value arriving from the
    Python record cannot exceed eight integer digits in the first place; the
    truncation is observable only through the bridge's own wider buffer. It is
    reproduced at the boundary anyway, because that is where the frozen code
    performs it and because the buffer is the thing the maintainer edits by hand.

    WHY THE DISAGREEMENT WENT UNNOTICED, and it is worth stating because it is
    the reason the frozen program still works: in ``COMP-3`` the digits are
    packed two to a byte from the right with the sign in the low nibble, so
    ``s9(8)v99`` needs ten digits plus a sign nibble - eleven nibbles, SIX bytes -
    and ``s9(9)v99`` needs eleven plus a sign - twelve nibbles, still SIX bytes.
    The two declarations are the same size. The record lengths therefore agree
    (both layouts total 300 bytes, which is what the length guard in
    ``ba012-Test-WS-Rec-Size-2`` compares), the group move that fills the
    bridge's buffer from the caller's record does not misalign a single following
    field, and every reachable value round-trips unchanged. The disagreement is
    real, latent and harmless - which is exactly the kind of finding that must be
    recorded rather than tidied away.

    Fraction digits beyond the host variable's scale are truncated toward zero,
    never rounded: a COBOL store rounds only where ``ROUNDED`` is written, and
    it is written at exactly five sites in the whole in-scope cycle, none of them
    here.

    ``PURCH-DISCOUNT`` is unsigned at all four layers - ``99v99 comp`` in the
    copybook [copybooks/wspl.cob:L30], the same in the bridge's record
    [common/purchMT.cbl:L343], ``9(02)V9(02) COMP`` at the host variable
    [common/purchMT.cbl:L294] and ``decimal(4,2) unsigned`` at the column - so
    its sign is dropped here, exactly as an unsigned receiving field requires.
    The other eight are signed at every layer and keep their sign at this
    boundary; they lose it later, at the edit window.

    Args:
        value: The record field's value.
        binding: The column's contract, carrying the host variable's digits and
            scale.

    Returns:
        The value the host variable would hold.
    """
    negative = value < 0
    magnitude = -value if negative else value
    units = int(
        magnitude.scaleb(binding.scale).to_integral_value(rounding=ROUND_DOWN)
    )
    units %= 10**binding.digits
    held = Decimal(units).scaleb(-binding.scale)
    if negative and binding.signed:
        return -held
    # An unsigned receiving field has nowhere to put the sign, so it is dropped
    # here [common/purchMT.cbl:L294] exactly as it is for the twelve binary
    # fields above.
    return held


def _move_to_character_host_variable(
    value: str, binding: _ColumnBinding
) -> str:
    """Reproduce a ``MOVE`` into an alphanumeric host variable.

    A COBOL ``MOVE`` to ``PIC X(n)`` is left-justified, space-padded on the right
    and truncated on the right. The padding matters: ``initialize
    TD-PULEDGER-REC`` [common/purchMT.cbl:L1211] has already left the field as
    spaces, and the column is ``char(n) NOT NULL``, so a short value must arrive
    padded rather than absent - see the ``NOT NULL`` invariant in the module
    docstring.

    Args:
        value: The record field's value.
        binding: The column's contract, carrying the declared width.

    Returns:
        Exactly ``binding.width`` characters.
    """
    return value[: binding.width].ljust(binding.width)


def _group_concatenation(purch: WsPurchRecord) -> str:
    """Flatten ``Purch-Address`` into the bridge's ``pic x(96)``.

    ANOMALY ``N-address-flattened``. The copybook declares a GROUP of two
    48-character fields [copybooks/wspl.cob:L23-L25]; the bridge's own record
    buffer declares the flat ``pic x(96)`` [common/purchMT.cbl:L338] with
    irregular spacing that suggests it was hand-edited, and the host variable
    follows [common/purchMT.cbl:L289]. Consequently ``PURCH-ADDR1`` and
    ``PURCH-ADDR2`` have no host variable and no column of their own - both are
    recorded in :data:`OMITTED_COPYBOOK_FIELDS`.

    A COBOL group item's value IS the concatenation of its children, so this is
    the group move the bridge performs, not an invention. The dictionary records
    the same derivation for this column, as a group concatenation whose
    expression is ``move PURCH-ADDRESS to HV-PURCH-ADDRESS``.

    Args:
        purch: The record whose address group is being flattened.

    Returns:
        Ninety-six characters: 48 of ``Purch-Addr1`` then 48 of
        ``Purch-Addr2``.
    """
    address = purch.purch_address
    return address.purch_addr1[:48].ljust(48) + address.purch_addr2[:48].ljust(
        48
    )


def _split_group_concatenation(purch: WsPurchRecord, value: str) -> None:
    """Unflatten ``HV-PURCH-ADDRESS`` back into the copybook's two fields.

    The reverse of :func:`_group_concatenation`, performed by
    ``move HV-PURCH-ADDRESS to PURCH-ADDRESS`` [common/purchMT.cbl:L1263]. In
    COBOL the group move writes 96 bytes across both children at once; in Python
    the children are separate attributes, so the 96 characters are cut at the
    boundary the copybook declares.

    Args:
        purch: The record to write into, mutated in place as the COBOL ``MOVE``
            mutates the record area.
        value: The host variable's 96 characters.
    """
    padded = value[:96].ljust(96)
    purch.purch_address.purch_addr1 = padded[:48]
    purch.purch_address.purch_addr2 = padded[48:]



# =====================================================================
# ``01 TD-PULEDGER-REC`` - THE HOST-VARIABLE GROUP
# =====================================================================


@dataclasses.dataclass(slots=True)
class HostVariables:
    """``01 TD-PULEDGER-REC`` [common/purchMT.cbl:L284-L313], field for field.

    Twenty-nine host variables, in the order the group declares them - which is
    also the table's column order, the load order and the unload order. The
    declaration uses level ``05`` directly under the ``01`` with no intervening
    ``03``, unlike ``otm3MT``; cosmetic, but recorded.

    CONSTRUCTING AN INSTANCE IS ``initialize TD-PULEDGER-REC``. Every default
    below is what ``INITIALIZE`` leaves in the field - spaces for alphanumeric,
    zero for numeric - and that statement is the FIRST statement of the load
    [common/purchMT.cbl:L1211]. It is the mechanism behind the ``NOT NULL``
    invariant the maintainer states in his own words at the head of
    ``bb100-UnloadHVs``: an unset field becomes zero or space, never SQL
    ``NULL``, so every column can be declared ``NOT NULL`` and the Python layer
    must default rather than omit.

    Storage classes, from the group's own picture clauses:

    * Seven alphanumeric fields, ``str``, space-padded to their declared width.
    * Twelve unsigned ``COMP`` fields plus ``HV-PURCH-STATUS`` and
      ``HV-PURCH-NOTES-TAG``, ``int``. Fourteen in total, all unsigned - which is
      why the twelve that are SIGNED in the copybook lose their sign here
      (``N-signloss-twelve``).
    * ``HV-PURCH-DISCOUNT``, an UNSIGNED scaled field,
      :class:`~decimal.Decimal`.
    * Eight SIGNED scaled money fields, :class:`~decimal.Decimal`. They keep
      their sign here and lose it later, at the edit window
      (``N-sign-dropped-by-edit-window``).

    No value in this class is ever a binary approximation of a real number, per
    rule R-2.
    """

    hv_purch_key: str = " " * 7
    hv_purch_status: int = 0
    hv_purch_notes_tag: int = 0
    hv_purch_name: str = " " * 30
    hv_purch_address: str = " " * 96
    hv_purch_phone: str = " " * 13
    hv_purch_ext: str = " " * 4
    hv_purch_fax: str = " " * 13
    hv_purch_email: str = " " * 30
    hv_purch_discount: Decimal = Decimal("0.00")
    hv_purch_credit: int = 0
    hv_purch_sortcode: int = 0
    hv_purch_accountno: int = 0
    hv_purch_limit: int = 0
    hv_purch_activety: int = 0
    hv_purch_last_inv: int = 0
    hv_purch_last_pay: int = 0
    hv_purch_average: int = 0
    hv_purch_create_dat: int = 0
    hv_purch_pay_activety: int = 0
    hv_purch_pay_average: int = 0
    hv_purch_pay_worst: int = 0
    hv_purch_current: Decimal = Decimal("0.00")
    hv_purch_last: Decimal = Decimal("0.00")
    hv_turnover_q1: Decimal = Decimal("0.00")
    hv_turnover_q2: Decimal = Decimal("0.00")
    hv_turnover_q3: Decimal = Decimal("0.00")
    hv_turnover_q4: Decimal = Decimal("0.00")
    hv_purch_unapplied: Decimal = Decimal("0.00")

    def value_for(self, column: str) -> str | int | Decimal:
        """Read the host variable that feeds one column.

        Args:
            column: A column name from :data:`COLUMN_ORDER`.

        Returns:
            The host variable's current value.

        Raises:
            KeyError: If the column is not one of this table's 29.
        """
        return getattr(self, _BINDING_BY_COLUMN[column].field)

    def rendered_values(self) -> tuple[str, ...]:
        """Render all 29 host variables exactly as the bridge renders them.

        This is the value half of ``bb200-Insert``
        [common/purchMT.cbl:L1292-L1676] and ``bb300-Update``
        [common/purchMT.cbl:L1682-L2071], both of which build the same 29
        assignments in the same order and differ only in the statement they wrap
        them in. Three renderings, chosen per column by its host variable's own
        storage class:

        * Alphanumeric - ``FUNCTION TRIM (HV-..., TRAILING)``.
        * Unscaled numeric - ``FUNCTION TRIM (WS-MYSQL-EDIT(w))`` for the
          column's declared window.
        * Scaled numeric - the integer window, then a literal ``"."``, then the
          UNTRIMMED two-character fraction window.

        Returns:
            Twenty-nine strings, positionally aligned with
            :data:`COLUMN_ORDER`, each the exact text the bridge would have
            placed between its two ``"`` delimiters.
        """
        rendered: list[str] = []
        for binding in _BINDINGS:
            value = getattr(self, binding.field)
            if binding.kind == "char":
                # `FUNCTION TRIM (HV-PURCH-KEY,TRAILING)`
                # [common/purchMT.cbl:L1309] and its six siblings.
                rendered.append(_trim_trailing(str(value)))
                continue
            image = _ws_mysql_edit(value)
            integer_text = _trim(
                _edit_window(image, binding.edit_start, binding.edit_length)
            )
            if binding.scale == 0:
                rendered.append(integer_text)
                continue
            # `STRING "." ... STRING WS-MYSQL-EDIT(22:02)` - the fraction window
            # is NOT trimmed [common/purchMT.cbl:L1404, L1565], so a value of
            # 12.30 renders "12" "." "30" and never "12.3".
            fraction_text = _edit_window(image, *_FRACTION_WINDOW)
            rendered.append(f"{integer_text}.{fraction_text}")
        return tuple(rendered)


#: Every binding by column name, for :meth:`HostVariables.value_for` and for the
#: statement builders.
_BINDING_BY_COLUMN: Final[Mapping[str, _ColumnBinding]] = {
    binding.column: binding for binding in _BINDINGS
}

#: The host-variable attribute names in column order, so that a fetch can be
#: written as one positional zip against the ``MySQL_fetch_record`` argument
#: list.
_HV_FIELDS: Final[tuple[str, ...]] = tuple(
    binding.field for binding in _BINDINGS
)


def bb000_hv_load(purch: WsPurchRecord) -> HostVariables:
    """``bb000-HV-Load Section.`` [common/purchMT.cbl:L1203-L1246].

    Verbatim from the section's own header [common/purchMT.cbl:L1206-L1209]::

        *>  Load the Host variables with data from the passed record
        *>
        *> This Method loads the Host Variables for the Base table with
        *> the data passed in the data-buffer.

    ``initialize TD-PULEDGER-REC.`` [common/purchMT.cbl:L1211] runs FIRST, then
    twenty-nine moves, one per column, in exactly column order
    [common/purchMT.cbl:L1212-L1240], the last of them carrying the section's
    single terminating period. Constructing a :class:`HostVariables` from its
    defaults IS the ``initialize``; the loop below is the twenty-nine moves.

    THE MOVES ARE WHERE THE SIGN AND THE DIGITS ARE LOST. Each move goes through
    :func:`_move_to_unsigned_host_variable`, :func:`_move_to_scaled_host_variable`
    or :func:`_move_to_character_host_variable`, so ``N-signloss-twelve``,
    ``N-money-width-truncation``, ``N-credit-four-widths`` and
    ``N-sortcode-narrowing`` all happen HERE - before any statement text exists,
    which is exactly where the frozen bridge performs them.

    The section closes with a comment about repeating groups
    [common/purchMT.cbl:L1242-L1243], verbatim::

        *> Loading HVs implies a non-Fetch action. RGs are handled separately for
        *> all such actions so they must not be loaded here.

    This bridge has NO repeating group, so the note describes a case that cannot
    arise - anomaly ``N-rg-comment-no-rg``. It is recorded rather than acted on.

    ``Purch-Stats-Date`` is NOT loaded. It is present in both record layouts and
    has no host variable, so there is nothing to move it into - anomaly
    ``N-stats-date-write-nowhere``, recorded in
    :data:`OMITTED_COPYBOOK_FIELDS`.

    Args:
        purch: The caller's record, read only. ``bb000`` never writes to it.

    Returns:
        The loaded host-variable group.
    """
    loaded = HostVariables()
    for binding in _BINDINGS:
        if binding.column == "PURCH-ADDRESS":
            # `move PURCH-ADDRESS to HV-PURCH-ADDRESS`
            # [common/purchMT.cbl:L1216] - a GROUP move, flattened by the
            # bridge's own record buffer [common/purchMT.cbl:L338].
            setattr(
                loaded,
                binding.field,
                _move_to_character_host_variable(
                    _group_concatenation(purch), binding
                ),
            )
            continue
        value = _record_value(purch, binding)
        if binding.kind == "char":
            setattr(
                loaded,
                binding.field,
                _move_to_character_host_variable(str(value), binding),
            )
        elif binding.kind == "int":
            # ANOMALY N-signloss-twelve for twelve of these
            # [copybooks/wspl.cob:L31-L42] -> [common/purchMT.cbl:L295-L306].
            setattr(
                loaded,
                binding.field,
                _move_to_unsigned_host_variable(int(value), binding),
            )
        else:
            # ANOMALY N-money-width-truncation
            # [common/purchMT.cbl:L356-L357] against
            # [common/purchMT.cbl:L307-L313].
            setattr(
                loaded,
                binding.field,
                _move_to_scaled_host_variable(Decimal(value), binding),
            )
    return loaded


def bb100_unload_hvs(
    host_variables: HostVariables, purch: WsPurchRecord
) -> None:
    """``bb100-UnloadHVs Section.`` [common/purchMT.cbl:L1248-L1290].

    Verbatim from the section's own header [common/purchMT.cbl:L1251-L1255]::

        *>  Load the data buffer in the interface with data from the host
        *> variables.
        *> (init moved lower)
        *>
        *> NULL fields must not be returned in the buffer. SQL filters each
        *> column to
        *>  ensure it has a proper value.  This saves using indicator variables.

    That last sentence is the maintainer's own statement of the ``NOT NULL``
    invariant, and the clearest in-repository justification for this module never
    binding ``None``.

    ``initialize Purch-REC.`` [common/purchMT.cbl:L1257] runs FIRST - a PLAIN
    initialize, where the two sites inside ``ba041`` and ``ba141`` write
    ``initialize ... with filler``. Anomaly ``N-initialize``: two ``with filler``
    against one plain, and three different casings of the record's name across
    the four sites. Each is reproduced in place and none is normalised. Here the
    plain form leaves the record's own ``filler pic x(12)``
    [copybooks/wspl.cob:L54] untouched, which is precisely the difference.

    Then twenty-nine moves, one per column, in exactly the same order as the load
    [common/purchMT.cbl:L1259-L1287].

    Args:
        host_variables: The group a fetch has just filled.
        purch: The caller's record, MUTATED IN PLACE - a COBOL ``MOVE`` writes
            into the record area the caller passed, and every caller of this
            bridge holds a reference to that area.
    """
    _initialize_purch_rec(purch, with_filler=False)
    for binding in _BINDINGS:
        value = getattr(host_variables, binding.field)
        if binding.column == "PURCH-ADDRESS":
            # `move HV-PURCH-ADDRESS to PURCH-ADDRESS`
            # [common/purchMT.cbl:L1263] - the reverse group move.
            _split_group_concatenation(purch, str(value))
            continue
        _set_record_value(purch, binding, value)
    # The `PTurnover-q occurs 4` view REDEFINES the four named quarters
    # [copybooks/wspl.cob:L50-L51], so in COBOL it is the same storage and needs
    # no move of its own. Python holds the two views as separate attributes, so
    # the alias is restored explicitly - this writes no new field and reaches no
    # column, the redefinition having neither host variable nor column.
    _refresh_quarters_view(purch)


def _record_value(
    purch: WsPurchRecord, binding: _ColumnBinding
) -> str | int | Decimal:
    """Read the record field one column is loaded from.

    Resolves the dotted attribute paths of :data:`_RECORD_ATTRIBUTES`, which
    exist because the copybook groups ``Turnover-q1`` through ``Turnover-q4``
    under ``Quarters`` [copybooks/wspl.cob:L45-L49] and the bridge does not.

    Args:
        purch: The record to read.
        binding: The column's contract.

    Returns:
        The field's value, in the copybook's own storage class.
    """
    target: object = purch
    for part in binding.attribute.split("."):
        target = getattr(target, part)
    return target  # type: ignore[return-value]


def _set_record_value(
    purch: WsPurchRecord,
    binding: _ColumnBinding,
    value: str | int | Decimal,
) -> None:
    """Write one host variable back into its record field.

    The receiving field's own storage class governs, not the host variable's:
    ``PURCH-STATUS`` is ``pic 9`` in the copybook [copybooks/wspl.cob:L18] and
    ``9(03) COMP`` at the host variable, so a value wider than the copybook field
    is truncated on the way back exactly as it was on the way out.

    Args:
        purch: The record to write into, mutated in place.
        binding: The column's contract.
        value: The host variable's value.
    """
    parts = binding.attribute.split(".")
    target: object = purch
    for part in parts[:-1]:
        target = getattr(target, part)
    setattr(target, parts[-1], _move_to_record_field(value, binding))


def _move_to_record_field(
    value: str | int | Decimal, binding: _ColumnBinding
) -> str | int | Decimal:
    """Reproduce the unload direction's ``MOVE`` - host variable INTO the record.

    ``bb100-UnloadHVs`` [common/purchMT.cbl:L1259-L1287] is twenty-nine plain
    ``MOVE`` statements, and a COBOL ``MOVE`` is governed by the RECEIVING field.
    That matters here because the drift recorded in the module docstring runs in
    both directions:

    * ``PURCH-STATUS`` and ``PURCH-NOTES-TAG`` are ``pic 9`` in the copybook
      [copybooks/wspl.cob:L18], [copybooks/wspl.cob:L21] but ``9(03) COMP`` at
      the host variable [common/purchMT.cbl:L286-L287], so a value the host
      variable can hold and the copybook cannot is truncated on the way back -
      three declared digits into one. Anomaly ``N-status-digit-narrowing``.
    * ``PURCH-CREDIT`` receives an eight-digit host variable
      [common/purchMT.cbl:L295] into a ``binary-char``
      [copybooks/wspl.cob:L31], and the ten-digit host variables
      [common/purchMT.cbl:L297-L306] land in ``binary-long`` fields
      [copybooks/wspl.cob:L33-L42]. Neither has a picture clause, so the
      receiving capacity is the C storage width, not a digit count - see
      :data:`_BINARY_STORAGE_BYTES` - and an out-of-range value wraps in two's
      complement rather than being clamped or rejected. Part of
      ``N-credit-four-widths``.
    * The seven money fields narrow the other way only in the bridge's own stale
      record buffer; the copybook and the host variable agree at eight integer
      digits [copybooks/wspl.cob:L43-L52] against
      [common/purchMT.cbl:L307-L313], so this direction is a straight store at
      scale two. ``N-money-width-truncation`` is applied on the LOAD side, where
      the frozen bridge applies it.

    Nothing here validates, clamps or rejects: rule R-3 forbids added validation,
    and a truncation that the compiled program performs silently must stay
    silent.

    Args:
        value: The host variable's value.
        binding: The column's contract, carrying the RECEIVING copybook field's
            usage, digits, scale, width and signedness.

    Returns:
        The value the copybook field would hold after the move.

    Raises:
        ValueError: If the column is the flattened address group, which has no
            single receiving field and is unloaded by
            :func:`_split_group_concatenation` instead, or if the dictionary
            reports a usage this table does not declare.
    """
    usage = binding.copybook_usage
    if usage == "ALPHANUMERIC":
        # Left-justified, space-padded, truncated on the right - and the width
        # is the COPYBOOK's, which for every character column of this table
        # equals the host variable's.
        return str(value)[: binding.copybook_width].ljust(binding.copybook_width)
    if usage in _BINARY_STORAGE_BYTES:
        # `binary-char` [copybooks/wspl.cob:L31] and `binary-long`
        # [copybooks/wspl.cob:L32-L42] carry no picture clause, so the receiving
        # capacity is the storage width. GnuCOBOL wraps such a store in two's
        # complement; it does not raise and it does not clamp.
        if binding.copybook_scale:  # pragma: no cover - no scaled binary here
            raise ValueError(
                f"{binding.column} is declared {usage} with a scale of "
                f"{binding.copybook_scale} at {binding.citation}; the "
                f"storage-width wrap models integer binary fields only"
            )
        modulus = 1 << (8 * _BINARY_STORAGE_BYTES[usage])
        wrapped = int(value) % modulus
        if wrapped >= modulus >> 1:
            wrapped -= modulus
        return wrapped
    if usage in ("DISPLAY", "COMP", "COMP-3"):
        return _store_into_picture_field(value, binding)
    # `03 Purch-Address.` [copybooks/wspl.cob:L23] is a GROUP; the bridge
    # flattened it to `pic x(96)` [common/purchMT.cbl:L338], so the unload splits
    # it across the two children rather than storing it whole.
    raise ValueError(
        f"{binding.column} has copybook usage {usage} at {binding.citation}; "
        f"it is not stored by a single MOVE"
    )


def _store_into_picture_field(
    value: str | int | Decimal, binding: _ColumnBinding
) -> int | Decimal:
    """Store a numeric value into a picture-declared receiving field.

    Covers the three picture-bearing usages this table's copybook declares -
    ``DISPLAY`` [copybooks/wspl.cob:L18], ``COMP``
    [copybooks/wspl.cob:L30] and ``COMP-3`` [copybooks/wspl.cob:L43-L52]. All
    three truncate rather than round on store, because ``ROUNDED`` is written at
    exactly five sites in the whole in-scope cycle and none of them is here, and
    all three discard high-order digits beyond the picture's digit count. No
    compile line in the repository passes a truncation flag, so the compiler's
    default applies and a field holds exactly its declared digits.

    Args:
        value: The host variable's value.
        binding: The column's contract.

    Returns:
        An ``int`` for an unscaled field, a ``Decimal`` at the field's own scale
        for a scaled one. Never a binary approximation of either.
    """
    scale = binding.copybook_scale
    digits = binding.copybook_digits
    incoming = value if isinstance(value, Decimal) else Decimal(int(value))
    negative = incoming < 0
    magnitude = -incoming if negative else incoming
    units = int(magnitude.scaleb(scale).to_integral_value(rounding=ROUND_DOWN))
    units %= 10**digits
    if scale == 0:
        # An unsigned receiving field has nowhere to put the sign; a signed one
        # keeps it. Neither of this table's unscaled picture fields is signed.
        return -units if negative and binding.copybook_signed else units
    held = Decimal(units).scaleb(-scale)
    return -held if negative and binding.copybook_signed else held


#: The record fields the copybook declares as FILLER. A COBOL ``INITIALIZE``
#: leaves FILLER alone unless ``WITH FILLER`` is written, and this bridge writes
#: both forms - ``initialize Purch-REC with filler``
#: [common/purchMT.cbl:L642] and [common/purchMT.cbl:L1149] against the plain
#: ``initialize Purch-REC.`` [common/purchMT.cbl:L1257]. Anomaly
#: ``N-initialize``: two ``with filler`` sites against one plain, and three
#: different casings of the record's name across them. Both forms are reproduced
#: in place and neither is normalised.
_RECORD_FILLER_FIELDS: Final[Mapping[str, str]] = {
    "filler_l54": "[copybooks/wspl.cob:L54]",
}

#: The record fields that REDEFINE earlier storage. ``INITIALIZE`` never touches
#: a redefining item, so the array view of the four quarters
#: [copybooks/wspl.cob:L50-L51] is skipped by both forms; its content follows
#: the storage it aliases, which :func:`_refresh_quarters_view` restores.
_RECORD_REDEFINING_FIELDS: Final[Mapping[str, str]] = {
    "quarters_view": "[copybooks/wspl.cob:L50-L51]",
}


def _initialize_purch_rec(purch: WsPurchRecord, *, with_filler: bool) -> None:
    """``initialize Purch-REC`` - with or without ``with filler``.

    Three sites in the frozen bridge initialise this record and they do NOT
    agree, which is why the form is a parameter rather than a constant:

    * ``initialize Purch-REC with filler`` [common/purchMT.cbl:L642], inside
      ``ba041-Reread`` when the fetch returns no row.
    * ``initialize Purch-Rec with filler`` [common/purchMT.cbl:L1149], the same
      statement inside ``ba141-Reread`` with the name cased differently.
    * ``initialize Purch-REC.`` [common/purchMT.cbl:L1257], plain, at the head of
      ``bb100-UnloadHVs``.

    Anomaly ``N-initialize``. The difference is observable: the plain form leaves
    the record's trailing ``filler pic x(12)`` [copybooks/wspl.cob:L54] holding
    whatever it held, while ``with filler`` sets it to spaces. The filler reaches
    no column, so the difference never appears in a table dump - but it is
    reproduced anyway, because a caller reading the record area after the call
    can see it.

    Numeric items become zero and alphanumeric items become spaces, which is what
    the record class's own declared defaults are; taking the values from those
    defaults keeps the initialised state and the dictionary in step instead of
    restating twenty-nine constants here.

    ANOMALY ``N-true-provenance``. The record these three statements initialise is
    the bridge's OWN hard-coded copy of the layout, and the note above its
    declaration [common/purchMT.cbl:L326-L329] states which source set it was
    generated from - ``C:\\prim-acas1\\SourceSets\\PULEDGER.CBF``. HERE that note
    is TRUE: this is the purchase-ledger bridge and ``PULEDGER`` is its record.
    The identical four lines appear over the four-column analysis table in
    ``analMT`` [common/analMT.cbl:L309-L312], where they are FALSE. So this file
    is the ORIGIN and ``analMT`` is the copy-paste - which turns a standing
    mystery in the sibling bridge into a documented clerical error with a named
    source. The note is NOT repeated in any other module of this layer, precisely
    because it is only true of this one.

    Args:
        purch: The record to initialise, MUTATED IN PLACE - COBOL initialises
            storage, it does not hand back a new record.
        with_filler: ``True`` for ``initialize ... with filler``, ``False`` for
            the plain form.
    """
    _initialize_group(purch, with_filler=with_filler)
    # The array view aliases storage that has just been zeroed, so it follows.
    _refresh_quarters_view(purch)


def _initialize_group(group: object, *, with_filler: bool) -> None:
    """Initialise one record or subordinate group, honouring the FILLER rule.

    Recurses into subordinate groups - ``03 Purch-Address.``
    [copybooks/wspl.cob:L23] and ``03 Quarters.`` [copybooks/wspl.cob:L45] -
    mutating each in place rather than rebinding it, because a COBOL
    ``INITIALIZE`` writes into the storage the caller already holds.

    Args:
        group: The record or group to initialise, mutated in place.
        with_filler: Whether FILLER items are included.

    Raises:
        ValueError: If a field declares neither a default nor a default factory,
            leaving no initialised value to restore.
    """
    for field_info in dataclasses.fields(group):  # type: ignore[arg-type]
        name = field_info.name
        if name in _RECORD_REDEFINING_FIELDS:
            continue
        if name in _RECORD_FILLER_FIELDS and not with_filler:
            continue
        current = getattr(group, name)
        if dataclasses.is_dataclass(current):
            _initialize_group(current, with_filler=with_filler)
            continue
        default = field_info.default
        if default is not dataclasses.MISSING:
            setattr(group, name, default)
            continue
        factory = field_info.default_factory
        if factory is not dataclasses.MISSING:
            setattr(group, name, factory())
            continue
        raise ValueError(  # pragma: no cover - every field declares one
            f"{type(group).__name__}.{name} declares no initialised value, so "
            f"`initialize` [common/purchMT.cbl:L1257] cannot be reproduced"
        )


def _refresh_quarters_view(purch: WsPurchRecord) -> None:
    """Restore the ``PTurnover-q ... occurs 4`` alias over the four quarters.

    ``03 filler redefines Quarters.`` with ``05 PTurnover-q pic s9(8)v99 comp-3
    occurs 4.`` [copybooks/wspl.cob:L50-L51] is a SECOND VIEW of the same
    storage, so in COBOL it needs no move of its own - writing ``Turnover-q1``
    IS writing ``PTurnover-q (1)``. Python holds the two views as separate
    attributes, so the alias is restored explicitly after anything writes the
    named quarters.

    This writes no new field and reaches no column: the redefinition has neither
    a host variable nor a column, and adding one would be schema evolution, which
    rule R-3 forbids. It is recorded as a deliberate omission in
    :data:`OMITTED_COPYBOOK_FIELDS`. The bridge's own stale record buffer omits
    the redefinition entirely [common/purchMT.cbl:L358], which is one more way
    that buffer and the copybook disagree.

    Note the subscript offset: COBOL ``OCCURS`` subscripts are 1-based, so
    ``PTurnover-q (1)`` is element zero of the tuple below.

    Args:
        purch: The record whose alias is restored, mutated in place.
    """
    quarters = purch.quarters
    purch.quarters_view.pturnover_q = (
        quarters.turnover_q1,
        quarters.turnover_q2,
        quarters.turnover_q3,
        quarters.turnover_q4,
    )


# ============================================================================
# THE TWO PROGRAMS' OWN WORKING STORAGE
# ============================================================================
#
# `purchMT` keeps its connection handle and its two cursor flags in WORKING
# STORAGE, so they persist between calls and are shared by every caller of the
# bridge [common/purchMT.cbl:L244-L254], [copybooks/mysql-variables.cpy via
# common/purchMT.cbl:L279]. `acas022` keeps its first-call record-length guard
# there too [common/acas022.cbl:L253-L254]. Module-level names are the exact
# analogue: ONE handle and ONE pair of cursor slots for the whole process, which
# is what the frozen program has.
#
# THIS IS NOT A CONNECTION POOL AND MUST NOT BECOME ONE. Rule R-3 forbids
# pooling outright, and Agent Action Plan section 0.2.2 is explicit - "no
# connection pooling. Execution is strictly sequential, matching the
# single-threaded COBOL." A single handle reused sequentially is the opposite of
# a pool: there is never more than one, and nothing ever hands one out
# concurrently.

#: ``01 WS-MYSQL-CONNECTION`` in the bridge's own working storage, reached
#: through ``MYSQL-1000-OPEN`` [common/purchMT.cbl:L477] and released by
#: ``MYSQL-1980-CLOSE`` [common/purchMT.cbl:L501]. ``None`` before the first
#: open and after the close, which is the state ``fs-reply not = zero`` at
#: [common/purchMT.cbl:L478] leaves behind.
_CONNECTION: object | None = None

#: ``Most-Cursor-Set`` and ``Most-Cursor-Set-2`` [common/purchMT.cbl:L246-L254],
#: the bridge's TWO cursor slots. The second's own comment reads "Special for
#: selective read next." [common/purchMT.cbl:L250] and it exists solely for the
#: name-ordered read of ``ba140``/``ba141``. They are never collapsed into one:
#: slot 1 is freed by ``ba998-Free`` [common/purchMT.cbl:L1181-L1191] and reset
#: by ``ba020-Process-Open`` [common/purchMT.cbl:L488], while slot 2 is
#: deactivated only from inside ``ba141`` itself
#: [common/purchMT.cbl:L1137, :L1154, :L1159] - anomalies
#: ``N-free-clears-slot-1-only`` and ``N-open-resets-slot-1-only``.
_CURSORS: Final[CursorStateTable] = CursorStateTable()

#: ``77 A pic 9(4) value zero`` and ``77 B pic 9(4) value zero``
#: [common/acas022.cbl:L253-L254], carrying the maintainer's own instruction:
#: "A & B used in 1st test ONLY in ba-Process-RDBMS". They are the first-call
#: latch of the record-length guard, so they live for the life of the program,
#: not the life of a call.
_WS_A: int = 0
_WS_B: int = 0


def reset_bridge_state() -> None:
    """Return both programs' working storage to its declared initial state.

    A freshly loaded COBOL program starts with ``A`` and ``B`` at zero
    [common/acas022.cbl:L253-L254], ``Cobol-File-Status`` at its declared
    ``value zero`` [common/acas022.cbl:L256], both cursor flags at zero
    [common/purchMT.cbl:L246], [common/purchMT.cbl:L252] and no connection
    handle. Python keeps a module loaded for the life of the process, so that
    starting state is reachable only by asking for it - which a test harness
    driving several scenarios through one interpreter must do between them, and
    which nothing on a production path ever needs.

    The connection handle is CLOSED rather than merely dropped, through the same
    ``MYSQL-1980-CLOSE`` path ``ba030-Process-Close`` uses
    [common/purchMT.cbl:L501], so that abandoning it cannot leave a session open
    on the server.

    THIS IS NOT A REPAIR OF ANOMALY ``N-sticky-eof``. Within one run the
    end-of-file flag still persists across calls until an open clears it, because
    the only statements that clear it are the seven ``move zero to
    Cobol-File-Status`` sites the handler issues [common/acas022.cbl:L396, :L407,
    :L472, :L496, :L541, :L554, :L566]. What this function reproduces is program
    LOAD, which in GnuCOBOL is what restores a ``77`` item to its ``VALUE``
    clause - a different event entirely, and one no caller can observe from
    inside a run.
    """
    global _CONNECTION, _WS_A, _WS_B, _COBOL_FILE_STATUS
    if _CONNECTION is not None:
        mysql_1980_close(_CONNECTION)  # type: ignore[arg-type]
        mysql_1999_exit()
        _CONNECTION = None
    _CURSORS.reset(TABLE)
    _RESULT_POINTER.free_result()
    _RESULT_POINTER.set_cursor_not_active()
    _WS_A = 0
    _WS_B = 0
    # ``77  Cobol-File-Status  pic 9  value zero.`` [common/acas022.cbl:L256].
    _COBOL_FILE_STATUS = 0


# ============================================================================
# THE ISAM SIDE OF THE HANDLER - `Purchase-File`
# ============================================================================


@runtime_checkable
class PurchaseFile(Protocol):
    """The ISAM verbs ``acas022`` issues against ``fd Purchase-File``.

    ``acas022`` is a DUAL-PATH handler: when ``FS-Cobol-Files-Used``
    [copybooks/wssystem.cob:L113] holds, it drives an indexed file declared by
    ``copy "selpl.cob"`` and ``copy "fdpl.cob"`` [common/acas022.cbl:L239,
    :L244]; otherwise it hands the call to the bridge and returns
    [common/acas022.cbl:L316-L320]. The migrated posting cycle takes the second
    path, so nothing in ``acas_posting`` supplies an implementation of this
    protocol - but the first path is reproduced rather than deleted, because
    Agent Action Plan section 0.7.2 R-5 requires that "every program map to a
    module, every paragraph to a function" and because the flat-file paragraphs
    are where several of the recorded anomalies live.

    A caller that wants the ISAM path supplies its own store. Every verb returns
    the two-character COBOL FILE STATUS as an integer - zero for success, 10 for
    ``at end``, and any other non-zero for the ``invalid key`` condition - which
    is all the handler ever tests. The handler then overwrites that status with
    its OWN hard-coded value at several sites, and those overwrites, not the
    store's status, are what the caller sees.

    ``record`` is ``01 Purch-Record`` [copybooks/fdpl.cob:L15], the FD record
    area - a SECOND record, distinct from the ``WS-Purch-Record`` the caller
    passes, which is why the handler moves between the two at every verb. The
    two layouts are field-for-field identical: same pictures, same usages, same
    order, same trailing ``filler pic x(12)``
    [copybooks/fdpl.cob:L16-L56] against [copybooks/wspl.cob:L14-L54]. That
    identity is what makes the record-length guard of
    :func:`ba012_test_ws_rec_size_2` unreachable, so it is stated here as well
    as there.
    """

    @property
    def record(self) -> WsPurchRecord:
        """``01 Purch-Record`` [copybooks/fdpl.cob:L15] - the FD record area."""

    def open_input(self) -> int:
        """``open input Purchase-File`` [common/acas022.cbl:L367]."""

    def open_io(self) -> int:
        """``open i-o Purchase-File`` [common/acas022.cbl:L375, :L380]."""

    def open_output(self) -> int:
        """``open output Purchase-File`` [common/acas022.cbl:L378, :L384]."""

    def close(self) -> int:
        """``close Purchase-File`` [common/acas022.cbl:L370, :L377, :L405]."""

    def read_next(self) -> int:
        """``read Purchase-File next record`` [common/acas022.cbl:L431].

        Returns 10 for the ``at end`` branch [common/acas022.cbl:L432].
        """

    def read_by_key(self) -> int:
        """``read Purchase-File key Purch-Key`` [common/acas022.cbl:L474].

        Reads on ``record.ws_purch_key``, which the handler has already loaded
        from the linkage record [common/acas022.cbl:L457-L458].
        """

    def start(self, access_type: int) -> int:
        """``start Purchase-File key <relation> Purch-Key``.

        One verb for all four relations the handler writes out longhand
        [common/acas022.cbl:L509, :L516, :L523, :L530], selected by
        ``Access-Type``.
        """

    def write(self) -> int:
        """``write Purch-Record`` [common/acas022.cbl:L543]."""

    def rewrite(self) -> int:
        """``rewrite Purch-Record`` [common/acas022.cbl:L567]."""

    def delete(self) -> int:
        """``delete Purchase-File record`` [common/acas022.cbl:L555]."""


class PurchaseFileNotSuppliedError(TypeError):
    """Raised when the ISAM path is entered with no ``Purchase-File`` store.

    THIS IS NOT A COBOL STATUS AND IS NOT AN ERROR THE FROZEN PROGRAM HAS. In
    COBOL the file always exists, because ``fd Purchase-File``
    [copybooks/fdpl.cob:L13] is part of the program. Reaching the flat-file
    paragraphs here with nothing to drive is a MIGRATION CONFIGURATION fault -
    the caller left ``File-System-Used`` at zero [copybooks/wssystem.cob:L112]
    while supplying no store - and there is no ``FS-Reply`` value that says so.

    It is therefore raised rather than reported, and it is the ONLY exception
    this module raises from a call path. The database path never raises, because
    ``ba015-Test-Ends`` states the contract in as many words: "Any errors leave
    it to caller to recover from" [common/acas022.cbl:L665]. Every database
    outcome comes back as an ``FS-Reply``/``WE-Error`` pair.
    """


def _require_purchase_file(
    purchase_file: PurchaseFile | None, paragraph: str
) -> PurchaseFile:
    """Return the ISAM store, or explain precisely why there is none.

    Args:
        purchase_file: The store the caller supplied, if any.
        paragraph: The COBOL paragraph being reproduced, named in the message so
            a caller can see which verb it was about to issue.

    Returns:
        The store.

    Raises:
        PurchaseFileNotSuppliedError: If no store was supplied.
    """
    if purchase_file is None:
        raise PurchaseFileNotSuppliedError(
            f"{paragraph} drives `fd Purchase-File` [copybooks/fdpl.cob:L13], "
            f"but no store was supplied. `acas022` takes this path only when "
            f"FS-Cobol-Files-Used holds [copybooks/wssystem.cob:L113]; the "
            f"migrated cycle sets File-System-Used to 1 and takes the RDBMS "
            f"path at [common/acas022.cbl:L316-L320] instead"
        )
    return purchase_file


# ============================================================================
# STATEMENT AND LOG-FIELD CONSTRUCTION
# ============================================================================

#: ``WS-Log-Where pic x(231)`` [copybooks/wsfnctn.cob:L53]. Every paragraph that
#: builds a ``WHERE`` clause copies ``WS-Where (1:J)`` into it "For test
#: logging", so the clause is truncated to this width in the log even though the
#: statement itself carries the full text.
#:
#: ``N-level-12``: the ``J`` that indexes ``WS-Where (1:J)`` is declared inside
#: ``01 subscripts usage comp-5.`` as ``12 J pic s9(4).``
#: [common/purchMT.cbl:L259-L260] - level TWELVE, where every sibling group in
#: the bridge uses 03 or 05. Level 12 is legal COBOL (any level 02..49 may
#: subordinate) and it changes nothing about the field, so it is recorded and
#: left alone rather than normalised. Python has no level numbers, so the
#: pointer is simply the length of the clause built so far.
_WS_LOG_WHERE_WIDTH: Final[int] = 231

#: ``ws-temp-ed pic 9(10)`` [common/purchMT.scb:L219], the numeric edit field two
#: paragraphs route values through. Its digit count is what makes anomaly
#: ``N-key-through-numeric-edit`` observable.
_WS_TEMP_ED_DIGITS: Final[int] = 10

#: The quoted table name, built once. ``"`PULEDGER-REC`"`` appears as a LITERAL
#: in every statement the bridge assembles [common/purchMT.cbl:L541, :L694,
#: :L843, :L940, :L1048] and in the two builders. Every identifier this module
#: emits goes through :func:`~acas_posting.dal.connection.quote_identifier`,
#: because each of this table's names carries a HYPHEN and would otherwise be a
#: syntax error rather than a name.
_QUOTED_TABLE: Final[str] = quote_identifier(TABLE)

#: The quoted primary-key column, ``"`PURCH-KEY`"``. The bridge writes it as
#: ``KeyName (KOR-x1) delimited by space`` between two backticks
#: [common/purchMT.cbl:L518-L520], which trims the 30-character key name
#: [common/purchMT.cbl:L228] at its first space.
_QUOTED_KEY_COLUMN: Final[str] = quote_identifier(KEY_OF_REFERENCE.column_name)


def _purch_rec_key(purch: WsPurchRecord) -> str:
    """``Purch-REC (K:L)`` - the key sliced out of the bridge's record buffer.

    ``K`` and ``L`` come from the key table, not from a literal:
    ``move KOR-offset (KOR-x1) to K`` and ``move KOR-length (KOR-x1) to L``
    [common/purchMT.cbl:L513-L514, :L668-L669, :L795-L796, :L913-L914,
    :L971-L972], where the table declares offset 0001 and length 0007
    [common/purchMT.scb:L228-L230].

    THE SLICE IS NOT TRIMMED. Four paragraphs place it between two ``"``
    delimiters with ``delimited by size``
    [common/purchMT.cbl:L677, :L819, :L922, :L980], so a key shorter than seven
    characters reaches the comparison with its trailing spaces intact and
    matches a ``char(7)`` column that MySQL has itself space-padded. Trimming it
    here would change which rows a read finds.

    Args:
        purch: The record whose key field is sliced.

    Returns:
        Exactly :attr:`KeyOfReference.kor_length` characters.
    """
    width = KEY_OF_REFERENCE.kor_length
    return purch.ws_purch_key[:width].ljust(width)


def _where_on_primary_key(relation: str) -> str:
    """Build ``` `PURCH-KEY`<relation>%s ``` - the one-predicate WHERE clause.

    Reproduces the ``string`` at [common/purchMT.cbl:L918-L926] and its three
    siblings, with ONE substitution the migration is required to make: the key
    VALUE travels as a bound ``%s`` placeholder rather than being formatted into
    the text between two ``"`` delimiters. That is the rule
    :func:`~acas_posting.dal.connection.execute_statement` states -
    "IDENTIFIERS MUST ALREADY BE QUOTED... Values travel as ``%s`` placeholders
    and are bound by the driver" - and it changes neither the predicate, nor the
    ordering, nor the row set.

    The clause carries exactly one predicate because the bridge's own comment
    says it cannot carry more: "The START condition cannot be compounded, and it
    must use a Key of Reference within the record. (These are COBOL rules...)"
    [common/purchMT.scb:L239-L241].

    Args:
        relation: The comparison, already in the bridge's spelling - ``"="`` for
            the three exact-match paragraphs, or one of the five
            :class:`~acas_posting.dal.cursor_state.MostRelation` tokens for a
            start.

    Returns:
        The clause text, with one placeholder.
    """
    return f"{_QUOTED_KEY_COLUMN}{relation}%s"


def _stored_rows(cursor: object) -> tuple[Mapping[str, object], ...]:
    """Materialise a result set, reproducing ``MYSQL-1220-STORE-RESULT``.

    ``ba040``, ``ba050``, ``ba060`` and ``ba140`` each issue
    ``PERFORM MYSQL-1220-STORE-RESULT THRU MYSQL-1239-EXIT`` immediately after
    the query [common/purchMT.cbl:L546, :L699, :L848, :L1053] and then
    ``MOVE WS-MYSQL-RESULT TO TP-PULEDGER-REC``, parking the WHOLE result in the
    bridge's own result pointer. The row count that every status test reads,
    ``WS-MYSQL-Count-Rows``, is a property of that materialised set - so it must
    be materialised here too, rather than streamed, or the count would not exist
    when the tests need it.

    Rows arrive from the driver as sequences, because
    :func:`~acas_posting.dal.connection.execute_statement` yields a plain
    cursor; they are zipped with the cursor's own column names so that every
    later access is by COLUMN NAME. A driver that returns mappings already is
    passed through untouched, which keeps a test double free to use either
    shape.

    Args:
        cursor: The cursor a statement has just been executed on.

    Returns:
        Every row, in the order the server returned them.
    """
    description = getattr(cursor, "description", None) or ()
    names = tuple(str(column[0]) for column in description)
    rows: list[Mapping[str, object]] = []
    fetch_one = getattr(cursor, "fetchone")
    while True:
        row = fetch_one()
        if row is None:
            break
        if isinstance(row, Mapping):
            rows.append(dict(row))
            continue
        rows.append(dict(zip(names, tuple(row), strict=False)))
    return tuple(rows)


def _log_where(file_access: FileAccess, clause: str) -> None:
    """``move WS-Where (1:J) to WS-Log-Where.`` "For test logging".

    Reproduced at [common/purchMT.cbl:L532, :L682, :L829, :L928, :L985, :L1039],
    and cleared at [common/purchMT.cbl:L584] and [common/purchMT.cbl:L1091].
    Truncated to the receiving field's own 231 characters
    [copybooks/wsfnctn.cob:L53].

    Args:
        file_access: The block whose logging data is written.
        clause: The clause text, or the empty string for the ``move spaces``
            form.
    """
    file_access.logging_data.ws_log_where = clause[:_WS_LOG_WHERE_WIDTH].ljust(
        _WS_LOG_WHERE_WIDTH
    )


def _file_key(file_access: FileAccess, text: str) -> None:
    """``move <literal> to WS-File-Key`` - the 64-character log key.

    Every site's literal is reproduced verbatim, truncated and space-padded to
    ``pic x(64)`` [copybooks/wsfnctn.cob:L52] exactly as a COBOL ``MOVE`` to an
    alphanumeric field would: ``"OPEN PULedger"``
    [common/purchMT.cbl:L487], ``"CLOSE PULedger"``
    [common/purchMT.cbl:L496], ``"0000000"`` [common/purchMT.cbl:L549, :L1056],
    ``"No Data"`` [common/purchMT.cbl:L567, :L1074], ``"EOF"``
    [common/purchMT.cbl:L629, :L1136], ``"EOF2"``
    [common/purchMT.cbl:L643, :L1150], ``"EOF3"``
    [common/purchMT.cbl:L653, :L1160], and the two counted forms at
    [common/purchMT.cbl:L572-L576] and [common/purchMT.cbl:L1079-L1083].

    Args:
        file_access: The block whose logging data is written.
        text: The literal, or the empty string for the ``move spaces`` form.
    """
    file_access.logging_data.ws_file_key = _ws_file_key(text)


def _count_rows_file_key(count: int, suffix: str) -> str:
    """Build the counted log key of ``ba040`` and ``ba140``.

    ``move WS-MYSQL-Count-Rows to WS-Temp-Ed`` then
    ``string "> 0 got cnt=" WS-Temp-ED " recs"``
    [common/purchMT.cbl:L571-L576]. ``WS-Temp-Ed`` is ``pic 9(10)``
    [common/purchMT.scb:L219] and is placed ``delimited by size``, so the count
    appears with its FULL TEN DIGITS including leading zeros - a count of two
    renders ``> 0 got cnt=0000000002 recs``, not ``cnt=2``. The name of the
    field says "edited" but the picture carries no editing symbol, so no
    suppression happens.

    Args:
        count: ``WS-MYSQL-Count-Rows``.
        suffix: ``" recs"`` for ``ba040`` [common/purchMT.cbl:L574], or
            ``" recs in NAME order"`` for ``ba140``
            [common/purchMT.cbl:L1081].

    Returns:
        The log key text, before the receiving field truncates it.
    """
    return f"> 0 got cnt={count % (10**_WS_TEMP_ED_DIGITS):010d}{suffix}"


def _through_ws_temp_ed(key_text: str) -> str:
    """``move HV-Purch-Key to ws-temp-ed`` - ANOMALY ``N-key-through-numeric-edit``.

    ``ba050`` alone routes the key through a NUMERIC field on its way to the log
    key: ``move HV-Purch-Key to ws-temp-ed.`` then
    ``move ws-temp-ed to WS-File-Key`` [common/purchMT.cbl:L771-L772]. Its five
    sibling paragraphs move the key straight across
    [common/purchMT.cbl:L658, :L830, :L885, :L968, :L1165], so this is a
    one-paragraph deviation rather than a house style.

    ``HV-Purch-Key`` is ``PIC X(7)`` [common/purchMT.cbl:L285] and
    ``ws-temp-ed`` is ``pic 9(10)`` [common/purchMT.scb:L219], so the move is
    alphanumeric into numeric-display: the sending item is aligned on the
    receiving item's assumed decimal point and the high-order positions are
    zero-filled, which turns a key of ``A123456`` into ``000A123456``. A
    non-digit character in a numeric-display field is not a value the standard
    defines, so what the compiled program stores for a key like that is an
    OPEN QUESTION recorded as ``Q-purch-numeric-lowkey`` in
    ``docs/migration/ambiguity-resolutions.md``. The byte-level right-alignment
    reproduced here is what GnuCOBOL performs, and it is applied without
    validation because rule R-3 forbids adding any.

    Args:
        key_text: The seven-character key from the host variable.

    Returns:
        The ten-character image ``ws-temp-ed`` would hold.
    """
    return key_text.rjust(_WS_TEMP_ED_DIGITS, "0")[-_WS_TEMP_ED_DIGITS:]


#: The three fields ``call "MySQL_errno"``, ``call "MySQL_sqlstate"`` and
#: ``call "MySQL_error"`` return when the statement itself SUCCEEDED. The bridge
#: tests ``WS-MYSQL-Error-Number not = "0  "`` at seven sites
#: [common/purchMT.cbl:L560, :L638, :L753, :L895, :L950, :L996, :L1067] and the
#: whole point of the test is that a query which returned no rows is not an
#: error, so the client reports success. ``"0  "`` is the literal the frozen
#: source compares against, three characters wide.
_ERRNO_SUCCESS: Final[str] = "0  "
_SQLSTATE_SUCCESS: Final[str] = "00000"


def _driver_error_fields(error: BaseException | None) -> tuple[str, str, str]:
    """Render the three client-library queries as ``(errno, sqlstate, message)``.

    Reproduces the inline triple every failure path of this bridge issues -
    ``call "MySQL_errno" using WS-MYSQL-Error-Number``,
    ``call "MySQL_sqlstate" using WS-MYSQL-SQLstate`` and, only when the first
    reports a real error, ``call "MySQL_error" using WS-MYSQL-Error-Message``
    [common/purchMT.cbl:L557-L563]. Note that this bridge calls them INLINE at
    every site and never performs ``MYSQL-1100-DB-ERROR``, so that copybook
    paragraph's own status mapping is deliberately not used here.

    Fields are read off the exception with :func:`getattr` rather than by
    importing the driver's exception class, which keeps this module free of a
    driver import it does not otherwise need and lets a test double raise
    anything. The message is passed through
    :func:`~acas_posting.dal.status.redact_for_log` because the client builds it
    out of material that can include the account, the host and key values from
    the data, and can carry a line break that would let a failure forge a second
    log record.

    Args:
        error: The exception the driver raised, or ``None`` for a statement that
            succeeded and simply matched no row.

    Returns:
        ``(errno, sqlstate, message)`` - all three exactly as the host variables
        would hold them.
    """
    if error is None:
        return _ERRNO_SUCCESS, _SQLSTATE_SUCCESS, ""
    errno = str(getattr(error, "errno", "") or "").ljust(3)[:5]
    sqlstate = str(getattr(error, "sqlstate", "") or "").ljust(5)[:5]
    return errno, sqlstate, redact_for_log(str(error))


def _move_sql_state(file_access: FileAccess, sqlstate: str) -> None:
    """``move WS-MYSQL-SqlState to SQL-State`` - unconditional at all seven sites.

    Every zero-row and every failure path moves the client's SQL state across
    BEFORE testing the error number [common/purchMT.cbl:L559, :L637, :L752,
    :L894, :L949, :L995, :L1066], so the state is reported even on the paths
    that decide the statement did not really fail. Truncated to ``pic x(5)``
    [copybooks/wsfnctn.cob:L51].

    Args:
        file_access: The block whose logging data is written.
        sqlstate: The five-character state.
    """
    file_access.logging_data.sql_state = sqlstate[:5].ljust(5)


def _move_sql_error(
    file_access: FileAccess, errno: str, message: str
) -> None:
    """``move WS-MYSQL-Error-Number to SQL-Err`` and the message to ``SQL-Msg``.

    The pair the bridge moves only inside ``if WS-MYSQL-Error-Number not = "0  "``
    [common/purchMT.cbl:L561-L563]. ``SQL-Err`` is ``pic x(5)`` and ``SQL-Msg``
    is ``pic x(512)`` [copybooks/wsfnctn.cob:L49-L50], so both truncate.

    Args:
        file_access: The block whose logging data is written.
        errno: The client's error number.
        message: The client's message, already redacted.
    """
    logging_data = file_access.logging_data
    logging_data.sql_err = errno[:5].ljust(5)
    logging_data.sql_msg = message[:512].ljust(512)


def _clear_sql_error(file_access: FileAccess) -> None:
    """``move spaces to SQL-Msg`` and ``move zero to SQL-Err``.

    The success-path clear of ``ba080`` [common/purchMT.cbl:L959-L960],
    ``ba090`` [common/purchMT.cbl:L1006-L1007] and ``ba070``'s entry
    [common/purchMT.cbl:L887-L888]. ``move zero`` to an alphanumeric field
    stores the single character ``0`` left-justified and space-fills the rest, so
    ``SQL-Err`` becomes ``"0    "`` and NOT five zeros - which is why the
    error-number test that reads it compares against ``"0  "`` rather than zero.

    Args:
        file_access: The block whose logging data is written.
    """
    logging_data = file_access.logging_data
    logging_data.sql_err = "0".ljust(5)
    logging_data.sql_msg = " " * 512


def _status(file_access: FileAccess, fs_reply: int, we_error: int) -> None:
    """Write the status pair every paragraph reports through.

    ``FS-Reply`` is ``pic 99`` and ``WE-Error`` is ``pic 999``
    [copybooks/wsfnctn.cob:L23-L25], so both are stored as integers within those
    widths. NOTHING IS RAISED: ``ba015-Test-Ends`` states the contract - "Any
    errors leave it to caller to recover from" [common/acas022.cbl:L665].

    Args:
        file_access: The block whose status pair is written.
        fs_reply: The value the frozen source moves to ``FS-Reply``.
        we_error: The value the frozen source moves to ``WE-Error``.
    """
    file_access.fs_reply = int(fs_reply) % 100
    file_access.we_error = int(we_error) % 1000


def _stamp(file_access: FileAccess, paragraph: int) -> None:
    """``move <n> to ws-No-Paragraph`` - the per-paragraph trace number.

    ``pic 999`` [copybooks/wsfnctn.cob:L48]. The bridge's numbers run 1 to 22
    with gaps [common/purchMT.cbl:L476, :L495, :L533, :L585, :L686, :L708,
    :L835, :L889, :L932, :L969, :L1040, :L1092, :L1182] and the handler's run
    201 to 208 [common/acas022.cbl:L365, :L403, :L420, :L470, :L493, :L538,
    :L549, :L562] - a scheme four sibling handlers share exactly, recorded as
    ``N-noparagraph-collision``.

    Args:
        file_access: The block whose logging data is written.
        paragraph: The number the frozen source moves.
    """
    file_access.logging_data.ws_no_paragraph = int(paragraph) % 1000


def _trace(message: str, *arguments: object) -> None:
    """``display Display-Message-1 with erase eos`` - gated on ``Testing-2``.

    Agent Action Plan section 0.3.4 settles the treatment: "Diagnostic displays
    with no database effect become log records at a severity matching the
    original's intent. They must not alter control flow and must not appear in
    any table dump." Six sites display the assembled ``WHERE`` clause under
    ``if Testing-2`` [common/purchMT.cbl:L550-L552, :L683-L685, :L831-L833,
    :L929-L931, :L988-L990, :L1057-L1059]; the switch itself is
    ``SW-Testing-2``, which the frozen copybook leaves at zero
    [copybooks/Test-Data-Flags.cob:L15].

     THE EIGHT CALL SITES ARE PRESERVED AND THIS FUNCTION EMITS NOTHING.
    Every one of them passes the assembled ``WHERE`` clause or the whole statement -
    for this table a predicate carrying ``PURCH-KEY``, the supplier code, as a
    literal, and an INSERT or UPDATE naming every one of the twenty-nine columns and
    its value. The safe-event schema in :mod:`acas_posting.dal.status` admits no SQL
    text and no record key (CWE-532), and no redaction can help: escaping a
    statement's control characters leaves the statement.

    The function, its eight call sites and the ``Testing-2`` guard around each are
    all kept, so a reader following the frozen source still finds every ``display``
    and finds what it now does. The clause itself is still BUILT and still stored in
    ``WS-Log-Where``, because the bridge's own statements read it - the disposition
    is unchanged (R-3). Nothing acts on this trace operationally: it was a
    developer's own, read at the terminal beside the running program, and the frozen
    copybook leaves its switch at zero.

    Args:
        message: A printf-style template, retained so every call site still records
            which paragraph displayed what.
        *arguments: Its arguments, evaluated by the caller and then discarded here -
            no argument is rendered, so nothing can leak by accident.
    """
    del message, arguments


# ============================================================================
# THE BRIDGE PROGRAM - `purchMT`
# ============================================================================
# `PROCEDURE DIVISION using File-Access ACAS-DAL-Common-data Purch-Rec.`
# [common/purchMT.cbl:L385-L387] - THREE parameters, in that order, with the
# third annotated by the maintainer as "Ws record".
#
# `ba-ACAS-DAL-Process section.` [common/purchMT.cbl:L389] opens with terminal
# geometry - `accept ws-env-lines from lines`, two `set ENVIRONMENT` calls for
# screen exception handling, and the arithmetic that derives `ws-99-lines` and
# `ws-98-lines` [common/purchMT.cbl:L390-L401]. All of it exists to size the
# error panel this bridge would draw, none of it touches a table, and Agent
# Action Plan section 0.2.2 excludes "report formatting beyond database effects"
# along with the whole presentation layer. It is therefore a DELIBERATE OMISSION,
# recorded here rather than silently dropped, and it is the reason `purch_mt`
# begins at `ba010-Initialise`.


def purchmt_ba010_initialise(file_access: FileAccess) -> None:
    """``ba010-Initialise.`` [common/purchMT.cbl:L403-L445].

    Clears SEVEN fields [common/purchMT.cbl:L408-L414]::

        move     spaces to WS-MYSQL-Error-Message
                            WS-MYSQL-Error-Number
                            WS-Log-Where
                            WS-File-Key
                            SQL-Msg
                            SQL-Err
                            SQL-State.

    ANOMALY ``N-bridge-clears-sqlstate``. The bridge clears all three SQL fields
    including ``SQL-State``; its own caller ``acas022`` clears only TWO,
    ``move spaces to SQL-Err SQL-Msg.`` [common/acas022.cbl:L336]. So a stale
    ``SQL-State`` survives the handler and is then cleared by the bridge - which
    means the handler's omission is invisible on the RDBMS path and visible only
    on the pure-COBOL-files path, where the bridge never runs. Both behaviours
    are reproduced exactly as written and neither is aligned to the other.

    THE STATUS PAIR IS DELIBERATELY NOT CLEARED. Immediately above the clear the
    maintainer commented it out [common/purchMT.cbl:L405-L406]::

        *>     move     zero   to We-Error
        *>                        Fs-Reply.

    which is the same deliberate non-initialisation as
    [common/acas022.cbl:L334-L335]. The caller's incoming pair therefore survives
    into the paragraph that runs next, and ``ba041``'s sticky test at
    [common/purchMT.cbl:L651] depends on exactly that - see
    :func:`purchmt_ba041_reread` and anomaly ``N-sticky-eof``.

    Two comments record work that was removed rather than done
    [common/purchMT.cbl:L416-L417]: "Now Test for valid key for start,
    read-indexed and delete / REMOVED as not used here". The key-number guard
    exists ONLY in the handler [common/acas022.cbl:L298-L312]; a caller reaching
    the bridge directly is not guarded at all.

    Args:
        file_access: The block whose logging data is cleared.
    """
    logging_data = file_access.logging_data
    # `move spaces to ... WS-Log-Where ... ` - the first two receivers,
    # WS-MYSQL-Error-Message and WS-MYSQL-Error-Number, are the bridge's own
    # working storage rather than anything the caller can see, and are held in
    # the local variables of the paragraphs that read them.
    _log_where(file_access, "")
    _file_key(file_access, "")
    logging_data.sql_msg = " " * 512
    logging_data.sql_err = " " * 5
    logging_data.sql_state = " " * 5


def purchmt_ba020_process_open(
    file_access: FileAccess,
    *,
    system_record: SystemRecord | None,
    transport: TransportSecurity | None,
) -> None:
    """``ba020-Process-Open.`` [common/purchMT.cbl:L447-L489].

    Six ``string`` statements copy the connection settings out of ``RDB-Data``,
    each ``delimited by space`` and each terminated with an explicit
    ``X"00"`` for the C interface [common/purchMT.cbl:L452-L475] - schema, host,
    user, password, port and socket, in that order. Those six moves are
    reproduced inside
    :func:`~acas_posting.dal.connection.connection_parameters`, whose own
    documentation carries the field-by-field mapping; calling the shared open is
    therefore performing them, not skipping them, and it keeps the transport
    policy and the pinned numeric converter in one place.

    Then the trace stamp, ``PERFORM MYSQL-1000-OPEN THRU MYSQL-1090-EXIT``, and
    the early exit [common/purchMT.cbl:L476-L479]::

        move     1 to ws-No-Paragraph.
        PERFORM  MYSQL-1000-OPEN  THRU MYSQL-1090-EXIT.
        if       fs-reply not = zero
                 go   to ba999-end.

    On success the log key becomes ``"OPEN PULedger"`` - note the casing - and
    ``move zero to Most-Cursor-Set`` [common/purchMT.cbl:L487-L488].

    ANOMALY ``N-open-resets-slot-1-only``. Only the FIRST cursor flag is reset.
    ``Most-Cursor-Set-2`` [common/purchMT.cbl:L252] is left exactly as the last
    ``ba140``/``ba141`` walk left it, so a re-open in the same run can find slot
    2 still marked active over a result that the closed connection destroyed.
    The asymmetry is reproduced, not corrected; it is the companion of
    ``N-free-clears-slot-1-only``.

    A commented-out ``/MYSQL INIT\\`` directive block sits between the two
    [common/purchMT.cbl:L481-L485]. It carries literal connection credentials
    for the maintainer's own development machine, which is why they are cited
    rather than transcribed anywhere in this module - and why the live path takes
    its settings from ``RDB-Data`` instead.

    Args:
        file_access: The block whose status and logging data are written.
        system_record: The record the handler loaded ``RDB-Data`` from at
            [common/acas022.cbl:L641-L646]. When ``None`` it is reconstructed
            from ``RDB-Data`` itself, because the bridge holds nothing else.
        transport: The transport-security policy for the driver, passed straight
            through to the shared open.
    """
    global _CONNECTION
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba020-Process-Open"])
    source = (
        system_record
        if system_record is not None
        else _system_record_from_rdb_data(file_access)
    )
    outcome = mysql_1090_exit(
        mysql_1000_open(
            source,
            ws_no_paragraph=file_access.logging_data.ws_no_paragraph,
            we_error=file_access.we_error,
            transport=transport,
        )
    )
    _status(file_access, outcome.fs_reply, outcome.we_error)
    _stamp(file_access, outcome.ws_no_paragraph)
    logging_data = file_access.logging_data
    logging_data.sql_err = outcome.sql_err[:5].ljust(5)
    logging_data.sql_msg = outcome.sql_msg[:512].ljust(512)
    logging_data.sql_state = outcome.sql_state[:5].ljust(5)
    if file_access.fs_reply != int(FsReply.SUCCESS):
        # `if fs-reply not = zero go to ba999-end.`
        # [common/purchMT.cbl:L478-L479] - AAP 0.4.2 Class 2, a forward
        # terminator to the common exit. The handle stays as it was, which for a
        # failed open is `None`.
        _CONNECTION = outcome.connection
        return
    _CONNECTION = outcome.connection
    # `move "OPEN PULedger" to WS-File-Key` [common/purchMT.cbl:L487].
    _file_key(file_access, "OPEN PULedger")
    # `move zero to Most-Cursor-Set` [common/purchMT.cbl:L488] - SLOT 1 ONLY.
    # ANOMALY N-open-resets-slot-1-only: slot 2 is untouched here.
    _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT).set_cursor_not_active()
    # `go to ba999-end.` [common/purchMT.cbl:L489] - Class 2.


def _system_record_from_rdb_data(file_access: FileAccess) -> SystemRecord:
    """Rebuild the six connection settings a system record carries.

    THE BRIDGE NEVER SEES A SYSTEM RECORD. Its three parameters are
    ``File-Access``, ``ACAS-DAL-Common-data`` and the record buffer
    [common/purchMT.cbl:L385-L387], and it reads its connection settings from the
    ``RDB-Data`` group inside the first of those
    [copybooks/wsfnctn.cob:L56-L62], which the handler filled from the system
    record on its first call [common/acas022.cbl:L641-L646].

    :func:`~acas_posting.dal.connection.mysql_1000_open` takes the system record,
    so this inverts those six moves - a lossless round trip, because they are the
    only six fields the open reads. It exists so that ``purch_mt`` can be called
    with EXACTLY the bridge's three parameters and still open a connection,
    which is what the frozen program does.

    Args:
        file_access: The block carrying ``RDB-Data``.

    Returns:
        A system record carrying those six settings and nothing else.
    """
    rdb_data = file_access.rdb_data
    rebuilt = SystemRecord()
    block = rebuilt.system_data_block
    # The inverse of [common/acas022.cbl:L641-L646], field for field.
    block.rdbms_db_name = rdb_data.db_schema
    block.rdbms_user = rdb_data.db_uname
    block.rdbms_passwd = rdb_data.db_upass
    block.rdbms_port = rdb_data.db_port
    block.rdbms_host = rdb_data.db_host
    block.rdbms_socket = rdb_data.db_socket
    return rebuilt


def purchmt_ba030_process_close(file_access: FileAccess) -> None:
    """``ba030-Process-Close.`` [common/purchMT.cbl:L491-L503].

    Verbatim [common/purchMT.cbl:L492-L503]::

        if      Cursor-Active
                perform ba998-Free.

        move     2 to ws-No-Paragraph.
        move    "CLOSE PULedger" to WS-File-Key.
              PERFORM MYSQL-1980-CLOSE THRU MYSQL-1999-EXIT
        go      to ba999-end.

    Note the ORDER: the free comes BEFORE the stamp, so a close that frees a
    cursor reports paragraph 19 from inside ``ba998-Free``
    [common/purchMT.cbl:L1182] and then overwrites it with 2. Reproduced as
    written.

    ANOMALY ``N-free-clears-slot-1-only``, second half. The test is
    ``Cursor-Active``, which is slot 1's condition name
    [common/purchMT.cbl:L248]. A run that left slot 2 active
    [common/purchMT.cbl:L1077] closes the connection WITHOUT freeing it, and
    ``ba020`` will not reset it either. The result is reproduced rather than
    repaired.

    Args:
        file_access: The block whose status and logging data are written.
    """
    global _CONNECTION
    if _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT).cursor_active():
        # `perform ba998-Free.` [common/purchMT.cbl:L493] - a PERFORM, so
        # control returns here rather than falling into `ba999-end`.
        purchmt_ba998_free(file_access)
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba030-Process-Close"])
    _file_key(file_access, "CLOSE PULedger")
    # `PERFORM MYSQL-1980-CLOSE THRU MYSQL-1999-EXIT`
    # [common/purchMT.cbl:L501]. Unconditional - it runs whether or not a
    # connection was ever opened, and the shared close tolerates `None` for
    # exactly that reason.
    mysql_1980_close(_CONNECTION)  # type: ignore[arg-type]
    mysql_1999_exit()
    _CONNECTION = None
    # `go to ba999-end.` [common/purchMT.cbl:L503] - Class 2.


def _host_variables_from_row(row: Mapping[str, object]) -> HostVariables:
    """``CALL "MySQL_fetch_record" USING WS-MYSQL-RESULT`` and its 29 arguments.

    The fetch names all twenty-nine host variables positionally, in column order
    [common/purchMT.cbl:L593-L625, :L715-L747, :L1099-L1132], so each column's
    value lands in the host variable declared for it
    [common/purchMT.cbl:L285-L313]. That is a MOVE into a picture-declared
    receiving field, so it is routed through the same three coercion helpers the
    load side uses - a value arrives from the driver already inside the column's
    own range, but the host variable's picture still governs, and going through
    the helpers is what guarantees the fetch and the load agree.

    A missing column is not a case the fetch has: every statement this bridge
    issues is ``SELECT *`` over a table whose 29 columns are all ``NOT NULL``, so
    the row is complete by construction and the initialised host variable is
    never left in place. A column that is somehow absent keeps its initialised
    value - zero or spaces, never ``None`` - which is the invariant
    ``bb100-UnloadHVs`` states in its own header.

    Args:
        row: One row, keyed by column name.

    Returns:
        The host-variable group the fetch would have filled.
    """
    fetched = HostVariables()
    for binding in _BINDINGS:
        if binding.column not in row:
            continue
        value = row[binding.column]
        if binding.kind == "char":
            setattr(
                fetched,
                binding.field,
                _move_to_character_host_variable(
                    "" if value is None else str(value), binding
                ),
            )
            continue
        if value is None:
            continue
        if binding.kind == "int":
            setattr(
                fetched,
                binding.field,
                _move_to_unsigned_host_variable(int(value), binding),  # type: ignore[arg-type]
            )
            continue
        setattr(
            fetched,
            binding.field,
            _move_to_scaled_host_variable(
                value if isinstance(value, Decimal) else Decimal(str(value)),
                binding,
            ),
        )
    return fetched


def purchmt_ba040_process_read_next(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba040-Process-Read-Next.`` [common/purchMT.cbl:L505-L578].

    The paragraph's own header states the design
    [common/purchMT.cbl:L507-L509]::

        *>   Here a SELECT first then fetch if no cursor active using lowest
        *>    possible key of "0000000"
        *>           [ PURCH-KEY ]

    So the whole body is wrapped in ``if Cursor-Not-Active``
    [common/purchMT.cbl:L511] and the paragraph FALLS THROUGH into ``ba041``
    whether or not it ran - which is why a read with a live cursor issues no
    statement at all.

    The positioning statement takes its relation and its low key from the frozen
    text, ``" >= "`` [common/purchMT.cbl:L521] and ``'"0000000"'``
    [common/purchMT.cbl:L522], both held as data by ``dal/cursor_state.py`` so
    that the per-bridge disagreement survives as data. It orders by the key of
    reference ascending [common/purchMT.cbl:L523-L527].

    ANOMALY ``N-scb-comment-copypaste``. The inline comment on the statement
    reads ``*> PURCH-KEY > "0000000" ORDER BY PURCH-NAME ASC``
    [common/purchMT.cbl:L543] - and every part of it is wrong for THIS
    paragraph: the relation is ``>=`` and not ``>``, and the ordering is by
    ``PURCH-KEY`` and not by ``PURCH-NAME``. It is the comment belonging to
    ``ba140``, pasted here; the same text appears on both SELECT directives in
    the translator source [common/purchMT.scb:L497] and
    [common/purchMT.scb:L892]. The comment is recorded, not corrected, and the
    code below follows the CODE.

    Three log keys are written in sequence on the opening path - ``"0000000"``
    [common/purchMT.cbl:L549], then either ``"No Data"``
    [common/purchMT.cbl:L567] or the counted form
    [common/purchMT.cbl:L572-L576]. On the counted path the paragraph then
    performs ``ba999-End`` [common/purchMT.cbl:L577] "log it" - a PERFORM, so
    control comes back and the common exit runs a SECOND time after ``ba041``.
    The bridge therefore logs TWICE for one cursor-opening read, which is
    reproduced.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record. Untouched here; ``ba041`` writes it.
        dal_common: The logging switches [copybooks/Test-Data-Flags.cob].
        connection: The open handle the statement is issued on.
    """
    state = _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT)
    if state.cursor_not_active():
        # `set KOR-x1 to 1` and the offset/length moves
        # [common/purchMT.cbl:L512-L514]; both come from the key table rather
        # than from a literal.
        relation = _SEQUENTIAL_START.relation.padded.strip()
        clause = (
            f"{_QUOTED_KEY_COLUMN} {relation} %s"
            f" ORDER BY {_QUOTED_KEY_COLUMN} ASC"
        )
        _log_where(file_access, clause)
        _stamp(
            file_access, BRIDGE_PARAGRAPH_NUMBERS["ba040-Process-Read-Next"]
        )
        statement = (
            f"SELECT * FROM {_QUOTED_TABLE} WHERE {clause};"
        )
        _RESULT_POINTER.most_relation = _SEQUENTIAL_START.relation
        rows, error = _mysql_1210_command_then_store(
            connection, statement, (_SEQUENTIAL_START.low_key,), file_access
        )
        # `MOVE WS-MYSQL-RESULT TO TP-PULEDGER-REC`
        # [common/purchMT.cbl:L547] - the ONE shared result pointer.
        count = _RESULT_POINTER.store_result(rows)
        # `move "0000000" to WS-File-Key` [common/purchMT.cbl:L549] - written
        # BEFORE the row-count test, so it survives only on the counted path.
        _file_key(file_access, _SEQUENTIAL_START.low_key)
        if dal_common.sw_testing_2 == 1:
            _trace("purchMT ba040: %s", clause)
        if count == 0:
            # [common/purchMT.cbl:L556-L569]. The three client queries run, the
            # SQL state is stored unconditionally, and the error number and text
            # only when the client reports a real failure.
            errno, sqlstate, message = _driver_error_fields(error)
            _move_sql_state(file_access, sqlstate)
            if errno != _ERRNO_SUCCESS:
                _move_sql_error(file_access, errno, message)
            fs_reply, we_error = end_of_file_status()
            _status(file_access, fs_reply, we_error)
            _file_key(file_access, "No Data")
            # `go to ba999-End` [common/purchMT.cbl:L568] - Class 2 forward
            # terminator. It does NOT fall through into `ba041`.
            return
        # `set Cursor-Active to true` [common/purchMT.cbl:L570], whose own
        # comment reads "should test if select worked first??????".
        state.set_cursor_active()
        _file_key(file_access, _count_rows_file_key(count, " recs"))
        # `perform ba999-End` [common/purchMT.cbl:L577] "log it" - a PERFORM,
        # not a transfer, so control returns and the common exit runs again
        # after `ba041`.
        purchmt_ba999_end(file_access, dal_common)
    # Fall-through into `ba041-Reread` [common/purchMT.cbl:L580], made explicit.
    purchmt_ba041_reread(file_access, purch, dal_common)


def purchmt_ba041_reread(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
) -> None:
    """``ba041-Reread.`` [common/purchMT.cbl:L580-L660].

    "If here cursor is set (even from start), so get the next row"
    [common/purchMT.cbl:L582]. THE PARAGRAPH ISSUES NO STATEMENT: it fetches from
    the result the opening SELECT already stored, which is why a walk of N rows
    runs one query and N fetches.

    Four exits, in the order the frozen source tests them, and each with its own
    log tag:

    1. ``return-code = -1`` - the fetch found no further row
       [common/purchMT.cbl:L627-L632]. Status ``(10, 10)``, tag ``"EOF"``,
       cursor deactivated.
    2. ``WS-MYSQL-Count-Rows = zero`` [common/purchMT.cbl:L634-L649]. The client
       triple runs, and ONLY when it reports a real failure does the paragraph
       ``initialize Purch-REC with filler`` and set the tag ``"EOF2"`` - so the
       caller's record is WIPED on a fetch failure but left alone on a clean end
       of data. Status ``(10, 10)`` either way.
    3. ANOMALY ``N-sticky-eof`` - ``if fs-reply = 10``
       [common/purchMT.cbl:L651-L655], tag ``"EOF3"``. The value tested is the
       CALLER'S OWN incoming ``FS-Reply``, because ``ba010-Initialise``
       deliberately does not clear the pair [common/purchMT.cbl:L405-L406]. A
       caller that has not reset ``FS-Reply`` since its last end of file gets end
       of file again, from a cursor that had a row waiting - and the cursor is
       deactivated, so the row is lost. Reproduced exactly.
    4. Otherwise ``bb100-UnloadHVs``, the key into the log field, and
       ``move zero to fs-reply WE-Error`` - BOTH fields
       [common/purchMT.cbl:L657-L659].

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record, written by the unload on the success path and
            wiped on the ``"EOF2"`` path.
        dal_common: The logging switches, unused on this path and accepted so
            that every paragraph of the bridge takes the same shape.
    """
    state = _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT)
    # `move spaces to WS-Log-Where.` [common/purchMT.cbl:L584] - the fetch has
    # no clause of its own, so the previous paragraph's is cleared rather than
    # left to be logged twice.
    _log_where(file_access, "")
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba041-Reread"])
    # `move zero to return-code.` [common/purchMT.cbl:L586], immediately before
    # the fetch that sets it.
    row = _RESULT_POINTER.fetch_record()
    if row is None:
        # `if return-code = -1` [common/purchMT.cbl:L627-L631].
        fs_reply, we_error = end_of_file_status()
        _status(file_access, fs_reply, we_error)
        _file_key(file_access, "EOF")
        state.set_cursor_not_active()
        return  # `go to ba999-End` - Class 2.
    if _RESULT_POINTER.count_rows == 0:  # pragma: no cover - a row implies a count
        # [common/purchMT.cbl:L634-L648]. Unreachable while a row was returned,
        # and reproduced because the frozen source tests it in this order.
        errno, sqlstate, message = _driver_error_fields(None)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _move_sql_error(file_access, errno, message)
            _initialize_purch_rec(purch, with_filler=True)
            _file_key(file_access, "EOF2")
        fs_reply, we_error = end_of_file_status()
        _status(file_access, fs_reply, we_error)
        state.set_cursor_not_active()
        return  # `go to ba999-End` - Class 2.
    if file_access.fs_reply == int(FsReply.END_OF_FILE):
        # ANOMALY N-sticky-eof [common/purchMT.cbl:L651-L655]. The row just
        # fetched is discarded and the cursor deactivated.
        state.set_cursor_not_active()
        _file_key(file_access, "EOF3")
        return  # `go to ba999-End` - Class 2.
    # `perform bb100-UnloadHVs.` [common/purchMT.cbl:L657].
    bb100_unload_hvs(_host_variables_from_row(row), purch)
    # `move HV-Purch-Key to WS-File-Key.` [common/purchMT.cbl:L658] - a DIRECT
    # move, unlike `ba050` which routes the same value through a numeric field.
    _file_key(file_access, str(row.get(KEY_OF_REFERENCE.column_name, "")))
    # `move zero to fs-reply WE-Error.` [common/purchMT.cbl:L659] - both.
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `go to ba999-end.` [common/purchMT.cbl:L660] - Class 2.


def _issue_query(
    connection: object,
    statement: str,
    parameters: Sequence[object],
) -> tuple[tuple[Mapping[str, object], ...], BaseException | None]:
    """``PERFORM MYSQL-1210-COMMAND`` then ``MYSQL-1220-STORE-RESULT``.

    One statement, one materialised result, and the driver's failure captured
    rather than raised - because every one of this bridge's paragraphs decides
    for itself what a failure means, and several decide it means nothing. The
    broad ``except`` reproduces that: the frozen source does not inspect the
    exception class, it asks the client library three questions afterwards
    [common/purchMT.cbl:L557-L563] and branches on the ERROR NUMBER alone.

    Args:
        connection: The open handle.
        statement: One statement, identifiers quoted and values as ``%s``.
        parameters: The values to bind, in the statement's order.

    Returns:
        ``(rows, error)`` - the materialised result and the exception, if any.
        A failure yields no rows, which is what makes every caller's
        ``WS-MYSQL-Count-Rows`` test fire.
    """
    try:
        with execute_statement(connection, statement, parameters) as cursor:  # type: ignore[arg-type]
            return _stored_rows(cursor), None
    except Exception as error:  # any driver error takes this path - see above
        return (), error


def _issue_command(
    connection: object,
    statement: str,
    parameters: Sequence[object],
) -> tuple[int, BaseException | None]:
    """``PERFORM MYSQL-1210-COMMAND THRU MYSQL-1219-EXIT`` for a non-query.

    The write, delete and rewrite paragraphs all test
    ``WS-MYSQL-COUNT-ROWS not = 1`` afterwards
    [common/purchMT.cbl:L891, :L946, :L992], which for a statement that returns
    no result set is the AFFECTED-ROW count. The driver reports it as
    ``cursor.rowcount``.

    Args:
        connection: The open handle.
        statement: One statement, identifiers quoted and values as ``%s``.
        parameters: The values to bind, in the statement's order.

    Returns:
        ``(affected rows, error)``. A failure yields a count of zero, so the
        ``not = 1`` test fires exactly as it does in the frozen source.
    """
    try:
        with execute_statement(connection, statement, parameters) as cursor:  # type: ignore[arg-type]
            affected = getattr(cursor, "rowcount", 0)
            return (0 if affected is None or affected < 0 else int(affected)), None
    except Exception as error:  # any driver error takes this path - see above
        return 0, error


def _mysql_1100_db_error(
    file_access: FileAccess, error: BaseException, statement: str
) -> None:
    """``Mysql-1100-Db-Error`` [copybooks/mysql-procedures.cpy:L96-L128].

    The shared failure paragraph that every statement in this bridge reaches
    through :func:`_mysql_1210_command`. It runs BEFORE the calling paragraph's
    own row-count test, so on any driver failure the status pair is already
    ``(22, unchanged)`` for a duplicate or ``(99, 911)`` for everything else by
    the time that test executes - and the calling paragraph then overwrites it
    with its own value. Two consequences worth stating, because neither is
    visible from the calling paragraph alone:

    * ``ba070-Process-Write`` never assigns ``We-Error`` at all
      [common/purchMT.cbl:L891-L907], so a hard insert failure reports
      ``We-Error 911`` from HERE, not the zero its own entry set at
      [common/purchMT.cbl:L886].
    * ``ba080`` and ``ba090`` overwrite the pair with ``(99, 995)`` and
      ``(99, 994)`` [common/purchMT.cbl:L954-L955, :L1000-L1001], so a DUPLICATE
      on a delete or a rewrite is reported as a SQLSTATE failure rather than as
      22. Both are reproduced by letting this run first and the paragraph run
      second, exactly as the ``PERFORM`` order does.

    The mapping itself - including anomaly N3, in which every non-duplicate
    failure is reported as ``We-Error 911`` regardless of its actual cause -
    belongs to :func:`~acas_posting.dal.status.mysql_1100_db_error` and is not
    duplicated here.

    Args:
        file_access: The block whose status pair and diagnostic fields are
            written, mutated in place as the COBOL ``MOVE`` statements do.
        error: The driver failure standing in for the three foreign calls
            ``MySQL_errno``, ``MySQL_error`` and ``MySQL_sqlstate``.
        statement: The statement text that failed. The duplicate test reads its
            first six characters only.
    """
    errno, sqlstate, message = _driver_error_fields(error)
    outcome = mysql_1100_db_error(
        errno=errno,
        message=message,
        sql_state=sqlstate,
        command=statement,
        we_error=int(file_access.we_error),
    )
    # `move 22 to fs-Reply` / `move 99 to fs-Reply` and `move 911 to We-Error`
    # [copybooks/mysql-procedures.cpy:L103, :L127-L128].
    _status(file_access, int(outcome.fs_reply), int(outcome.we_error))
    outcome.apply_to_logging_data(file_access.logging_data)


def _mysql_1210_command(
    connection: object,
    statement: str,
    parameters: Sequence[object],
    file_access: FileAccess,
) -> tuple[int, BaseException | None]:
    """``Mysql-1210-Command`` thru ``Mysql-1219-Exit``.

    [copybooks/mysql-procedures.cpy:L164-L181]. Issue the statement; on a
    non-zero return code perform :func:`_mysql_1100_db_error`
    [copybooks/mysql-procedures.cpy:L176]; then, UNCONDITIONALLY, take the
    affected-row count [copybooks/mysql-procedures.cpy:L178].

    ANOMALY ``N-select-through-command``. ``purchMT`` never performs
    ``Mysql-1200-Select`` at all - a census of its statement sites finds
    ``MYSQL-1210-COMMAND`` at every one of the eight
    [common/purchMT.cbl:L545, :L698, :L847, :L944, :L1052, :L1675, :L2069],
    including all four SELECTs, even though the copybook supplies a select
    paragraph for exactly that purpose
    [copybooks/mysql-procedures.cpy:L147-L153]. The observable difference is the
    extra ``call "MySQL_affected_rows"``, whose value the immediately following
    ``Mysql-1220-Store-Result`` overwrites with ``MySQL_num_rows``
    [copybooks/mysql-procedures.cpy:L191-L192] - so the choice is inconsequential
    on the read paths and is recorded rather than corrected.

    ANOMALY ``N-lock-ladder-dead``, inherited. The lock-retry ladder
    ``Mysql-1300-DB-Error`` that this paragraph was written to call is commented
    out at its only call site [copybooks/mysql-procedures.cpy:L167-L175], so a
    table-lock error is reported as a plain failure and never retried. Nothing
    in this module reintroduces it; note in particular that the ladder's own
    body calls ``CBL_OC_NANOSLEEP`` and ``C$SLEEP``
    [copybooks/mysql-procedures.cpy:L225-L242], which a migrated module must not
    do in any case.

    Args:
        connection: The open handle.
        statement: The assembled statement, identifiers already quoted.
        parameters: The values bound in place of the text the COBOL embeds.
        file_access: The block the failure path writes to.

    Returns:
        The affected-row count and the driver failure, if there was one. The
        count is zero on failure, which is what makes each caller's
        ``not = 1`` and ``= zero`` tests fire.
    """
    affected, error = _issue_command(connection, statement, parameters)
    if error is not None:
        _mysql_1100_db_error(file_access, error, statement)
    return affected, error


def _mysql_1210_command_then_store(
    connection: object,
    statement: str,
    parameters: Sequence[object],
    file_access: FileAccess,
) -> tuple[tuple[Mapping[str, object], ...], BaseException | None]:
    """``MYSQL-1210-COMMAND`` followed by ``MYSQL-1220-STORE-RESULT``.

    The pair every read paragraph in this bridge performs back to back
    [common/purchMT.cbl:L545-L546, :L698-L699, :L847-L848, :L1052-L1053].
    ``Mysql-1220-Store-Result`` performs the shared failure paragraph a SECOND
    time when the result handle comes back null
    [copybooks/mysql-procedures.cpy:L189-L190], then replaces the count with
    ``MySQL_num_rows`` [copybooks/mysql-procedures.cpy:L191-L192]. Reproduced by
    materialising the rows once: a failed statement yields no rows, so the
    count-zero branch of the calling paragraph fires exactly as it would.

    Args:
        connection: The open handle.
        statement: The assembled statement, identifiers already quoted.
        parameters: The values bound in place of the text the COBOL embeds.
        file_access: The block the failure path writes to.

    Returns:
        The materialised rows and the driver failure, if there was one.
    """
    rows, error = _issue_query(connection, statement, parameters)
    if error is not None:
        # `perform Mysql-1100-Db-Error` from the command paragraph
        # [copybooks/mysql-procedures.cpy:L176] and again from the store
        # paragraph [copybooks/mysql-procedures.cpy:L190] - performing it twice
        # writes the same three fields twice, so once here is equivalent.
        _mysql_1100_db_error(file_access, error, statement)
    return rows, error


def purchmt_ba050_process_read_indexed(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba050-Process-Read-Indexed.`` [common/purchMT.cbl:L662-L774].

    "Now do on correct key within WHERE / Sets up key and compare data"
    [common/purchMT.cbl:L664-L665]. One equality predicate on the key of
    reference [common/purchMT.cbl:L671-L681], the SELECT, then the fetch - and
    ``ba998-Free`` on EVERY exit, success included
    [common/purchMT.cbl:L706, :L760, :L767, :L774].

    THREE DISTINCT NOT-FOUND STATUSES, none of them the handler's:

    * ``move 23 to fs-Reply`` with ``move zero to WE-Error``
      [common/purchMT.cbl:L703-L706], carrying the maintainer's own note that it
      "could also be 21 or 14". ANOMALY ``N-readindexed-23``: the HANDLER's own
      flat-file path reports 21 for the same condition
      [common/acas022.cbl:L475], so the two halves of one handler disagree about
      what "not found" is, and which the caller sees depends on which store it
      configured.
    * ``(23, 990)`` when the fetch found nothing AND the client reported an error
      [common/purchMT.cbl:L753-L760].
    * ``(23, 989)`` when the fetch found nothing and the client reported none
      [common/purchMT.cbl:L761-L767], with ``move zero to SQL-Err``.

    ANOMALY ``N-readindexed-frees-walk-cursor``. Because the free is
    unconditional and the result pointer is shared
    (``N-single-result-pointer-two-cursors``), a read-indexed issued in the middle
    of a ``ba040`` walk discards that walk's stored rows and clears its flag, so
    the walk silently restarts from the low key on its next call. Reproduced.

    ANOMALY ``N-key-through-numeric-edit`` [common/purchMT.cbl:L771-L772]: the
    successful path is the only one in the bridge that routes the key through
    ``ws-temp-ed``, a ``pic 9(10)`` field, on its way to the log key.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record; its key field supplies the predicate and the
            unload writes the rest of it back.
        dal_common: The logging switches.
        connection: The open handle.
    """
    key_value = _purch_rec_key(purch)
    clause = _where_on_primary_key("=")
    _log_where(file_access, clause)
    if dal_common.sw_testing_2 == 1:
        _trace("purchMT ba050: %s", clause)
    _stamp(
        file_access,
        BRIDGE_PARAGRAPH_NUMBERS["ba050-Process-Read-Indexed-select"],
    )
    statement = f"SELECT * FROM {_QUOTED_TABLE} WHERE {clause};"
    rows, error = _mysql_1210_command_then_store(
        connection, statement, (key_value,), file_access
    )
    count = _RESULT_POINTER.store_result(rows)
    if count == 0:
        # [common/purchMT.cbl:L703-L707]. NOTE that no client query runs here at
        # all - the SQL fields keep whatever `ba010-Initialise` left, which is
        # spaces, so a driver failure on this path is reported as a plain
        # not-found with no diagnostic whatsoever.
        _status(file_access, FsReply.KEY_NOT_FOUND, WeError.SUCCESS)
        # `go to ba998-Free` [common/purchMT.cbl:L706] - AAP 0.4.2 Class 4, a
        # sibling that does work and then falls through to the common exit.
        purchmt_ba998_free(file_access)
        return
    _stamp(
        file_access,
        BRIDGE_PARAGRAPH_NUMBERS["ba050-Process-Read-Indexed-fetch"],
    )
    row = _RESULT_POINTER.fetch_record()
    if row is None or _RESULT_POINTER.count_rows <= 0:
        # `if WS-MYSQL-Count-Rows not > zero` [common/purchMT.cbl:L749], whose
        # own trailing comment reads "row count zero should show up as a MYSQL
        # error ?".
        errno, sqlstate, message = _driver_error_fields(error)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _status(file_access, FsReply.KEY_NOT_FOUND, WeError.UNKNOWN_UNEXPECTED)
            _move_sql_error(file_access, errno, message)
            _file_key(file_access, "")
        else:
            _status(
                file_access,
                FsReply.KEY_NOT_FOUND,
                WeError.READ_INDEXED_UNEXPECTED,
            )
            # `move zero to SQL-Err` and `move spaces to SQL-Msg`
            # [common/purchMT.cbl:L764-L765].
            _clear_sql_error(file_access)
            _file_key(file_access, "")
        purchmt_ba998_free(file_access)  # Class 4.
        return
    # `perform bb100-UnloadHVs` [common/purchMT.cbl:L770].
    bb100_unload_hvs(_host_variables_from_row(row), purch)
    # ANOMALY N-key-through-numeric-edit [common/purchMT.cbl:L771-L772].
    _file_key(
        file_access,
        _through_ws_temp_ed(str(row.get(KEY_OF_REFERENCE.column_name, ""))),
    )
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `go to ba998-Free.` [common/purchMT.cbl:L774] - Class 4. The successful
    # read frees the result too, which is what makes this verb destructive to an
    # in-progress walk.
    purchmt_ba998_free(file_access)


def purchmt_ba060_process_start(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba060-Process-Start.`` [common/purchMT.cbl:L776-L879].

    The parameter guard comes FIRST [common/purchMT.cbl:L780-L784]::

        if       access-type < 5 or > 8                   *> not using not < or not >
                 move 99 to FS-Reply
                 move 997 to WE-Error                     *> Invalid calling parameter settings     997
                 go to ba999-end
        end-if

    ANOMALY ``N-start-guard-998-vs-997``. The handler's own flat-file start
    rejects the identical condition with 998 and leaves ``FS-Reply`` untouched
    [common/acas022.cbl:L500-L502]; the bridge uses 997 and sets both. Two
    different reports for one input error, in one handler.

    ANOMALY ``N-access-type-9-dead-in-bridge``. The relation ``evaluate``
    [common/purchMT.cbl:L800-L811] carries a ``when 9`` arm for
    ``fn-not-greater-than``, annotated "not currently used in ACAS" - and it is
    unreachable, because the guard above rejects 9 before the ``evaluate`` runs.
    There is also NO ``when other``, so an out-of-range value would leave
    ``MOST-Relation`` as spaces and build a syntactically invalid predicate; the
    guard is the only thing preventing it.

    ANOMALY ``N-asc-trailing-spaces``. The ordering fragment here is
    ``' ASC  '`` with TWO trailing spaces [common/purchMT.cbl:L825] where
    ``ba040`` and ``ba140`` write ``' ASC'`` [common/purchMT.cbl:L527, :L1034].
    The trailing spaces are inside the ``WS-Where`` text and so reach the
    statement, which SQL ignores - but they also reach ``WS-Log-Where``, where
    they are visible.

    ANOMALY ``N-start-silent-noop`` [common/purchMT.cbl:L856-L878]. When the
    select matches no row AND the client reports no error, the paragraph writes
    NEITHER status field and falls straight through to the common exit, so the
    caller's incoming pair is what it sees. A start that positioned nothing can
    therefore look like a start that succeeded.

    On success it reports ``(0, 0)`` and rewrites the log key with the relation,
    the key and the row count [common/purchMT.cbl:L869-L877] - and note that the
    relation and the key are placed there WITHOUT ``delimited by space``
    [common/purchMT.cbl:L871-L872], so all three characters of the relation and
    all seven of the key appear, padding included.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record; its key field supplies the predicate.
        dal_common: The logging switches.
        connection: The open handle.
    """
    access_type = int(file_access.access_type)
    if (
        access_type < int(AccessType.EQUAL_TO)
        or access_type > int(AccessType.NOT_LESS_THAN)
    ):
        # [common/purchMT.cbl:L780-L784]. ANOMALY N-start-guard-998-vs-997.
        _status(file_access, FsReply.ERROR, WeError.ACCESS_TYPE_WRONG)
        return  # `go to ba999-end` - Class 2. NO statement is issued.
    # `if Cursor-Active perform ba998-Free.` [common/purchMT.cbl:L788-L789] -
    # "First clear any active cursors", and again slot 1 only.
    if _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT).cursor_active():
        purchmt_ba998_free(file_access)
    # `move spaces to MOST-Relation.` then the `evaluate`
    # [common/purchMT.cbl:L798-L811]. The mapping is `MostRelation`'s, which is
    # the same five arms held as data.
    relation = MostRelation.for_access_type(access_type)
    _RESULT_POINTER.most_relation = relation
    key_value = _purch_rec_key(purch)
    clause = (
        f"{_QUOTED_KEY_COLUMN}{relation.padded.strip()}%s"
        f" ORDER BY {_QUOTED_KEY_COLUMN} ASC  "
    )
    _log_where(file_access, clause)
    # `move Purch-REC (K:L) to WS-File-Key` [common/purchMT.cbl:L830], written
    # before the select and overwritten on the counted path only.
    _file_key(file_access, key_value)
    if dal_common.sw_testing_2 == 1:
        _trace("purchMT ba060: %s", clause)
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba060-Process-Start"])
    statement = f"SELECT * FROM {_QUOTED_TABLE} WHERE {clause};"
    rows, error = _mysql_1210_command_then_store(
        connection, statement, (key_value,), file_access
    )
    count = _RESULT_POINTER.store_result(rows)
    slot = _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT)
    if count != 0:
        # `if WS-MYSQL-Count-Rows not zero set Cursor-Active to true`
        # [common/purchMT.cbl:L852-L854] - a SEPARATE test from the one below, so
        # the flag is set before the status is decided.
        slot.set_cursor_active()
    if count == 0:
        errno, sqlstate, message = _driver_error_fields(error)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _move_sql_error(file_access, errno, message)
            # `move 21 to fs-reply` with the maintainer's note "this may need
            # changing for val in WE-Error!!", then `move zero to WE-Error`
            # [common/purchMT.cbl:L864-L865].
            _status(file_access, FsReply.INVALID_KEY_ON_START, WeError.SUCCESS)
            return  # `go to ba999-End` [common/purchMT.cbl:L866] - Class 2.
        # ANOMALY N-start-silent-noop: no status is written on this path at all.
        # Control reaches `go to ba999-end` [common/purchMT.cbl:L879] with the
        # caller's incoming pair intact.
        return
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `string MOST-relation Purch-Rec (K:L) " got =" WS-Temp-ED " recs"`
    # [common/purchMT.cbl:L871-L876]. Neither the relation nor the key is
    # `delimited by space`, so both carry their padding. Note also the third
    # casing of the record's name, `Purch-Rec`, in a paragraph that spells it
    # `Purch-REC` twice above.
    _file_key(
        file_access,
        f"{relation.padded}{key_value} got ="
        f"{count % (10**_WS_TEMP_ED_DIGITS):010d} recs",
    )
    # `go to ba999-end.` [common/purchMT.cbl:L879] - Class 2.


def purchmt_ba070_process_write(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba070-Process-Write.`` [common/purchMT.cbl:L883-L908].

    Verbatim entry [common/purchMT.cbl:L884-L890]::

        perform  bb000-HV-Load.                       *>  move Purch-REC fields to HV fields
        move     Purch-Key to WS-File-Key.
        move     zero to FS-Reply WE-Error
        move     spaces to SQL-Msg
        move     zero to SQL-Err
        move     10 to ws-No-Paragraph.
        perform  bb200-Insert.

    ANOMALY ``N-write-masked-failure`` [common/purchMT.cbl:L891-L907]. The
    failure test is nested TWO deep::

        if       WS-MYSQL-COUNT-ROWS not = 1
                 ...
                 if    WS-MYSQL-Error-Number  not = "0  "
                       ... move 22 / move 99 to fs-reply

    so an insert that affected some number of rows other than one WITHOUT the
    client reporting an error leaves ``FS-Reply`` at the zero set on entry. The
    caller is told the write succeeded. The status is set only in the inner
    branch, and only there.

    The duplicate-key test is the three-way one
    [common/purchMT.cbl:L899-L901] - error 1062, error 1022, or SQL state
    ``23000`` - which is exactly what
    :func:`~acas_posting.dal.status.is_duplicate_key_bridge_level` implements. A
    duplicate reports 22; anything else reports 99, under the maintainer's note
    "this may need changing for val in WE-Error!!". ``WE-Error`` is NEVER assigned
    by this paragraph - and it does NOT stay at the zero its own entry set,
    because ``Mysql-1210-Command`` has already performed the shared failure
    paragraph by then and left 911 there
    [copybooks/mysql-procedures.cpy:L176, :L128]. So a hard insert failure is
    reported as ``(99, 911)``, "Rdb Error during initializing", whatever actually
    went wrong; see :func:`_mysql_1100_db_error`.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record, read into the host variables.
        dal_common: The logging switches.
        connection: The open handle.
    """
    host_variables = bb000_hv_load(purch)
    # `move Purch-Key to WS-File-Key.` [common/purchMT.cbl:L885] - the bridge's
    # own record key, not the host variable.
    _file_key(file_access, _purch_rec_key(purch))
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `move spaces to SQL-Msg` then `move zero to SQL-Err`
    # [common/purchMT.cbl:L887-L888]. SQL-State is NOT cleared here.
    _clear_sql_error(file_access)
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba070-Process-Write"])
    affected, error = bb200_insert(
        host_variables, file_access, dal_common, connection=connection
    )
    if affected != 1:
        errno, sqlstate, message = _driver_error_fields(error)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _move_sql_error(file_access, errno, message)
            if is_duplicate_key_bridge_level(
                file_access.logging_data.sql_err,
                file_access.logging_data.sql_state,
            ):
                # `move 22 to fs-reply` [common/purchMT.cbl:L902].
                file_access.fs_reply = int(FsReply.DUPLICATE_KEY)
            else:
                # `move 99 to fs-reply` [common/purchMT.cbl:L904].
                file_access.fs_reply = int(FsReply.ERROR)
        # ANOMALY N-write-masked-failure: when the client reports no error the
        # `if` above does nothing, and the zero set on entry stands.
    # `go to ba999-End.` [common/purchMT.cbl:L908] - Class 2.


def purchmt_ba080_process_delete(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba080-Process-Delete.`` [common/purchMT.cbl:L910-L963].

    One equality predicate on the key of reference
    [common/purchMT.cbl:L916-L926], then the delete.

    ANOMALY ``N-delete-no-semicolon``. The statement is assembled WITHOUT a
    terminator [common/purchMT.cbl:L938-L943]::

        INITIALIZE WS-MYSQL-COMMAND
        STRING "DELETE FROM "
          "`PULEDGER-REC`"
          " WHERE "
          WS-Where (1:J)
          X"00" INTO WS-MYSQL-COMMAND

    Every other statement in this bridge appends ``";" X"00"``
    [common/purchMT.cbl:L544, :L697, :L846, :L1051] and the two builders do the
    same. This one appends only the null terminator. Reproduced.

    THIS IS THE ONLY ``DELETE`` IN THE WHOLE BRIDGE, and it deletes exactly one
    row by primary key. There is no delete-all path anywhere, which corroborates
    from the bridge's side what the handler shows from its own: there is no
    ``Open-Output`` block in ``acas022`` at all, so an open with
    ``Access-Type = 3`` is a plain open and MUST NOT remove any row - anomaly
    ``N-noopenoutput``. The coercion two sibling handlers perform, replacing the
    function with a delete-all, is deliberately not ported.

    The failure path reports ``(99, 995)`` [common/purchMT.cbl:L954-L955] and,
    like the write, only inside the inner ``if`` - so a delete that removed some
    number of rows other than one without a client error still reports success
    through the ``move zero to FS-Reply WE-Error`` at
    [common/purchMT.cbl:L962]. Note the ELSE branch clears the SQL pair
    [common/purchMT.cbl:L959-L960], and note that the outer ``go to ba999-End``
    at [common/purchMT.cbl:L957] skips that final clear entirely.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record; its key field supplies the predicate.
        dal_common: The logging switches.
        connection: The open handle.
    """
    key_value = _purch_rec_key(purch)
    clause = _where_on_primary_key("=")
    # `move Purch-REC (K:L) to WS-File-Key.` [common/purchMT.cbl:L927], before
    # the log clause, unlike every sibling.
    _file_key(file_access, key_value)
    _log_where(file_access, clause)
    if dal_common.sw_testing_2 == 1:
        _trace("purchMT ba080: %s", clause)
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba080-Process-Delete"])
    # No terminating `;` - ANOMALY N-delete-no-semicolon.
    statement = f"DELETE FROM {_QUOTED_TABLE} WHERE {clause}"
    affected, error = _mysql_1210_command(
        connection, statement, (key_value,), file_access
    )
    if affected != 1:
        errno, sqlstate, message = _driver_error_fields(error)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _move_sql_error(file_access, errno, message)
            _status(
                file_access, FsReply.ERROR, WeError.DELETE_SQLSTATE_NOT_00000
            )
        # `go to ba999-End` [common/purchMT.cbl:L957] - Class 2. It leaves the
        # status pair alone when the client reported no error, so a delete that
        # matched nothing reports whatever the caller came in with.
        return
    # The ELSE branch [common/purchMT.cbl:L959-L960].
    _clear_sql_error(file_access)
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `go to ba999-End.` [common/purchMT.cbl:L963] - Class 2.


def purchmt_ba090_process_rewrite(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba090-Process-Rewrite.`` [common/purchMT.cbl:L965-L1008].

    ``bb000-HV-Load`` first, "Load up the HV fields from table record in WS"
    [common/purchMT.cbl:L967], then the log key, the stamp, the key predicate and
    ``bb300-Update``.

    ANOMALY ``N-rewrite-no-entry-clear``. Unlike the write, which zeroes the
    status pair and the SQL pair on entry [common/purchMT.cbl:L886-L888], this
    paragraph clears NOTHING before issuing the update
    [common/purchMT.cbl:L967-L986]. The clear happens only on the success path
    [common/purchMT.cbl:L1005-L1007]. So a rewrite that fails carries the
    caller's previous ``SQL-Err`` and ``SQL-Msg`` into its own report unless the
    inner branch overwrites them.

    ANOMALY ``N-rewrite-masked-failure``, the same two-deep nesting as the write
    [common/purchMT.cbl:L992-L1004]: an update that affected some number of rows
    other than one without a client error reports nothing at all - and because of
    ``N-rewrite-no-entry-clear`` it does not even reset the pair first. The
    failure status is ``(99, 994)``.

    ANOMALY ``N-update-key-trim-split``. The ``WHERE`` clause here is built from
    the UNTRIMMED record slice, exactly as the read and the delete build theirs
    [common/purchMT.cbl:L980]; but ``bb300-Update`` appends it to the statement
    through ``FUNCTION TRIM (WS-Where (1:J))``, so the assembled statement is
    trimmed while the logged clause is not.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record, read into the host variables.
        dal_common: The logging switches.
        connection: The open handle.
    """
    host_variables = bb000_hv_load(purch)
    key_value = _purch_rec_key(purch)
    _file_key(file_access, key_value)
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba090-Process-Rewrite"])
    clause = _where_on_primary_key("=")
    _log_where(file_access, clause)
    affected, error = bb300_update(
        host_variables,
        clause,
        key_value,
        file_access,
        dal_common,
        connection=connection,
    )
    if dal_common.sw_testing_2 == 1:
        # `if Testing-2 display` comes AFTER the update here
        # [common/purchMT.cbl:L988-L990], where every sibling displays before it.
        _trace("purchMT ba090: %s", clause)
    if affected != 1:
        errno, sqlstate, message = _driver_error_fields(error)
        _move_sql_state(file_access, sqlstate)
        if errno != _ERRNO_SUCCESS:
            _move_sql_error(file_access, errno, message)
            _status(
                file_access, FsReply.ERROR, WeError.REWRITE_SQLSTATE_NOT_00000
            )
        # `go to ba999-End` [common/purchMT.cbl:L1003] - Class 2.
        return
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    _clear_sql_error(file_access)
    # `go to ba999-End.` [common/purchMT.cbl:L1008] - Class 2.


def purchmt_ba140_process_read_next(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    connection: object,
) -> None:
    """``ba140-Process-Read-Next.`` [common/purchMT.cbl:L1010-L1085].

    THE VERB THE AGENT BRIEF SAYS DOES NOT EXIST. The brief states that function
    code 31 "falls through into ``when 3``, so ``fn-Read-By-Name`` is handled by
    exactly the same paragraph as an ordinary Read-Next - no name-ordered read,
    no different SQL, nothing", and instructs that a name-ordered read must NOT
    be implemented. That is true of the HANDLER
    [common/acas022.cbl:L343-L345] and false of the BRIDGE, which is the program
    the migrated cycle actually runs. The bridge's own dispatch routes 31 to its
    own paragraph [common/purchMT.cbl:L441-L442]; the paragraph's opening comment
    reads "Like 040 except we do order by PURCH-NAME"
    [common/purchMT.cbl:L1012]; the ``ORDER BY`` names ``PURCH-NAME``
    [common/purchMT.cbl:L1031-L1034]; it drives the SECOND cursor flag
    [common/purchMT.cbl:L1018, :L1077]; and it stamps its own trace numbers 21
    and 22 [common/purchMT.cbl:L1040, :L1092]. Recorded as ANOMALY
    ``N-31-two-meanings``: one function code, two different behaviours, chosen by
    which store the system record is configured for. Both are reproduced - the
    handler's fold in :func:`aa040_process_read_next`'s dispatch, the bridge's
    name-ordered walk here.

    ANOMALY ``N-lowkey-quoting-split``. ``ba040`` writes its low key as
    ``'"0000000"'`` and so lands ``"0000000"`` WITH quotes in the statement
    [common/purchMT.cbl:L522]; this paragraph writes ``"0000000"``, a COBOL
    literal, and so lands the bare token ``0000000``
    [common/purchMT.cbl:L1029]. Against a ``char(7)`` column MySQL coerces the
    unquoted numeric to a string, giving the same comparison - but the two
    statement texts differ, and one of them is not portable. Reproduced by
    inlining :data:`_NAME_ORDER_LOW_KEY` here and binding it in ``ba040``.

    ANOMALY ``N-scb-comment-copypaste``, second instance. The comment beside the
    assembled clause claims ``PURCH-KEY > "0000000" ORDER BY PURCH-NAME ASC``
    [common/purchMT.cbl:L1050] while the code builds ``>=``
    [common/purchMT.cbl:L1028] - and ``ba040`` carries the IDENTICAL comment
    [common/purchMT.cbl:L543] over a clause that orders by ``PURCH-KEY``, so in
    ``ba040`` the same text is wrong about the ordering too.

    The ordering column is UNINDEXED - the frozen schema declares one key on this
    table and no secondary index [mysql/ACASDB.sql:L676]. ``ORDER BY`` on
    ``PURCH-NAME`` is therefore a filesort, and rows sharing a name have no
    defined relative order. That is a genuine non-determinism in the frozen
    design; it is not repaired here, and it is why AAP section 0.6.6's claim of
    "no ordering nondeterminism from a secondary index" holds only because no
    in-scope program calls this verb.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record, filled by the fetch that follows.
        dal_common: The logging switches.
        connection: The open handle.
    """
    state = _CURSORS.state_for(TABLE, _NAME_ORDER_SLOT)
    if state.cursor_not_active():
        # `set KOR-x1 to 1` then the offset and length moves
        # [common/purchMT.cbl:L1019-L1021]; the same primary key of reference the
        # key-ordered walk uses, because the PREDICATE is on PURCH-KEY here too
        # and only the ORDERING differs.
        order_term = NAME_ORDER.order_terms[0]
        clause = (
            f"{_QUOTED_KEY_COLUMN} >= {_NAME_ORDER_LOW_KEY}"
            f" ORDER BY {quote_identifier(order_term.column_name)}"
            f" {order_term.direction}"
        )
        _log_where(file_access, clause)
        _stamp(
            file_access, BRIDGE_PARAGRAPH_NUMBERS["ba140-Process-Read-Next"]
        )
        statement = f"SELECT * FROM {_QUOTED_TABLE} WHERE {clause};"
        # No value is bound: the low key is a frozen literal, inlined so that
        # N-lowkey-quoting-split survives - see :data:`_NAME_ORDER_LOW_KEY`.
        rows, error = _mysql_1210_command_then_store(
            connection, statement, (), file_access
        )
        # `MOVE WS-MYSQL-RESULT TO TP-PULEDGER-REC` [common/purchMT.cbl:L1054] -
        # THE SAME ONE POINTER the key-ordered walk stores into
        # (``N-single-result-pointer-two-cursors``).
        count = _RESULT_POINTER.store_result(rows)
        # `move "0000000" to WS-File-Key` [common/purchMT.cbl:L1056].
        _file_key(file_access, _NAME_ORDER_LOW_KEY)
        if dal_common.sw_testing_2 == 1:
            _trace("purchMT ba140: %s", clause)
        if count == 0:
            # [common/purchMT.cbl:L1063-L1076], with the maintainer's own note
            # "It could be an empty table so test for it".
            errno, sqlstate, message = _driver_error_fields(error)
            _move_sql_state(file_access, sqlstate)
            if errno != _ERRNO_SUCCESS:
                _move_sql_error(file_access, errno, message)
            fs_reply, we_error = end_of_file_status()
            _status(file_access, fs_reply, we_error)
            _file_key(file_access, "No Data")
            # `go to ba999-End` [common/purchMT.cbl:L1075] - Class 2, carrying
            # the maintainer's "can clear the dup code after testing".
            purchmt_ba999_end(file_access, dal_common)
            return
        # `set Cursor-Active-2 to true` [common/purchMT.cbl:L1077].
        state.set_cursor_active()
        _file_key(
            file_access, _count_rows_file_key(count, " recs in NAME order")
        )
        # `perform ba999-End` [common/purchMT.cbl:L1084], commented "log it" -
        # a PERFORM and not a GO TO, so control returns and falls into ba141.
        # The walk therefore logs TWICE on the call that opens it.
        purchmt_ba999_end(file_access, dal_common)
    # Fall through into `ba141-Reread` [common/purchMT.cbl:L1087].
    purchmt_ba141_reread(file_access, purch, dal_common)


def purchmt_ba141_reread(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
) -> None:
    """``ba141-Reread.`` [common/purchMT.cbl:L1087-L1167].

    "If here cursor is set (even from start), so get the next row"
    [common/purchMT.cbl:L1089]. The name-ordered twin of :func:`purchmt_ba041_re`
    ``read``, and identical to it in every respect except three, each of which is
    reproduced:

    * it stamps 22 rather than 4 [common/purchMT.cbl:L1092];
    * it clears and sets ``Most-Cursor-Set-2``, never slot 1
      [common/purchMT.cbl:L1137, :L1154, :L1159];
    * its ``initialize`` writes ``Purch-Rec`` where ``ba041`` writes
      ``Purch-REC`` [common/purchMT.cbl:L1149 versus :L642] - the third of the
      three casings of one name, anomaly ``N-initialize``. Both spell
      ``with filler``, so both clear the trailing 12-byte filler that the plain
      ``initialize`` at [common/purchMT.cbl:L1257] leaves alone.

    ANOMALY ``N-sticky-eof``, second instance. The third test is
    ``if fs-reply = 10`` [common/purchMT.cbl:L1158-L1162], which inspects the
    CALLER's incoming status rather than anything this fetch established. A caller
    that arrives already holding 10 - from a previous walk that hit end of file,
    say - has its cursor flag cleared and gets ``"EOF3"`` in the log key without
    a row ever being examined. Reproduced.

    ANOMALY ``N-eof2-inside-the-errno-test``. On the count-zero path the
    ``initialize`` and the ``"EOF2"`` log key sit INSIDE the
    ``if WS-MYSQL-Error-Number not = "0  "`` test
    [common/purchMT.cbl:L1145-L1151] while the status pair and the flag sit
    outside it [common/purchMT.cbl:L1152-L1154]. So a count-zero WITHOUT a client
    error reports end of file, clears the flag, and leaves both the caller's
    record and the log key untouched - the caller sees the record it passed in,
    unchanged, alongside a 10.

    Args:
        file_access: The block whose status and logging data are written.
        purch: The caller's record; the unload writes into it on success only.
        dal_common: The logging switches.
    """
    # `move spaces to WS-Log-Where.` [common/purchMT.cbl:L1091].
    _log_where(file_access, "")
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba141-Reread"])
    state = _CURSORS.state_for(TABLE, _NAME_ORDER_SLOT)
    # `move zero to return-code.` [common/purchMT.cbl:L1093] then
    # `MOVE TP-PULEDGER-REC TO WS-MYSQL-RESULT` and
    # `CALL "MySQL_fetch_record"` [common/purchMT.cbl:L1099-L1129] - the fetch
    # reads the ONE shared result pointer.
    row = _RESULT_POINTER.fetch_record()
    if row is None:
        # `if return-code = -1` [common/purchMT.cbl:L1134-L1139].
        fs_reply, we_error = end_of_file_status()
        _status(file_access, fs_reply, we_error)
        _file_key(file_access, "EOF")
        state.set_cursor_not_active()
        purchmt_ba999_end(file_access, dal_common)  # Class 2.
        return
    if _RESULT_POINTER.count_rows == 0:  # pragma: no cover - a row implies rows
        # `if WS-MYSQL-Count-Rows = zero` [common/purchMT.cbl:L1141-L1156].
        _initialize_purch_rec(purch, with_filler=True)
        _file_key(file_access, "EOF2")
        fs_reply, we_error = end_of_file_status()
        _status(file_access, fs_reply, we_error)
        state.set_cursor_not_active()
        purchmt_ba999_end(file_access, dal_common)
        return
    if int(file_access.fs_reply) == int(FsReply.END_OF_FILE):
        # ANOMALY N-sticky-eof [common/purchMT.cbl:L1158-L1162].
        state.set_cursor_not_active()
        _file_key(file_access, "EOF3")
        purchmt_ba999_end(file_access, dal_common)  # Class 2.
        return
    # `perform bb100-UnloadHVs.` [common/purchMT.cbl:L1164].
    bb100_unload_hvs(_host_variables_from_row(row), purch)
    # `move HV-Purch-Key to WS-File-Key.` [common/purchMT.cbl:L1165] - the HOST
    # VARIABLE, trimmed to its own width, where the read-indexed path routes the
    # same value through a numeric edit field instead.
    _file_key(file_access, str(row.get(KEY_OF_REFERENCE.column_name, "")))
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    # `go to ba999-end.` [common/purchMT.cbl:L1167] - Class 2.
    purchmt_ba999_end(file_access, dal_common)


def purchmt_ba100_bad_function(file_access: FileAccess) -> None:
    """``ba100-Bad-Function.`` [common/purchMT.cbl:L1169-L1175].

    "Houston; We have a problem" [common/purchMT.cbl:L1171]. Reached from the
    bridge's ``when other`` arm [common/purchMT.cbl:L443-L444], whose comment
    records that "6 is spare / unused".

    ANOMALY ``N-badfunction-990-vs-999``. The bridge reports
    ``(99, 990)``; the handler's own ``aa100-Bad-Function`` reports
    ``(99, 999)`` for the identical condition
    [common/acas022.cbl:L576-L577]. One handler, one invalid function code, two
    different ``We-Error`` values, decided by which store is configured. Neither
    is reconciled. Note also that 990 is documented as "unknown/unexpected" and
    999 as "not used", so the bridge's is at least the more descriptive of the
    two - which is not a reason to change either.

    Args:
        file_access: The block whose status pair is written.
    """
    # `move 990 to WE-Error.` then `move 99 to Fs-Reply.`
    # [common/purchMT.cbl:L1173-L1174] - in that order, WE-Error first, which is
    # the reverse of the handler's order at [common/acas022.cbl:L576-L577].
    _status(file_access, FsReply.ERROR, WeError.UNKNOWN_UNEXPECTED)
    # `go to ba999-end.` [common/purchMT.cbl:L1175] - Class 2.


def purchmt_ba998_free(file_access: FileAccess) -> None:
    """``ba998-Free.`` [common/purchMT.cbl:L1181-L1191].

    "Free the results memory / Only used for read-indexed as we do not know when
    an app has finished with a cursor" [common/purchMT.cbl:L1183-L1186] - the
    maintainer's own statement of why the read-indexed path frees and the walks
    do not.

    ANOMALY ``N-free-clears-slot-1-only``. The paragraph ends
    ``set Cursor-Not-Active to true`` [common/purchMT.cbl:L1191], clearing the
    KEY-ordered flag, while the result pointer it just freed is the single shared
    one (``N-single-result-pointer-two-cursors``). A free issued while a
    NAME-ordered walk is live therefore destroys that walk's rows and leaves
    ``Most-Cursor-Set-2`` set, so the walk's next call takes the fetch path
    against a freed pointer instead of re-selecting. Reproduced by freeing the
    one pointer and clearing slot 1 alone.

    ANOMALY ``N-free-falls-through``. There is no ``go to`` at the end
    [common/purchMT.cbl:L1191]; control falls straight into ``ba999-end``
    [common/purchMT.cbl:L1193]. Every caller of this paragraph therefore logs,
    whether or not it wanted to - which is AAP section 0.4.2 Class 2 fall-through
    made explicit here rather than left implicit.

    Args:
        file_access: The block whose paragraph stamp is written.
    """
    _stamp(file_access, BRIDGE_PARAGRAPH_NUMBERS["ba998-Free"])
    # `MOVE TP-PULEDGER-REC TO WS-MYSQL-RESULT` then
    # `CALL "MySQL_free_result" USING WS-MYSQL-RESULT`
    # [common/purchMT.cbl:L1188-L1189].
    _RESULT_POINTER.free_result()
    # `set Cursor-Not-Active to true.` [common/purchMT.cbl:L1191] - slot 1 ONLY.
    _CURSORS.state_for(TABLE, _KEY_ORDER_SLOT).set_cursor_not_active()
    # Falls through into ba999-end; callers that need the log record perform it,
    # and every caller of this paragraph is on a path that reaches it.


def purchmt_ba999_end(
    file_access: FileAccess, dal_common: AcasDalCommonData
) -> None:
    """``ba999-end.`` [common/purchMT.cbl:L1193-L1198].

    The bridge's single convergence point::

        if       Testing-1
                 perform Ca-Process-Logs
        end-if.

    ANOMALY ``N-bridge-logs-handler-does-not``. The handler's own
    ``Ca-Process-Logs`` carries the comment "Not called on DAL access as it does
    it already" on its label line [common/acas022.cbl:L671], and this is what it
    means: on the RDB path the BRIDGE logs and the handler must not. The two
    guards are also not the same - the handler tests ``Testing-1`` at
    [common/acas022.cbl:L580] before its own call, so were both to run the same
    operation would be logged twice.

    Args:
        file_access: The block passed to the logger.
        dal_common: Carries ``SW-Testing``, whose ``88 Testing-1 value 1``
            [copybooks/Test-Data-Flags.cob:L11] gates the call. The frozen
            copybook declares it ``value 1``, so logging is ON as shipped.
    """
    # `if Testing-1` [common/purchMT.cbl:L1195]. The Python record exposes no
    # condition-name predicate, so the 88 is tested inline
    # [copybooks/Test-Data-Flags.cob:L10-L11].
    if dal_common.sw_testing == 1:
        purchmt_ca_process_logs(file_access, dal_common)
    # Falls through into ba999-exit.


def purchmt_ba999_exit() -> None:
    """``ba999-exit.`` [common/purchMT.cbl:L1200-L1201].

    ``exit program.`` - the bridge's return to its caller. Modelled as a named
    no-op so that the paragraph-to-function mapping rule R-5 requires has an
    entry for it, and so that a reader following the frozen listing finds every
    label. It carries no behaviour: returning from :func:`purch_mt` IS the
    ``exit program``.
    """
    return


def bb200_insert(
    host_variables: HostVariables,
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    *,
    connection: object,
) -> tuple[int, BaseException | None]:
    """``bb200-Insert Section.`` [common/purchMT.cbl:L1292-L1680].

    Assembles ``INSERT INTO `PULEDGER-REC` SET `` [common/purchMT.cbl:L1302-L1303]
    followed by all TWENTY-NINE columns in table ordinal order, each rendered
    through the edit field and its declared window, separated by ``', '``
    [common/purchMT.cbl:L1313], and terminated with ``";" X"00"``
    [common/purchMT.cbl:L1671-L1673]. Then
    ``PERFORM MYSQL-1210-COMMAND THRU MYSQL-1219-EXIT``
    [common/purchMT.cbl:L1675], reproduced by :func:`_mysql_1210_command`.

    EVERY COLUMN IS NAMED AND NONE IS OMITTED, which is the ``NOT NULL``
    invariant the maintainer states in his own words at the head of
    ``bb100-UnloadHVs``: "NULL fields must not be returned in the buffer. SQL
    filters each column to ensure it has a proper value. This saves using
    indicator variables." The load's first statement is
    ``initialize TD-PULEDGER-REC`` [common/purchMT.cbl:L1211], so an unset field
    arrives as zero or space rather than as ``NULL``, and AAP section 0.6.2 draws
    the conclusion this function implements: "This is why every column in the
    schema can be declared ``NOT NULL`` and why the Python layer must default
    rather than omit." No ``None`` is ever bound.

    The rendered text comes from :meth:`HostVariables.rendered_values`, which is
    where the twelve sign losses and the seven money truncations have already
    happened - by the time a value reaches this function it is exactly the
    character sequence the COBOL would have placed between the double quotes.
    Values travel as bound parameters rather than as embedded literals; MySQL
    coerces the same strings to the same column types either way, and binding is
    what keeps a name containing a quotation mark from ending the statement.

    Args:
        host_variables: The loaded ``TD-PULEDGER-REC`` group.
        file_access: The block the shared failure paragraph writes to.
        dal_common: The logging switches.
        connection: The open handle.

    Returns:
        The affected-row count and the driver failure, if any. The caller's
        ``not = 1`` test decides what the status becomes; see
        :func:`purchmt_ba070_process_write` and anomaly
        ``N-write-masked-failure``.
    """
    assignments = ", ".join(
        f"{quote_identifier(column)}=%s" for column in COLUMN_ORDER
    )
    statement = f"INSERT INTO {_QUOTED_TABLE} SET {assignments};"
    values = host_variables.rendered_values()
    if len(values) != len(COLUMN_ORDER):  # pragma: no cover - guarded on import
        raise AssertionError(
            f"{BRIDGE} bb200-Insert renders {len(values)} values for "
            f"{len(COLUMN_ORDER)} columns"
        )
    if dal_common.sw_testing_2 == 1:
        _trace("purchMT bb200: %s", statement)
    return _mysql_1210_command(connection, statement, values, file_access)


def bb300_update(
    host_variables: HostVariables,
    clause: str,
    key_value: str,
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    *,
    connection: object,
) -> tuple[int, BaseException | None]:
    """``bb300-Update Section.`` [common/purchMT.cbl:L1682-L2074].

    ``UPDATE `PULEDGER-REC` SET `` [common/purchMT.cbl:L1692-L1693] with the SAME
    twenty-nine assignments the insert builds - the primary key among them
    [common/purchMT.cbl:L1697-L1700] - then ``" WHERE "``
    [common/purchMT.cbl:L2061] and the clause, then ``";" X"00"``
    [common/purchMT.cbl:L2067].

    ANOMALY ``N-update-key-trim-split``. The clause reaches the statement through
    ``FUNCTION TRIM (WS-Where (1:J))`` [common/purchMT.cbl:L2064] while
    ``ba090`` placed the very same text into ``WS-Log-Where`` untrimmed
    [common/purchMT.cbl:L985]. The trim removes the one trailing character that
    ``(1:J)`` overruns by, so the logged clause and the executed clause differ by
    a space. Reproduced: the parameter arrives untrimmed for the log and the
    assembled text is trimmed here.

    ANOMALY ``N-update-rewrites-the-key``. The ``SET`` list includes
    ``PURCH-KEY`` itself, so a rewrite whose record key differs from the key the
    ``WHERE`` matched would move the row to a new key rather than fail. Since
    ``ba090`` builds both from the same record field
    [common/purchMT.cbl:L968, :L980] the two always agree in practice, and the
    latent hazard is recorded rather than guarded - adding a guard would be the
    added validation rule R-3 forbids.

    Args:
        host_variables: The loaded ``TD-PULEDGER-REC`` group.
        clause: The predicate ``ba090`` assembled, untrimmed.
        key_value: The value bound into that predicate.
        file_access: The block the shared failure paragraph writes to.
        dal_common: The logging switches.
        connection: The open handle.

    Returns:
        The affected-row count and the driver failure, if any.
    """
    assignments = ", ".join(
        f"{quote_identifier(column)}=%s" for column in COLUMN_ORDER
    )
    # `FUNCTION TRIM (WS-Where (1:J))` [common/purchMT.cbl:L2064].
    statement = (
        f"UPDATE {_QUOTED_TABLE} SET {assignments} WHERE {clause.strip()};"
    )
    values = host_variables.rendered_values()
    if len(values) != len(COLUMN_ORDER):  # pragma: no cover - guarded on import
        raise AssertionError(
            f"{BRIDGE} bb300-Update renders {len(values)} values for "
            f"{len(COLUMN_ORDER)} columns"
        )
    if dal_common.sw_testing_2 == 1:
        _trace("purchMT bb300: %s", statement)
    return _mysql_1210_command(
        connection, statement, (*values, key_value), file_access
    )


def purchmt_ca_process_logs(
    file_access: FileAccess, dal_common: AcasDalCommonData
) -> None:
    """``Ca-Process-Logs.`` [common/purchMT.cbl:L2076-L2080].

    The bridge's logging paragraph, whose COBOL body is
    ``call "fhlogger" using File-Access ACAS-DAL-Common-data``
    [common/purchMT.cbl:L2079-L2080]. ``fhlogger`` is a COBOL program and rule
    R-1 forbids calling it, so the record it would have written is emitted
    natively instead: the same eleven ``Logging-Data`` fields plus the status
    pair, at debug level, reaching no table.

    AAP section 0.1.1 places this transformation explicitly - diagnostics with no
    database effect become log lines - and section 0.2.2 puts ``common/fhlogger``
    ``.cbl`` out of scope, so there is nothing to reimplement beyond the record
    itself. It is emitted through
    :func:`acas_posting.dal.status.log_file_handler_record`, THE ONE ADAPTER every
    handler in this package shares, so the single legacy log this cycle produces
    reads the same whichever table wrote it.

    THREE FIELDS ARE WITHHELD. ``WS-File-Key`` is ``PURCH-KEY``, the supplier
    code; ``WS-Log-Where`` is a predicate carrying it as a literal; ``SQL-Msg`` is
    driver free text. All three are CWE-532 in a log and none is needed to act on a
    failure, and ``redact_for_log`` was escaping the first two rather than removing
    them.

    ``Log-File-Rec-Written`` IS NOW ADVANCED, by the adapter, modulo one
    million - the range of the frozen ``pic 9(6)``
    [copybooks/Test-Data-Flags.cob:L20]. Leaving it alone was wrong: the counter
    lives in ``ACAS-DAL-Common-data``, which the CALLER owns and carries across
    calls, so it is not the COBOL program's private state but part of the linkage
    this module is reproducing.

    Args:
        file_access: The block whose fields make up the record.
        dal_common: Carried for signature fidelity with the COBOL parameter list;
            the switch that gated this call was already tested by
            :func:`purchmt_ba999_end`.
    """
    logging_data = file_access.logging_data
    log_file_handler_record(
        _LOG,
        program=BRIDGE_PROG_NAME,
        paragraph="Ca-Process-Logs",
        log_system=logging_data.ws_log_system,
        log_file_no=logging_data.ws_log_file_no,
        no_paragraph=logging_data.ws_no_paragraph,
        file_function=int(file_access.file_function),
        access_type=int(file_access.access_type),
        fs_reply=int(file_access.fs_reply),
        we_error=int(file_access.we_error),
        sql_err=logging_data.sql_err,
        sql_state=logging_data.sql_state,
        dal_common=dal_common,
    )
    # Falls through into ca-Exit.


def purchmt_ba_acas_dal_process(
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    purch: WsPurchRecord,
    *,
    system_record: SystemRecord | None,
    transport: TransportSecurity | None,
) -> None:
    """``ba-ACAS-DAL-Process section.`` [common/purchMT.cbl:L389-L445].

    The bridge's only section entry. Its first six statements are terminal
    geometry and curses environment settings
    [common/purchMT.cbl:L390-L401] - ``accept ws-env-lines from lines``, two
    ``set ENVIRONMENT`` calls for ``COB_SCREEN_EXCEPTIONS`` and
    ``COB_SCREEN_ESC``, and the two derived line numbers a display panel would
    have used. All six are DELIBERATELY OMITTED (rule R-5's "deliberate omissions
    are recorded as omissions"): they reach no table, and AAP section 0.3.4 rules
    that presentation with no database effect is dropped rather than
    reimplemented. Their only consumers in this bridge are the ``display ... at
    line ws-lines`` statements inside the dead lock-retry ladder
    [copybooks/mysql-procedures.cpy:L229-L243].

    Then ``ba010-Initialise`` [common/purchMT.cbl:L403] falls through into the
    function ``evaluate`` [common/purchMT.cbl:L424-L445], which this function
    reproduces. All ten arms, in the frozen order, with ``when 31`` routed to its
    OWN paragraph and not folded into ``when 3``.

    Args:
        file_access: The block carrying the function code, the access type and
            every status and diagnostic field.
        dal_common: The logging switches.
        purch: The caller's record.
        system_record: Supplies the credentials on the open path only.
        transport: The transport policy for the open path only.
    """
    purchmt_ba010_initialise(file_access)
    function = int(file_access.file_function)
    # `evaluate File-Function` [common/purchMT.cbl:L424]. Every arm is a
    # `go to`, i.e. AAP section 0.4.2 Class 4 - a sibling paragraph that runs and
    # then transfers to the common exit - so each is a call followed by `return`.
    if function == int(FileFunction.OPEN):
        purchmt_ba020_process_open(
            file_access, system_record=system_record, transport=transport
        )
        return
    if function == int(FileFunction.CLOSE):
        purchmt_ba030_process_close(file_access)
        return
    # `01 WS-MYSQL-CONNECTION` is the bridge's own working storage, and the
    # bridge reaches its statement sites with whatever that field holds - it
    # never tests it. A statement issued before `ba020-Process-Open` succeeded
    # therefore fails inside the client, which routes through the shared failure
    # paragraph and reports `(99, 911)`, the code the authoritative table
    # documents as "Rdb Error during initializing, possibly can not connect to
    # database" [common/glpostingMT.cbl:L143-L144]. No guard is added here: a
    # guard would be an added validation, which rule R-3 forbids, and it would
    # also pre-empt the two paragraphs below that reject their parameters BEFORE
    # touching the connection.
    connection = _CONNECTION
    if function == int(FileFunction.READ_NEXT):
        purchmt_ba040_process_read_next(
            file_access, purch, dal_common, connection
        )
        return
    if function == int(FileFunction.READ_INDEXED):
        purchmt_ba050_process_read_indexed(
            file_access, purch, dal_common, connection
        )
        return
    if function == int(FileFunction.WRITE):
        purchmt_ba070_process_write(
            file_access, purch, dal_common, connection
        )
        purchmt_ba999_end(file_access, dal_common)
        return
    if function == int(FileFunction.RE_WRITE):
        # `when 7 go to ba090-Process-Rewrite` [common/purchMT.cbl:L435-L436] -
        # note the frozen order puts 7 BEFORE 8, so rewrite is dispatched ahead
        # of delete even though the paragraphs are laid out the other way round.
        purchmt_ba090_process_rewrite(
            file_access, purch, dal_common, connection
        )
        purchmt_ba999_end(file_access, dal_common)
        return
    if function == int(FileFunction.DELETE):
        purchmt_ba080_process_delete(
            file_access, purch, dal_common, connection
        )
        purchmt_ba999_end(file_access, dal_common)
        return
    if function == int(FileFunction.START):
        purchmt_ba060_process_start(
            file_access, purch, dal_common, connection
        )
        purchmt_ba999_end(file_access, dal_common)
        return
    if function == int(FileFunction.READ_BY_NAME):
        # ANOMALY N-31-two-meanings [common/purchMT.cbl:L441-L442]. The bridge
        # gives code 31 its own name-ordered paragraph where the handler folds it
        # into an ordinary read-next.
        purchmt_ba140_process_read_next(
            file_access, purch, dal_common, connection
        )
        return
    # `when other` [common/purchMT.cbl:L443-L444]. Codes 6, 13, 15, 32, 33 and 34
    # all land here: the bridge dispatches NONE of them, which is why no
    # delete-all, no raw write and no by-batch or by-customer read exists in this
    # module (``N-codes-32-33-dead``).
    purchmt_ba100_bad_function(file_access)
    purchmt_ba999_end(file_access, dal_common)


def purch_mt(
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    purch: WsPurchRecord,
    *,
    system_record: SystemRecord | None = None,
    transport: TransportSecurity | None = None,
) -> tuple[int, int]:
    """``call "purchMT" using File-Access ACAS-DAL-Common-data WS-Purch-Record``.

    The bridge program ``purchMT``, entered exactly as the handler enters it
    [common/acas022.cbl:L659-L663] with the THREE parameters its own
    ``PROCEDURE DIVISION`` declares, in that order
    [common/purchMT.cbl:L385-L387]. Note that the handler passes its
    ``WS-Purch-Record`` where the bridge's linkage names the parameter
    ``Purch-Rec`` with the comment "Ws record" [common/purchMT.cbl:L387]; the two
    layouts are NOT identical, which is the whole subject of the drift table in
    this module's docstring, and it is the bridge's own hard-coded copy
    [common/purchMT.cbl:L331-L358] that its ``MOVE`` statements read from.

    This function owns ALL SQL for ``PULEDGER-REC`` - the four SELECTs, the
    INSERT, the UPDATE and the single-row DELETE - and no other module issues a
    statement against that table.

    THE AUTHORITATIVE DATA DICTIONARY IS THE DIRECTIVE BLOCK, verbatim from
    [common/purchMT.cbl:L276-L279]::

        *> /MYSQL VAR\
        *>       ACASDB
        *>       TABLE=PULEDGER-REC,HV
        COPY "mysql-variables.cpy".

    That block names the schema and the table, and declares that the group which
    follows is the host-variable group for it. The group it introduces is
    ``01 TD-PULEDGER-REC`` [common/purchMT.cbl:L285-L313] - twenty-nine entries,
    and the ONLY layer this module treats as authoritative for width, scale and
    signedness. The preserved user requirement in AAP section 0.8.2 - "The
    maintainer's one-way COBOL-to-MySQL bridge defines the authoritative
    record-layout to table mapping - it is the data dictionary for this
    migration" - has to mean this group specifically, because the bridge's own
    hard-coded record buffer [common/purchMT.cbl:L331-L358] disagrees with it on
    seven money fields and eleven integer widths, and a value that reaches the
    database passes through the host variable, never through the buffer.

    THE CONTRACT IS THE STATUS PAIR, NEVER AN EXCEPTION. The handler's own
    comment at the call site is explicit: "Any errors leave it to caller to
    recover from" [common/acas022.cbl:L665]. Every failure path therefore writes
    ``Fs-Reply`` and ``We-Error`` and returns; the single exception this module
    defines, :class:`PurchaseFileNotSuppliedError`, is reachable only from the
    ISAM branch of the handler and never from here.

    Args:
        file_access: The ``File-Access`` block. Read for ``File-Function``,
            ``Access-Type`` and ``File-Key-No``; written with the status pair and
            the whole ``Logging-Data`` sub-block.
        dal_common: ``ACAS-DAL-Common-data``, carrying the two testing switches.
        purch: The caller's record, read on the write and rewrite paths and
            written on the read paths.
        system_record: The system record whose ``RDBMS`` fields supply the
            credentials. Consulted on the open path only; when omitted the open
            path rebuilds an equivalent from the ``RDB-Data`` sub-block the
            handler already copied in [common/acas022.cbl:L641-L646].
        transport: The transport policy handed to
            :func:`~acas_posting.dal.connection.mysql_1000_open`. Consulted on
            the open path only.

    Returns:
        The ``(Fs-Reply, We-Error)`` pair, as a convenience for callers that
        prefer a return value to reading the record back. The record itself is
        authoritative and is what the COBOL caller inspects.

    Example:
        >>> from acas_posting.records.file_access import FileAccess
        >>> from acas_posting.records.purchase_ledger import WsPurchRecord
        >>> from acas_posting.records.test_data_flags import AcasDalCommonData
        >>> block = FileAccess()
        >>> block.file_function = 34            # fn-Read-Next-Header
        >>> purch_mt(block, AcasDalCommonData(), WsPurchRecord())
        (99, 990)
    """
    purchmt_ba_acas_dal_process(
        file_access,
        dal_common,
        purch,
        system_record=system_record,
        transport=transport,
    )
    # `ba999-exit. exit program.` [common/purchMT.cbl:L1200-L1201].
    purchmt_ba999_exit()
    return int(file_access.fs_reply), int(file_access.we_error)


def purchmt_ca_exit() -> None:
    """``ca-Exit.`` [common/purchMT.cbl:L2082].

    Written on one line as ``ca-Exit.     exit.`` - a plain ``exit``, not
    ``exit section``, exactly as the handler's own ``ca-Exit`` is
    [common/acas022.cbl:L677]. Both are modelled as named no-ops so that R-5's
    paragraph-to-function mapping is complete; returning from
    :func:`purchmt_ca_process_logs` IS the ``exit``.
    """
    return


# ---------------------------------------------------------------------------
# The handler - `acas022`, the ISAM half.
#
# `aa-Process-Flat-File Section.` [common/acas022.cbl:L287] onwards. Every
# paragraph below is the flat-file path, reached only when
# `FS-Cobol-Files-Used` holds [common/acas022.cbl:L316]; the RDB path leaves
# `aa010-main` before any of them runs. They are implemented in full because
# rule R-5 requires a function per paragraph and because the two halves of this
# handler DISAGREE on six separate points - the bad-function code, the start
# guard, the read-indexed not-found status, the SQL field clear, the log file
# number and the meaning of function code 31 - and a disagreement cannot be
# recorded by implementing only one side of it.
#
# The ISAM store itself is supplied by the caller through the `PurchaseFile`
# protocol; this module holds no file, opens none, and reaches no COBOL runtime
# (rule R-1).
# ---------------------------------------------------------------------------

#: ``77  Cobol-File-Status pic 9`` with ``88 Cobol-File-Eof value 1``
#: [common/acas022.cbl:L256-L257]. Handler-local WORKING-STORAGE, not part of
#: any linkage record, so it lives at module level here for the same reason
#: :data:`_WS_A` does. It is set only by the end-of-file branch of
#: ``aa040-Process-Read-Next`` [common/acas022.cbl:L433-L434] - which sets it
#: TWICE, once through the condition name and once by moving 1 into the field,
#: under the maintainer's "JIC above dont work :)" - and zeroed by five separate
#: paragraphs [common/acas022.cbl:L396, :L407, :L472, :L496, :L541, :L554,
#: :L566].
_COBOL_FILE_STATUS: int = 0

#: ``88  Cobol-File-Eof value 1.`` [common/acas022.cbl:L257].
_COBOL_FILE_EOF: Final[int] = 1

#: ``03  PL905 pic x(32) value "PL905 Program Error: Temp rec = ".``
#: [common/acas022.cbl:L263] and ``03 PL901 pic x(31) value "PL901 Note error
#: and hit return".`` [common/acas022.cbl:L262]. Declared INSIDE this handler,
#: in an ``01 Error-Messages`` group of its own [common/acas022.cbl:L259], and
#: nowhere else in the checkout - a grep across ``copybooks/`` finds neither
#: identifier. Both are reachable only from the dead 901 panel.
_PL905: Final[str] = "PL905 Program Error: Temp rec = "
_PL901: Final[str] = "PL901 Note error and hit return"

#: The two function codes the key guard's FIRST arm covers - ``when 4`` and
#: ``when 9`` share one body and one 998 [common/acas022.cbl:L299-L305].
#: ``when 8`` is a separate arm with its own 996, so it is NOT in this set.
_KEY_GUARDED_READ_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {int(FileFunction.READ_INDEXED), int(FileFunction.START)}
)

#: ``when 3`` and ``when 31`` [common/acas022.cbl:L343-L345]. ANOMALY
#: ``N-read-by-name-is-read-next``: 31 falls through into 3 on the ISAM path and
#: is served by the ordinary read-next paragraph. The BRIDGE routes 31 to its own
#: name-ordered paragraph instead [common/purchMT.cbl:L441-L442], which is
#: anomaly ``N-31-two-meanings`` - one code, two behaviours, one handler.
#:
#: ``N-changelog-cross-ledger``: three sources name three different drivers for
#: this one code. The handler's own changelog says
#: ``.05 Allow for fn-Read-By-Name used in SL165.``
#: [common/acas022.cbl:L139] - a SALES program named as the driver of the
#: PURCHASE handler. The SALES handler carries the IDENTICAL changelog line
#: [common/acas012.cbl:L139], so one line was pasted into both. And the shared
#: vocabulary that declares the code names a THIRD program, "for Salesled
#: (SL160)" [copybooks/wsfnctn.cob:L102]. Recorded, not arbitrated: the code is
#: dispatched regardless of which program drives it, and no caller is consulted.
_AA_READ_NEXT_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {int(FileFunction.READ_NEXT), int(FileFunction.READ_BY_NAME)}
)

#: The five function arms of ``aa045-Eval-Keys`` [common/acas022.cbl:L450-L454].
#: FOUR of them - 5, 7, 8 and 9 - are unreachable, because the paragraph's only
#: caller is ``aa050-Process-Read-Indexed`` [common/acas022.cbl:L471], which
#: always arrives with 4. Anomaly ``N-deadbranches``; the set is complete anyway.
_AA045_FUNCTIONS: Final[frozenset[int]] = frozenset(
    {
        int(FileFunction.READ_INDEXED),
        int(FileFunction.WRITE),
        int(FileFunction.RE_WRITE),
        int(FileFunction.DELETE),
        int(FileFunction.START),
    }
)

#: The four relations ``aa060-Process-Start`` has a longhand block for, in the
#: frozen order [common/acas022.cbl:L507-L534]. ``fn-not-greater-than`` (9) has
#: NO block, which is consistent with the guard's ``> 8``
#: [common/acas022.cbl:L500] and is why anomaly
#: ``N-access-type-9-dead-in-bridge`` is dead on the ISAM path too.
_AA060_RELATIONS: Final[tuple[int, ...]] = (
    int(AccessType.EQUAL_TO),
    int(AccessType.LESS_THAN),
    int(AccessType.GREATER_THAN),
    int(AccessType.NOT_LESS_THAN),
)

#: ``03  Purch-Address.`` with ``05 Purch-Addr1 pic x(48)`` and
#: ``05 Purch-Addr2 pic x(48)`` [copybooks/wspl.cob:L23-L25]. The group has a
#: column, ``PURCH-ADDRESS char(96)``, and its two children have NEITHER a host
#: variable NOR a column, because the bridge flattens the group to
#: ``pic x(96)`` in its own record copy [common/purchMT.cbl:L338] - anomaly
#: ``N-address-flattened``. The dictionary therefore reports the group with no
#: character length of its own, so the 48+48 is stated here, at the one place
#: that needs it.
_ADDRESS_GROUP_BYTES: Final[int] = 96

#: ``Purch-Stats-Date pic 9(4)`` [copybooks/wspl.cob:L53] plus
#: ``filler pic x(12)`` [copybooks/wspl.cob:L54]. Neither has a host variable or
#: a column - anomalies ``N-stats-date-write-nowhere`` and the trailing padding -
#: so neither appears in :data:`COLUMN_ORDER`, and both must be added back by
#: hand when the RECORD's length is what is wanted rather than the ROW's.
_TRAILING_UNMAPPED_BYTES: Final[int] = 4 + 12


def _cobol_storage_bytes(binding: _ColumnBinding) -> int:
    """The bytes one copybook field occupies, by its declared usage.

    Needed by :func:`ba012_test_ws_rec_size_2`, whose guard compares
    ``function Length`` of two records [common/acas022.cbl:L610-L615]. The rules
    are GnuCOBOL's defaults, which is what the frozen build uses - a census of
    every compile invocation in the checkout finds no ``-std=`` dialect
    selection, no ``binary-truncate`` flag and no arithmetic directive.

    Args:
        binding: The column binding carrying the copybook's usage, digit count
            and character length.

    Returns:
        The field's storage size in bytes.

    Raises:
        ValueError: If the usage is one this table does not declare. The frozen
            copybook declares exactly seven, so this cannot fire for
            ``PULEDGER-REC``; it fires loudly rather than returning a wrong
            length if the dictionary ever changes shape.
    """
    usage = binding.copybook_usage
    if usage == "GROUP":
        # `03 Purch-Address.` [copybooks/wspl.cob:L23-L25].
        return _ADDRESS_GROUP_BYTES
    if usage == "ALPHANUMERIC":
        return binding.copybook_width
    if usage == "DISPLAY":
        # Zoned decimal: one byte per digit, the sign folded into a digit.
        return binding.copybook_digits
    if usage in _BINARY_STORAGE_BYTES:
        # `binary-char` and `binary-long` [copybooks/wspl.cob:L31-L42].
        return _BINARY_STORAGE_BYTES[usage]
    if usage == "COMP-3":
        # Packed decimal: two digits per byte plus a sign nibble, rounded up.
        return (binding.copybook_digits + 2) // 2
    if usage == "COMP":
        # `pic 99v99 comp` [copybooks/wspl.cob:L30], four digits, which
        # GnuCOBOL stores in the smallest binary that holds them.
        for digits, width in ((4, 2), (9, 4), (18, 8)):
            if binding.copybook_digits <= digits:
                return width
    raise ValueError(
        f"{COPYBOOK} declares no field of usage {usage!r}; "
        f"{binding.column} cannot be sized"
    )


#: ``function Length (WS-Purch-Record)`` and ``function length (Purch-Record)``
#: [common/acas022.cbl:L610-L615] - ONE value, because the two records are
#: IDENTICAL. Verified field by field: every picture clause in
#: ``copybooks/wspl.cob`` appears, in the same order with the same usage and
#: width, in ``copybooks/fdpl.cob``, down to the trailing ``filler pic x(12)``
#: [copybooks/wspl.cob:L14-L54 against copybooks/fdpl.cob:L16-L56]. That is what
#: makes ``A < B`` impossible and the 901 panel dead - anomaly
#: ``N-901-unreachable``.
#:
#: ANOMALY ``N-recsize``. The copybook records THREE different sizes in its own
#: header - 299 bytes on 26/03/09, 300 bytes on 22/12/11, and 302 bytes on
#: 4/03/2012 "checked by COBSTRUCT (PRIMA tool)"
#: [copybooks/wspl.cob:L6-L8] - and then ``Purch-Stats-Date`` and its 12-byte
#: filler were added on 15/01/18 [copybooks/wspl.cob:L11, :L53], after the last
#: of those measurements. The computed value here agrees with the SECOND of the
#: three and with none of the other two. The contradiction is recorded, not
#: resolved, alongside AAP anomaly #15's 96-versus-98 case in ``wsbatch.cob``.
_RECORD_DECLARED_LENGTH: Final[int] = (
    sum(_cobol_storage_bytes(binding) for binding in _BINDINGS)
    + _TRAILING_UNMAPPED_BYTES
)


def _reset_cobol_file_status(file_access: FileAccess) -> None:
    """``move zero to Cobol-File-Status``.

    Issued by seven separate statements in the handler
    [common/acas022.cbl:L396, :L407, :L472, :L496, :L541, :L554, :L566] - once
    per paragraph that touches the file, plus the two open and close paths.

    Args:
        file_access: Accepted so that every paragraph's helper calls read alike;
            the flag itself is handler-local WORKING-STORAGE and is not part of
            this record, exactly as the COBOL has it.
    """
    global _COBOL_FILE_STATUS
    _COBOL_FILE_STATUS = 0
    del file_access


def _set_cobol_file_eof(file_access: FileAccess) -> None:
    """``set Cobol-File-EoF to true`` AND ``move 1 to Cobol-File-Status``.

    [common/acas022.cbl:L433-L434]. The frozen source does BOTH, the second
    under the comment "JIC above dont work :)" - a condition-name ``SET`` and a
    literal ``MOVE`` of the value that condition name tests for, one after the
    other. The redundancy is the maintainer's own hedge and is preserved as a
    single assignment of the same value, because two assignments of 1 to one
    field are indistinguishable from one.

    Args:
        file_access: Accepted for call-site symmetry; see
            :func:`_reset_cobol_file_status`.
    """
    global _COBOL_FILE_STATUS
    _COBOL_FILE_STATUS = _COBOL_FILE_EOF
    del file_access


def _cobol_file_eof() -> bool:
    """``if Cobol-File-Eof`` [common/acas022.cbl:L421].

    Returns:
        Whether the handler's own end-of-file flag is set.
    """
    return _COBOL_FILE_STATUS == _COBOL_FILE_EOF


def _copy_purch_record(source: WsPurchRecord, target: WsPurchRecord) -> None:
    """``move Purch-Record to WS-Purch-Record`` and its three reverses.

    [common/acas022.cbl:L441] reads the file's record into the caller's;
    [common/acas022.cbl:L478] does the same on the read-indexed path; and
    [common/acas022.cbl:L539, :L550, :L563] copy the other way for the write,
    delete and rewrite. A group ``MOVE`` between two IDENTICAL layouts is a byte
    copy, and the layouts ARE identical - see
    :data:`_RECORD_DECLARED_LENGTH` - so every field transfers unchanged and no
    field is reinterpreted. Modelled as a field-by-field copy rather than a
    :func:`dataclasses.replace`, because the subordinate groups must be copied
    rather than shared: a shared ``PurchAddress`` would let a later write to the
    file's record reach into the caller's, which a COBOL group ``MOVE`` cannot do.

    Args:
        source: The sending record.
        target: The receiving record, mutated in place - the COBOL ``MOVE``
            writes into storage the caller already holds.
    """
    for field in dataclasses.fields(source):
        value = getattr(source, field.name)
        if dataclasses.is_dataclass(value):
            nested = getattr(target, field.name)
            for sub in dataclasses.fields(value):
                setattr(nested, sub.name, getattr(value, sub.name))
            continue
        setattr(target, field.name, value)
    _refresh_quarters_view(target)


def _move_spaces_to_purch_record(record: WsPurchRecord) -> None:
    """``move spaces to Purch-Record`` [common/acas022.cbl:L435, :L481].

    ANOMALY ``N-spaces-into-record``, reproduced literally. A group ``MOVE`` of
    ``SPACES`` writes the space character over EVERY byte of the record,
    including the ``binary-char`` field [copybooks/wspl.cob:L31], the eleven
    ``binary-long`` fields [copybooks/wspl.cob:L32-L42], the ``comp`` discount
    [copybooks/wspl.cob:L30] and the seven ``comp-3`` money fields
    [copybooks/wspl.cob:L43-L52]. Those bytes are then no longer valid numbers:
    a packed-decimal field full of ``0x20`` has neither valid digit nibbles nor a
    sign nibble, and a four-byte binary field reads as the integer 538976288.
    The sibling handler in the same position uses ``initialize`` instead
    [common/acas019.cbl:L379], which would have set the numerics to zero.

    Reproducing "every byte is a space" exactly would require a byte-image
    record, which this layer does not have and which would change the record
    contract every other module depends on. What IS reproduced is the observable
    consequence a caller can act on: the alphanumeric fields become spaces, and
    the numeric fields are left holding the value that space bytes decode to in
    their own usage, computed from the field's declared width rather than
    guessed. The one thing NOT done is silently substituting zero, which is what
    ``initialize`` would have given and is precisely the defect fix rule R-4
    forbids. AMBIGUITY ``Q-purch-spaces-into-binary`` records that the exact
    decoded values need measuring against the compiled program.

    Args:
        record: The record to space-fill, mutated in place.
    """
    for binding in _BINDINGS:
        if binding.column == "PURCH-ADDRESS":
            # The group's two children take the spaces between them, exactly as
            # the group MOVE writes 96 bytes across both
            # [copybooks/wspl.cob:L23-L25].
            _split_group_concatenation(record, " " * _ADDRESS_GROUP_BYTES)
            continue
        if binding.copybook_usage == "ALPHANUMERIC":
            _set_record_value(
                record, binding, " " * _cobol_storage_bytes(binding)
            )
            continue
        _set_record_value(record, binding, _space_bytes_as_number(binding))
    # `Purch-Stats-Date pic 9(4)` and the trailing filler have no column and so
    # no binding; the group MOVE reaches them all the same
    # [copybooks/wspl.cob:L53-L54].
    record.purch_stats_date = int(
        _space_bytes_as_number(_STATS_DATE_BINDING)
    )
    record.filler_l54 = " " * len(record.filler_l54)
    _refresh_quarters_view(record)


def _space_bytes_as_number(binding: _ColumnBinding) -> int | Decimal:
    """What a field full of ``0x20`` bytes decodes to, in that field's usage.

    Supports :func:`_move_spaces_to_purch_record`, which reproduces the group
    ``MOVE SPACES`` at [common/acas022.cbl:L435] rather than the ``initialize``
    a sibling handler uses [common/acas019.cbl:L379].

    Args:
        binding: The field being space-filled.

    Returns:
        The decoded value, as an ``int`` for integer usages and a ``Decimal`` for
        scaled ones. Never a binary floating-point value (rule R-2).
    """
    usage = binding.copybook_usage
    if usage in _BINARY_STORAGE_BYTES:
        # Big-endian `0x2020...` in the field's own width, then read back as a
        # signed integer through the receiving field's own store semantics.
        width = _BINARY_STORAGE_BYTES[usage]
        # The COPYBOOK's signedness governs here, not the host variable's: the
        # MOVE writes into the record field [common/acas022.cbl:L435].
        return int.from_bytes(
            b"\x20" * width, "big", signed=binding.copybook_signed
        )
    if usage == "DISPLAY":
        # Zoned decimal: a space has no digit nibble, and GnuCOBOL reads the
        # low-order nibble, which for 0x20 is zero.
        return 0
    if usage == "COMP":
        width = _cobol_storage_bytes(binding)
        raw = int.from_bytes(
            b"\x20" * width, "big", signed=binding.copybook_signed
        )
        return _scaled_from_raw(raw, binding)
    if usage == "COMP-3":
        # 0x20 nibbles are 2 and 0 alternately, and the final low nibble is the
        # sign position, where 0 is not a valid sign - GnuCOBOL treats an
        # unrecognised sign nibble as positive.
        digits = "".join("20" for _ in range(_cobol_storage_bytes(binding)))
        return _scaled_from_raw(
            int(digits[: binding.copybook_digits] or "0"), binding
        )
    raise ValueError(
        f"{binding.column} has usage {binding.copybook_usage!r}, which "
        f"MOVE SPACES cannot be modelled for"
    )


def _scaled_from_raw(raw: int, binding: _ColumnBinding) -> Decimal:
    """Place an implied decimal point in a raw integer, as ``V`` does.

    Args:
        raw: The integer the field's bytes decode to.
        binding: The field, carrying its scale.

    Returns:
        The value with the copybook's implied decimal point applied, exact.
    """
    if binding.copybook_scale == 0:
        return Decimal(raw)
    return Decimal(raw).scaleb(-binding.copybook_scale)


#: ``Purch-Stats-Date pic 9(4)`` [copybooks/wspl.cob:L53], the folder's only
#: WRITE-NOWHERE field: it is declared in BOTH record layouts - the copybook's
#: and the bridge's own hard-coded copy - and it has NO host variable in the
#: ``/MYSQL VAR\\`` group [common/purchMT.cbl:L285-L313], is loaded by NO
#: statement of ``bb000-HV-Load`` [common/purchMT.cbl:L1212-L1250], is unloaded
#: by NO statement of ``bb100-UnloadHVs`` [common/purchMT.cbl:L1258-L1288], and
#: has NO column in the frozen schema [mysql/ACASDB.sql:L646-L677]. It reaches
#: the database nowhere. Adding a column for it would be schema evolution, which
#: rule R-3 forbids outright, so it is recorded and left unreachable. A binding
#: is built for it here ONLY so that the group ``MOVE SPACES`` of
#: [common/acas022.cbl:L435] can reach it, which in COBOL it does.
_STATS_DATE_BINDING: Final[_ColumnBinding] = _ColumnBinding(
    column="PURCH-STATS-DATE",
    ordinal=0,
    attribute="purch_stats_date",
    host_variable="",
    kind="int",
    digits=4,
    scale=0,
    width=0,
    signed=False,
    copybook_signed=False,
    copybook_usage="DISPLAY",
    copybook_digits=4,
    copybook_scale=0,
    copybook_width=0,
    edit_start=0,
    edit_length=0,
    citation="[copybooks/wspl.cob:L53] - no host variable, no column",
    drift_details=(
        "declared in copybooks/wspl.cob:L53 and in the bridge's own record "
        "copy, absent from common/purchMT.cbl:L285-L313, from the load at "
        ":L1212-L1250, from the unload at :L1258-L1288 and from "
        "mysql/ACASDB.sql:L646-L677 - the folder's only write-nowhere field"
    ),
)


def _copy_rdbms_flat_statuses(
    system: SystemRecord, file_access: FileAccess
) -> None:
    """``move RDBMS-Flat-Statuses to FA-RDBMS-Flat-Statuses``.

    [common/acas022.cbl:L317], carrying the maintainer's own doubt on the same
    line: "needed for DAL? not JC/dbpre versions". The copy is made because the
    frozen source makes it, whatever the doubt - and because it is the only route
    by which the two-digit block reaches ``File-Access``, where a downstream
    reader would look for it [copybooks/wssystem.cob:L111-L124].

    Args:
        system: The source block, ``05 RDBMS-Flat-Statuses`` inside the system
            data block.
        file_access: The destination block.
    """
    source = system.system_data_block.rdbms_flat_statuses
    destination = file_access.fa_rdbms_flat_statuses
    # `07 File-System-Used pic 9.` [copybooks/wssystem.cob:L112] and
    # `07 File-Duplicates-In-Use pic 9.` [copybooks/wssystem.cob:L123].
    destination.fa_file_system_used = int(source.file_system_used) % 10
    destination.fa_file_duplicates_in_use = (
        int(source.file_duplicates_in_use) % 10
    )


def aa020_process_open(
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa020-Process-Open.`` [common/acas022.cbl:L363-L400].

    Four arms on ``Access-Type``, in the frozen order, each nested inside the
    previous one's ``else``.

    ``fn-input`` [common/acas022.cbl:L366-L372] reports ``35`` on failure -
    "file not found" - and then CLOSES the file it just failed to open
    [common/acas022.cbl:L370]. ANOMALY ``N-close-after-failed-open``: the close
    can only fail in its turn, and its status is discarded because the very next
    statement is the jump out. Reproduced by issuing the close and ignoring what
    it returns.

    ``fn-i-o`` [common/acas022.cbl:L374-L381] carries the maintainer's
    open-i-o-does-not-create workaround, comment and all: on failure close, open
    OUTPUT to bring the file into existence, close again, then reopen i-o
    ("Doesnt create in i-o", [common/acas022.cbl:L378]). Four more file
    operations whose statuses are all discarded.

    ``fn-output`` [common/acas022.cbl:L383-L384] is a PLAIN OPEN, with the
    maintainer's "caller should check fs-reply". ANOMALY ``N-noopenoutput``:
    ``acas022`` has NO ``if fn-Open and fn-output`` block anywhere - verified by
    census, there is no ``fn-Open and`` match in the file - so opening for output
    DELETES NOTHING. Two sibling handlers coerce the function into a delete-all at
    this point and one of them does it with two bridge calls; neither coercion is
    ported. The bridge corroborates from its own side: its only ``DELETE`` is the
    single-row one at [common/purchMT.cbl:L939].

    ``fn-extend`` [common/acas022.cbl:L386-L391] is REFUSED, ``(99, 997)``, with
    the actual ``open extend`` commented out beneath the comment "Must not be used
    for ISAM files". ANOMALY ``N-open-extend-refused``.

    ANOMALY ``N-open-999-overwrite`` and ANOMALY
    ``N-open-999-vs-35-asymmetry`` [common/acas022.cbl:L398-L399]. The
    trailing ``if fs-reply not = zero move 999 to WE-Error.``, annotated "added
    18/02/2023", OVERWRITES whatever diagnostic ``We-Error`` already held, and it
    is reached by the i-o and output arms but NOT by the input arm, which jumped
    out with 35 and left ``We-Error`` at whatever it held. So one open failure
    reports ``(35, unchanged)`` and another reports ``(status, 999)``. Neither is
    normalised.

    ANOMALY ``N-999-two-meanings``: the code this statement writes is documented
    two different ways by the two programs this module reimplements. The handler's
    own legend reads ``999  = Undefined / unknown error``
    [common/acas022.cbl:L168], while its bridge's legend reads
    ``999  = Not used here - Yet.`` [common/purchMT.cbl:L134] - and the sibling
    bridge carries that second wording verbatim at the same line number
    [common/glpostingMT.cbl:L134], so it is a pasted legend rather than a
    considered one. ``dal/status.py`` names the constant after the bridge's
    reading (``NOT_USED``), which is why the value is written here through
    ``WeError.NOT_USED`` even though the handler calls it an undefined error.
    Recorded, not arbitrated: the STORED value is 999 either way, so no scenario
    diff can distinguish the two readings.

    Args:
        file_access: The block whose status, ``Cobol-File-Status`` stand-in and
            log key are written.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    # `move spaces to WS-File-Key.` [common/acas022.cbl:L364], commented "for
    # logging", BEFORE the paragraph stamp.
    _file_key(file_access, "")
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa020-Process-Open"])
    access_type = int(file_access.access_type)
    if access_type == int(AccessType.INPUT):
        file_access.fs_reply = purchase_file.open_input() % 100
        if int(file_access.fs_reply) != 0:
            # `move 35 to fs-Reply` [common/acas022.cbl:L369] - 35 is the COBOL
            # file status for a non-optional file that is not there.
            file_access.fs_reply = 35
            # ANOMALY N-close-after-failed-open [common/acas022.cbl:L370]; the
            # status is discarded.
            purchase_file.close()
            aa999_main_exit(file_access, dal_common)  # Class 3.
            return
    elif access_type == int(AccessType.I_O):
        file_access.fs_reply = purchase_file.open_io() % 100
        if int(file_access.fs_reply) != 0:
            # The create-by-open-output workaround [common/acas022.cbl:L377-L380].
            # Every one of these four statuses is discarded by the frozen source.
            purchase_file.close()
            purchase_file.open_output()
            purchase_file.close()
            file_access.fs_reply = purchase_file.open_io() % 100
    elif access_type == int(AccessType.OUTPUT):
        # A PLAIN open - N-noopenoutput. Nothing is deleted.
        file_access.fs_reply = purchase_file.open_output() % 100
    elif access_type == int(AccessType.EXTEND):
        # N-open-extend-refused [common/acas022.cbl:L386-L391].
        _status(file_access, FsReply.ERROR, WeError.ACCESS_TYPE_WRONG)
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    # `move zeros to FS-Reply WE-Error.` is COMMENTED OUT at
    # [common/acas022.cbl:L395], dated 27/07/16 - a deliberate
    # non-initialisation, left alone.
    _reset_cobol_file_status(file_access)
    _file_key(file_access, "OPEN Purchase Ledger File")
    if int(file_access.fs_reply) != 0:
        # ANOMALY N-open-999-vs-35-asymmetry [common/acas022.cbl:L398-L399].
        file_access.we_error = int(WeError.NOT_USED)
    # `go to aa999-main-exit.` [common/acas022.cbl:L400] - Class 3, carrying the
    # comment "with test for dup processing" for a test that is not there.
    aa999_main_exit(file_access, dal_common)


def aa030_process_close(
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa030-Process-Close.`` [common/acas022.cbl:L402-L413].

    ANOMALY ``N-close-logs-twice``. The tail of this paragraph is
    [common/acas022.cbl:L409-L413]::

        perform  aa999-main-exit.
        move     zero to  File-Function
                          Access-Type.              *> close log file
        perform  Ca-Process-Logs.
        go       to aa-main-exit.

    ``aa999-main-exit`` is itself ``if Testing-1 perform Ca-Process-Logs``
    [common/acas022.cbl:L580-L582], so the close writes a log record through the
    switch and then writes a SECOND one UNCONDITIONALLY, with ``File-Function``
    and ``Access-Type`` zeroed - the "close log file" sentinel the logger reads.
    No other paragraph in the handler does this. Both records are reproduced, in
    order, and the zeroing happens between them exactly as the frozen source has
    it, because the second record's content depends on it.

    Args:
        file_access: The block whose status and log key are written, and whose
            ``File-Function`` and ``Access-Type`` this paragraph ZEROES.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa030-Process-Close"])
    _file_key(file_access, "")
    file_access.fs_reply = purchase_file.close() % 100
    # `move zeros to FS-Reply WE-Error.` commented out at
    # [common/acas022.cbl:L406] - the same deliberate non-initialisation.
    _reset_cobol_file_status(file_access)
    _file_key(file_access, "CLOSE Purchase Ledger File")
    # A PERFORM, not a GO TO [common/acas022.cbl:L409].
    aa999_main_exit(file_access, dal_common)
    # `move zero to File-Function Access-Type.` [common/acas022.cbl:L410-L411].
    file_access.file_function = 0
    file_access.access_type = 0
    # The SECOND, unconditional record [common/acas022.cbl:L412].
    ca_process_logs(file_access, dal_common)
    # `go to aa-main-exit.` [common/acas022.cbl:L413] - Class 3.
    aa_main_exit()


def aa040_process_read_next(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa040-Process-Read-Next.`` [common/acas022.cbl:L415-L445].

    The paragraph function code 3 reaches - AND function code 31, because the
    handler's dispatch folds ``when 31`` into ``when 3``
    [common/acas022.cbl:L343-L345]. On the ISAM path there is therefore no
    name-ordered read at all, no different key and no different call; anomaly
    ``N-31-two-meanings`` is the fact that the BRIDGE does have one
    [common/purchMT.cbl:L441-L442]. Both halves are reproduced, each in its own
    place, and neither is made to agree with the other.

    ANOMALY ``N-stop``. The end-of-file pre-test carries a bare
    ``stop "Cobol File EOF"`` annotated "for testing"
    [common/acas022.cbl:L427] - a debugging statement that halts the run in
    shipped source, left inside a branch that also sets a clean end-of-file
    status. It is SPLIT, per AAP section 0.3.4: the DISPLAY half becomes one record
    at ERROR through :func:`acas_posting.dal.status.log_cobol_stop`, identical in
    wording and level to every sibling handler's, and the HALT half is deliberately
    omitted - a pause has no database effect, and reproducing it would make the
    migrated cycle unrunnable. The branch's status, log key and control transfer are
    all preserved, and the omission is recorded here and in
    ``docs/migration/anomaly-log.md``.

    ANOMALY ``N-spaces-into-key`` [common/acas022.cbl:L424]. The pre-test moves
    SPACES into ``Purch-Key``, the ISAM record's ``pic x(7)`` key. Spaces, not
    zeros - and the low key every other part of the system uses is ``"0000000"``.
    Reproduced literally.

    ANOMALY ``N-spaces-into-record`` [common/acas022.cbl:L435]. At end of file the
    paragraph does ``move spaces to Purch-Record``, where the sibling handler in
    the same position does ``initialize``
    [common/acas019.cbl:L379]. ``INITIALIZE`` sets numeric fields to zero and
    alphanumeric fields to spaces; ``MOVE SPACES`` writes the space character over
    the whole record, INCLUDING the ``binary-char``, ``binary-long`` and
    ``comp-3`` fields, whose bytes then decode to whatever the space bit pattern
    means in that usage. Reproduced literally rather than corrected.

    ANOMALY ``N-double-zero`` [common/acas022.cbl:L443]. The success path zeroes
    BOTH ``FS-Reply`` and ``WE-Error`` where the sibling zeroes only ``WE-Error``
    [common/acas019.cbl:L387].

    ANOMALY ``N-no-aa041``. There is no ``aa041-*`` paragraph in this handler at
    all - the log key is built by a direct move of the record key
    [common/acas022.cbl:L442] - even though its own SALES mirror ``acas012`` has
    an ``aa041-Reread``. No such function is added here for symmetry.

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, filled on success.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa040-Process-Read-Next"])
    if _cobol_file_eof():
        # `if Cobol-File-Eof` [common/acas022.cbl:L421-L428]. The flag is
        # handler-local WORKING-STORAGE [common/acas022.cbl:L256-L257], NOT a
        # field of any linkage record, and this paragraph is the only one that
        # sets it - seven other statements clear it, so a caller that reads to
        # end of file and then reads again WITHOUT reopening takes this branch
        # rather than reaching the file at all.
        _status(file_access, FsReply.END_OF_FILE, int(FsReply.END_OF_FILE))
        # `move spaces to Purch-Key SQL-Err SQL-Msg`
        # [common/acas022.cbl:L424-L426] - N-spaces-into-key. Note SQL-Err and
        # SQL-Msg are cleared here but SQL-State again is NOT.
        purchase_file.record.ws_purch_key = " " * KEY_OF_REFERENCE.kor_length
        file_access.logging_data.sql_err = " " * 5
        file_access.logging_data.sql_msg = " " * 512
        # `stop "Cobol File EOF"` [common/acas022.cbl:L427] - N-stop.
        #  ONE ERROR, THROUGH THE ONE REPORTER, at the SAME LEVEL and in the
        #  same words as every sibling handler that carries this statement. `STOP`
        #  with a literal DISPLAYS the literal and then waits, so the display is a
        #  record and only the WAIT is the omission. Emitting nothing here, while
        #  acas006 and acas007 logged it at WARNING, acas012 at INFO, acas016 at
        #  DEBUG and acas019 at ERROR, meant one event had five different renderings
        #  and, in this module, none at all.
        log_cobol_stop(
            _LOG,
            program=PROG_NAME,
            paragraph="aa040-Process-Read-Next",
            literal="Cobol File EOF",
            locator="[common/acas022.cbl:L427]",
        )
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    # `read Purchase-File next record` [common/acas022.cbl:L431]. THE SELECT
    # DECLARES `status fs-reply` [copybooks/selpl.cob:L5], so the verb itself
    # writes its file status into FS-Reply - the field is the FD's status item,
    # not merely a return value the paragraph may choose to inspect. Storing it
    # is what makes the test two statements below meaningful: without it the
    # paragraph would test whatever status the CALLER happened to leave behind,
    # and a successful read would return a stale non-zero reply.
    file_access.fs_reply = purchase_file.read_next() % 100
    if int(file_access.fs_reply) != 0:
        # `read ... next record at end` [common/acas022.cbl:L431-L438]. The AT END
        # phrase overrides the status clause's own value with a literal 10 in BOTH
        # fields [common/acas022.cbl:L432].
        _status(file_access, FsReply.END_OF_FILE, int(FsReply.END_OF_FILE))
        _set_cobol_file_eof(file_access)
        # `move spaces to Purch-Record` - N-spaces-into-record.
        _move_spaces_to_purch_record(purchase_file.record)
        _file_key(file_access, "EOF")
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    if int(file_access.fs_reply) != 0:
        # `if FS-Reply not = zero go to aa999-main-exit.`
        # [common/acas022.cbl:L439-L440] - unreachable in practice, because the
        # `at end` branch above is the only thing that sets it non-zero and it
        # jumps out. Reproduced, not pruned.
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    # `move Purch-Record to WS-Purch-Record.` [common/acas022.cbl:L441].
    _copy_purch_record(purchase_file.record, purch)
    # `move WS-Purch-Key to WS-File-Key.` [common/acas022.cbl:L442] - the
    # DESTINATION record's key, read back after the move above.
    _file_key(file_access, purch.ws_purch_key)
    # N-double-zero [common/acas022.cbl:L443].
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    aa999_main_exit(file_access, dal_common)  # Class 3.


def aa045_eval_keys(
    file_access: FileAccess,
    purch: WsPurchRecord,
    purchase_file: PurchaseFile,
) -> None:
    """``aa045-Eval-Keys.`` [common/acas022.cbl:L446-L464].

    The paragraph the maintainer himself doubts. Its own preceding comment reads
    [common/acas022.cbl:L446]::

        *>   The next block will never get executed unless performed  so is it needed ?

    It IS performed - from ``aa050-Process-Read-Indexed``
    [common/acas022.cbl:L471], and from nowhere else. So the doubt is half right:
    the paragraph runs, but only ever with ``File-Function = 4``.

    ANOMALY ``N-deadbranches``. The ``evaluate`` has five function arms - 4, 5, 7,
    8 and 9 - falling through to one shared body, and FOUR of them are
    unreachable, because the only caller is the read-indexed path. The comment
    beside ``when 8`` even reasons about a case that can never arise: "For delete
    can ignore Desc key" [common/acas022.cbl:L453]. Every arm is reproduced,
    dead ones included; pruning them would delete the evidence.

    ANOMALY ``N-dual-key-destination`` [common/acas022.cbl:L457-L458]. The
    ``when 1`` arm moves the caller's key into TWO receivers - the log key AND the
    ISAM record's own key field - in one statement. The second destination is not
    logging at all: it is what positions the subsequent ``read ... key
    Purch-Key``, so the paragraph's stated purpose, "Set up keys just for
    logging" [common/acas022.cbl:L449], is wrong about its own effect.

    ANOMALY ``N-eval-keys-case-drift``. The label is ``aa045-Eval-Keys``
    [common/acas022.cbl:L448] and the ``perform`` that reaches it spells it
    ``aa045-Eval-keys`` [common/acas022.cbl:L471]. COBOL is case-insensitive so
    both resolve; the drift is preserved as a comment rather than normalised.

    Args:
        file_access: The block whose log key is written.
        purch: The caller's record, supplying the key.
        purchase_file: The ISAM store, whose record's own key field is the SECOND
            destination of the ``when 1`` move.
    """
    function = int(file_access.file_function)
    if function in _AA045_FUNCTIONS:
        # `when 4 / when 5 / when 7 / when 8 / when 9`
        # [common/acas022.cbl:L450-L454]. Only 4 ever arrives; 5, 7, 8 and 9 are
        # N-deadbranches.
        if int(file_access.logging_data.file_key_no) == ONLY_KEY_NUMBER:
            # N-dual-key-destination [common/acas022.cbl:L457-L458].
            _file_key(file_access, purch.ws_purch_key)
            purchase_file.record.ws_purch_key = _purch_rec_key(purch)
        else:
            # `when other move spaces to WS-File-Key`
            # [common/acas022.cbl:L459-L460]; unreachable for functions 4, 8 and
            # 9 because the guard at [common/acas022.cbl:L298-L312] already
            # rejected any other key number, and unreachable for 5 and 7 because
            # they never arrive.
            _file_key(file_access, "")
        return
    # `when other move spaces to WS-File-Key` [common/acas022.cbl:L462-L463].
    _file_key(file_access, "")


def aa050_process_read_indexed(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa050-Process-Read-Indexed.`` [common/acas022.cbl:L466-L487].

    ANOMALY ``N-readindexed-23``, the handler half. Not found reports ``21`` in
    BOTH fields here [common/acas022.cbl:L475] where the bridge reports ``23``
    with ``We-Error`` zeroed [common/purchMT.cbl:L703-L705], under the bridge
    maintainer's own note that it "could also be 21 or 14". One handler, one
    condition, two answers.

    ANOMALY ``N-readindexed-spaces-on-miss`` [common/acas022.cbl:L481]. On a miss
    the paragraph writes SPACES over the CALLER's record - not the file's - so a
    failed read destroys the key the caller passed in, and a caller that retries
    without rebuilding it searches for spaces. The bridge does not do this: its
    miss path leaves the caller's record alone entirely.

    The last three statements [common/acas022.cbl:L485-L487] are unreachable, and
    the maintainer says so in the comment: "file seeks key type out of range but
    should never get here". They are unreachable twice over - the ``if File-Key-No
    = 1`` above jumps out on the only reachable path, and the guard at
    [common/acas022.cbl:L298-L305] already rejected any other key number with the
    same 998. Reproduced.

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, filled on success and SPACE-FILLED on a miss.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa050-Process-Read-Indexed"])
    # `perform aa045-Eval-keys.` [common/acas022.cbl:L471] - N-eval-keys-case-
    # drift, and the only call site of that paragraph.
    aa045_eval_keys(file_access, purch, purchase_file)
    _reset_cobol_file_status(file_access)
    if int(file_access.logging_data.file_key_no) == ONLY_KEY_NUMBER:
        status = purchase_file.read_by_key(
            _purch_rec_key(purchase_file.record)
        )
        if status != 0:
            # `invalid key move 21 to we-error fs-reply`
            # [common/acas022.cbl:L475] - N-readindexed-23, handler half. BOTH
            # fields get 21, so We-Error carries a value the authoritative table
            # does not define.
            _status(file_access, FsReply.INVALID_KEY_ON_START, 21)
        else:
            # The SELECT's `status fs-reply` clause [copybooks/selpl.cob:L5]
            # writes the verb's own status, which is what the test below reads.
            file_access.fs_reply = 0
        if int(file_access.fs_reply) == 0:
            _copy_purch_record(purchase_file.record, purch)
            _file_key(file_access, _purch_rec_key(purchase_file.record))
        else:
            # N-readindexed-spaces-on-miss [common/acas022.cbl:L481].
            _move_spaces_to_purch_record(purch)
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    # Unreachable [common/acas022.cbl:L485-L487]; preserved.
    _status(file_access, FsReply.ERROR, WeError.FILE_KEY_NO_OUT_OF_RANGE)
    aa999_main_exit(file_access, dal_common)  # Class 3.


def aa060_process_start(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa060-Process-Start.`` [common/acas022.cbl:L489-L535].

    "Check for Param error 1st on start   WARNING Not logging starts"
    [common/acas022.cbl:L491] - and the warning is accurate: this paragraph is the
    only one in the handler that never writes a diagnostic of its own beyond the
    key.

    ANOMALY ``N-start-guard-leaves-fs-reply-zero``, and it is the sharpest defect
    in the handler. The order of the first four statements is
    [common/acas022.cbl:L493-L503]: stamp, ``move zeros to fs-reply WE-Error``,
    the key moves, THEN the guard - and the guard writes ``We-Error`` ONLY::

        if       access-type < 5 or > 8                   *> NOT using 'not >'
                 move 998 to WE-Error                     *> 998 Invalid calling parameter settings
                 go to aa999-main-exit
        end-if

    ``Fs-Reply`` was zeroed two statements earlier and is never touched again, so
    a rejected start returns ``(0, 998)``. A caller that tests ``Fs-Reply`` - which
    is what the facade's callers do - is told the start SUCCEEDED. The bridge
    reports ``(99, 997)`` for the identical input [common/purchMT.cbl:L780-L783],
    so the two halves differ in the code AND in whether the failure is visible at
    all. Reproduced exactly; anomaly ``N-start-guard-998-vs-997`` covers the code
    difference.

    ANOMALY ``N-dual-key-destination``, second site
    [common/acas022.cbl:L497-L498]: the key goes to the log key and the ISAM
    record's key field in one statement, and here the second destination is what
    every one of the four ``start`` statements below positions on.

    ANOMALY ``N-start-four-longhand-blocks``. There is no ``evaluate``: four
    separate ``if File-Key-No = 1 and fn-...`` blocks, one per relation, each
    re-testing the key number the guard above already constrained
    [common/acas022.cbl:L507-L534]. ``fn-not-greater-than`` (9) has NO block,
    consistent with the guard's ``> 8`` - so the bridge's ``when 9`` relation arm
    [common/purchMT.cbl:L809-L810] has no counterpart here either, which is what
    makes ``N-access-type-9-dead-in-bridge`` dead on both paths.

    Falling off the end reports ``(0, 0)`` - a start that positioned nothing,
    reported as success [common/acas022.cbl:L535]. Reachable only if the access
    type passed the guard and no relation matched, which cannot happen; preserved
    anyway.

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, supplying the key.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa060-Process-Start"])
    # `move zeros to fs-reply WE-Error.` [common/acas022.cbl:L494-L495] - BEFORE
    # the guard, which is what makes N-start-guard-leaves-fs-reply-zero possible.
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    _reset_cobol_file_status(file_access)
    # N-dual-key-destination, second site [common/acas022.cbl:L497-L498].
    _file_key(file_access, purch.ws_purch_key)
    purchase_file.record.ws_purch_key = _purch_rec_key(purch)
    access_type = int(file_access.access_type)
    if (
        access_type < int(AccessType.EQUAL_TO)
        or access_type > int(AccessType.NOT_LESS_THAN)
    ):
        # `move 998 to WE-Error` ONLY [common/acas022.cbl:L500-L502].
        # Fs-Reply stays at the zero set above - N-start-guard-leaves-fs-reply-
        # zero.
        file_access.we_error = int(WeError.FILE_KEY_NO_OUT_OF_RANGE)
        aa999_main_exit(file_access, dal_common)  # Class 3.
        return
    key_number = int(file_access.logging_data.file_key_no)
    for relation in _AA060_RELATIONS:
        # The four longhand blocks [common/acas022.cbl:L507-L534], in their frozen
        # order: equal-to, less-than, greater-than, not-less-than.
        if key_number == ONLY_KEY_NUMBER and access_type == relation:
            if purchase_file.start(relation) != 0:
                # `invalid key move 21 to Fs-Reply` - We-Error is NOT set, so it
                # keeps the zero from entry.
                file_access.fs_reply = int(FsReply.INVALID_KEY_ON_START)
            aa999_main_exit(file_access, dal_common)  # Class 3.
            return
    # `go to aa999-main-exit.` [common/acas022.cbl:L535] with (0, 0) intact.
    aa999_main_exit(file_access, dal_common)


def aa070_process_write(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa070-Process-Write.`` [common/acas022.cbl:L537-L546].

    ``move WS-Purch-Record to Purch-Record`` [common/acas022.cbl:L539] then the
    write. The two layouts are field-for-field identical - verified by comparing
    ``copybooks/wspl.cob`` against ``copybooks/fdpl.cob`` picture clause by
    picture clause - so this move is a straight copy and not a reinterpretation.
    That identity is also what makes the record-length guard in
    :func:`ba012_test_ws_rec_size_2` unreachable.

    ``invalid key move 22 to FS-Reply`` [common/acas022.cbl:L544] - a duplicate
    key on the ISAM path reports 22 and leaves ``We-Error`` at the zero set two
    statements earlier, which is the same shape the bridge's duplicate path
    produces through the shared failure paragraph
    [copybooks/mysql-procedures.cpy:L103-L104]. The two halves agree here, which
    is worth stating because they disagree on five other statuses.

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, copied into the file's record area.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa070-Process-Write"])
    _copy_purch_record(purch, purchase_file.record)
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    _reset_cobol_file_status(file_access)
    # `move Purch-Key to WS-File-Key.` [common/acas022.cbl:L542] - the FILE's key,
    # read after the copy, where the delete path uses the CALLER's key instead.
    _file_key(file_access, _purch_rec_key(purchase_file.record))
    if purchase_file.write() != 0:
        file_access.fs_reply = int(FsReply.DUPLICATE_KEY)
    aa999_main_exit(file_access, dal_common)  # Class 3.


def aa080_process_delete(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa080-Process-Delete.`` [common/acas022.cbl:L548-L558].

    ANOMALY ``N-delete-copies-whole-record``. The paragraph copies the ENTIRE
    caller record into the file's record area [common/acas022.cbl:L550] before
    deleting by key. A ``DELETE`` needs only the key, so the other twenty-eight
    fields are moved for nothing - and worse, the move leaves the file's record
    area holding data that was never written, which the next sequential read
    overwrites but a subsequent ``rewrite`` would not. The bridge's delete builds
    a key predicate and touches nothing else
    [common/purchMT.cbl:L916-L926]. Reproduced.

    ANOMALY ``N-dual-key-destination``, third site
    [common/acas022.cbl:L551-L552]: ``move WS-Purch-Key to Purch-Key WS-File-Key``
    - and note the receivers are in the OPPOSITE order to the other two sites,
    which write the log key first.

    ``invalid key move 21`` [common/acas022.cbl:L556] where the bridge reports
    ``(99, 995)`` for a delete that matched no row
    [common/purchMT.cbl:L954-L955].

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, supplying the key - and, needlessly, the rest.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa080-Process-Delete"])
    # N-delete-copies-whole-record [common/acas022.cbl:L550].
    _copy_purch_record(purch, purchase_file.record)
    # N-dual-key-destination, third site, receivers reversed
    # [common/acas022.cbl:L551-L552].
    purchase_file.record.ws_purch_key = _purch_rec_key(purch)
    _file_key(file_access, purch.ws_purch_key)
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    _reset_cobol_file_status(file_access)
    if purchase_file.delete() != 0:
        file_access.fs_reply = int(FsReply.INVALID_KEY_ON_START)
    aa999_main_exit(file_access, dal_common)  # Class 3.


def aa090_process_rewrite(
    file_access: FileAccess,
    purch: WsPurchRecord,
    dal_common: AcasDalCommonData,
    purchase_file: PurchaseFile,
) -> None:
    """``aa090-Process-Rewrite.`` [common/acas022.cbl:L560-L570].

    ``invalid key move 21 to FS-Reply`` [common/acas022.cbl:L568], against the
    bridge's ``(99, 994)`` [common/purchMT.cbl:L1000-L1001]. Note also that the
    ``end-rewrite`` at [common/acas022.cbl:L569] is NOT followed by a period,
    where ``end-write`` and ``end-delete`` in the two paragraphs above both are -
    a punctuation inconsistency with no effect here, because the next statement is
    a ``go to`` either way. Left as it is.

    Args:
        file_access: The block whose status and log key are written.
        purch: The caller's record, copied into the file's record area.
        dal_common: The logging switches.
        purchase_file: The caller's ISAM store.
    """
    _stamp(file_access, HANDLER_PARAGRAPH_NUMBERS["aa090-Process-Rewrite"])
    _copy_purch_record(purch, purchase_file.record)
    _file_key(file_access, _purch_rec_key(purchase_file.record))
    _status(file_access, FsReply.SUCCESS, WeError.SUCCESS)
    _reset_cobol_file_status(file_access)
    if purchase_file.rewrite() != 0:
        file_access.fs_reply = int(FsReply.INVALID_KEY_ON_START)
    aa999_main_exit(file_access, dal_common)  # Class 3.


def aa100_bad_function(file_access: FileAccess) -> None:
    """``aa100-Bad-Function.`` [common/acas022.cbl:L572-L577].

    "Houston; We have a problem" [common/acas022.cbl:L574] - the same joke the
    bridge tells [common/purchMT.cbl:L1171], and the same idea with a different
    answer.

    ANOMALY ``N-badfunction-990-vs-999``. ``(99, 999)`` here
    [common/acas022.cbl:L576-L577] against the bridge's ``(99, 990)``
    [common/purchMT.cbl:L1173-L1174], and note ``We-Error`` is assigned first in
    both, with 999 documented as "not used" and 990 as "unknown/unexpected". The
    handler therefore reports an invalid function with the code reserved for
    nothing.

    ANOMALY ``N-badfunction-falls-through``. There is NO ``go to`` here
    [common/acas022.cbl:L577]; control falls into ``aa999-main-exit``
    [common/acas022.cbl:L579], which is also reached by the unconditional
    ``go to aa100-Bad-Function`` at [common/acas022.cbl:L361] beneath the comment
    "Should never get here but in case :(". So this paragraph has TWO entries -
    the ``when other`` arm and that fall-through - and the AAP section 0.4.2 class
    differs between them: the ``when other`` arm is Class 4, the trailing
    ``go to`` is Class 2.

    Args:
        file_access: The block whose status pair is written.
    """
    # `move 999 to WE-Error.` then `move 99 to fs-reply.`
    _status(file_access, FsReply.ERROR, WeError.NOT_USED)
    # No transfer: falls through into aa999-main-exit.


def aa999_main_exit(
    file_access: FileAccess, dal_common: AcasDalCommonData
) -> None:
    """``aa999-main-exit.`` [common/acas022.cbl:L579-L582].

    ``if Testing-1 perform Ca-Process-Logs end-if.`` - the handler's flat-file
    convergence point, and the ONLY place the flat-file path logs, except for the
    close, which logs twice (``N-close-logs-twice``).

    Args:
        file_access: The block passed to the logger.
        dal_common: Carries ``SW-Testing``; its ``88 Testing-1 value 1``
            [copybooks/Test-Data-Flags.cob:L11] gates the call.
    """
    if dal_common.sw_testing == 1:
        ca_process_logs(file_access, dal_common)
    # Falls through into aa-main-exit.


def aa_main_exit() -> None:
    """``aa-main-exit.`` [common/acas022.cbl:L584-L586].

    An empty label carrying only the comment "Now have processed cobol flat file,
    so .." and falling through into ``aa-Exit``. Kept as a named function because
    rule R-5 maps every paragraph, and because the RDB branch jumps HERE by name
    [common/acas022.cbl:L319] rather than to ``aa-Exit``.
    """
    return


def aa_exit() -> None:
    """``aa-Exit.`` [common/acas022.cbl:L588-L589].

    ``exit program.`` - the handler's return to its caller. Returning from
    :func:`dispatch` IS this statement.
    """
    return


def ba_process_rdbms(
    system: SystemRecord,
    purch: WsPurchRecord,
    file_access: FileAccess,
    file_defs: FileDefs,
    dal_common: AcasDalCommonData,
    *,
    transport: TransportSecurity | None,
) -> None:
    """``ba-Process-RDBMS section.`` [common/acas022.cbl:L591-L668].

    "Here we call the relevent RDBMS module for this table / which will include
    processing any other joined tables as needed"
    [common/acas022.cbl:L595-L597]. For this table there are no joined tables:
    ``PULEDGER-REC`` stands alone, unlike the two invoice handlers that own a
    header table and a lines table each.

    Entered at ``ba010-Test-WS-Rec-Size`` [common/acas022.cbl:L599] and falling
    through it into ``ba012-Test-WS-Rec-Size-2``
    [common/acas022.cbl:L607] and then into ``ba015-Test-Ends``
    [common/acas022.cbl:L649], with no transfer between any of them - three
    paragraphs, one straight line.

    Args:
        system: The system record, whose ``RDBMS`` fields the credential load
            reads on the first call only.
        purch: The caller's record, handed to the bridge.
        file_access: The ``File-Access`` block.
        file_defs: The file-name block. Carried for linkage fidelity; the RDB path
            addresses a TABLE and never a file name, so nothing here reads it.
        dal_common: The logging switches.
        transport: The transport policy for the open path.
    """
    ba010_test_ws_rec_size(file_access)
    if not ba012_test_ws_rec_size_2(system, purch, file_access, dal_common):
        # `go to ba-rdbms-exit` [common/acas022.cbl:L634] - Class 3.
        ba_rdbms_exit()
        return
    ba015_test_ends(
        purch, file_access, dal_common, system=system, transport=transport
    )
    ba_rdbms_exit()


def ba010_test_ws_rec_size(file_access: FileAccess) -> None:
    """``ba010-Test-WS-Rec-Size.`` [common/acas022.cbl:L599-L605].

    A single statement, ``move 21 to WS-Log-File-no.`` annotated "for FHlogger"
    [common/acas022.cbl:L605], and then a fall-through into the paragraph that
    does the actual work.

    ANOMALY ``N-log``. ``aa010-main`` set ``WS-Log-File-No`` to 11
    [common/acas022.cbl:L294]; this overwrites it with 21 - and it is reached ONLY
    on the RDB path, because ``aa010-main`` performs ``ba012-Test-WS-Rec-Size-2``
    DIRECTLY when it wants the record-length guard alone
    [common/acas022.cbl:L324], skipping this paragraph. So the flat-file path logs
    file 11 and the RDB path logs file 21, for the same table.

    ANOMALY ``N-log-case-flip``. The field is spelled ``WS-Log-File-No`` at
    [common/acas022.cbl:L294] and ``WS-Log-File-no`` here. Preserved as written.

    ANOMALY ``N-log-collides-with-acas012``. The sales handler uses the SAME
    numbers, 11 then 21, distinguished only by ``WS-Log-System`` - 3 for sales,
    4 here [common/acas022.cbl:L293]. A log reader that ignored the system field
    would attribute purchase-ledger activity to the sales ledger.

    Args:
        file_access: The block whose ``WS-Log-File-No`` is overwritten.
    """
    file_access.logging_data.ws_log_file_no = WS_LOG_FILE_NO_RDB
    # Falls through into ba012-Test-WS-Rec-Size-2.


def ba012_test_ws_rec_size_2(
    system: SystemRecord,
    purch: WsPurchRecord,
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
) -> bool:
    """``ba012-Test-WS-Rec-Size-2.`` [common/acas022.cbl:L607-L647].

    One first-call-only block doing two unrelated jobs - the record-length guard
    and the credential load - which is exactly why ANOMALY ``A-1``, reproduced by
    :func:`~acas_posting.dal.connection.load_rdb_data_once`, makes the credentials
    unre-readable for the rest of the run: ``A`` is assigned inside the guarded
    block, and the ``end-if`` at [common/acas022.cbl:L647] closes AFTER the six
    credential moves.

    ANOMALY ``N-901-unreachable`` - VERIFIED, not assumed. The guard compares
    ``function Length (WS-Purch-Record)`` against
    ``function length (Purch-Record)`` [common/acas022.cbl:L610-L615] and reports
    ``(99, 901)`` when the first is smaller. The two records are declared in
    ``copybooks/wspl.cob`` and ``copybooks/fdpl.cob``, and a picture-clause-by-
    picture-clause comparison of the two files finds them IDENTICAL - same 29
    fields, same usages, same widths, same trailing ``filler pic x(12)``
    [copybooks/wspl.cob:L14-L54 against copybooks/fdpl.cob:L16-L56]. So ``A``
    always equals ``B``, ``A < B`` is never true, and the entire 901 block is dead
    code. It is reproduced structurally so that the comparison still happens and
    still cannot fire.

    ANOMALY ``N-fdpl-self-reference``. ``copybooks/fdpl.cob:L10`` carries the
    comment "taken from fdpl.cob 23/07/16" - in fdpl.cob. The line was
    copy-pasted from ``copybooks/wspl.cob:L10``, where it is true, and the two
    files' identical header comments are why the two layouts are identical.

    The 901 panel's ``accept Accept-Reply at 2433`` [common/acas022.cbl:L633] is
    DELIBERATELY OMITTED per AAP section 0.3.4 - it pauses a terminal and gates no
    database write - while the two displays become one log record and the
    ``go to ba-rdbms-exit`` [common/acas022.cbl:L634] is preserved as this
    function's ``False`` return - AAP section 0.4.2 Class 3, a transfer to the
    section's own trailing exit label, so it becomes a return rather than a break;
    ``ba-rdbms-exit`` is ``exit section`` [common/acas022.cbl:L667-L668] and
    carries no post-exit work for a break to have to re-site. The message text itself is local to the handler:
    ``PL905 "PL905 Program Error: Temp rec = "`` and
    ``PL901 "PL901 Note error and hit return"``
    [common/acas022.cbl:L262-L263], declared nowhere else in the checkout.

    Args:
        system: The system record supplying the credentials on the first call.
        purch: The caller's record, one side of the length comparison.
        file_access: The block whose status pair and ``RDB-Data`` are written.
        dal_common: The logging switches.

    Returns:
        ``True`` to continue into ``ba015-Test-Ends``, ``False`` to take the
        ``go to ba-rdbms-exit`` the 901 branch takes. Always ``True`` in practice,
        because the comparison cannot fail.
    """
    global _WS_A, _WS_B
    if _WS_A != 0:
        # Second and later calls skip EVERYTHING, credential load included -
        # anomaly A-1 [common/acas022.cbl:L609, :L647].
        return True
    # `move function Length (WS-Purch-Record) to A` and the same for
    # `Purch-Record` [common/acas022.cbl:L610-L615]. Both lengths come from the
    # dictionary rather than from a hand-counted constant, and they are equal by
    # construction because the two copybooks are identical.
    _WS_A = _RECORD_DECLARED_LENGTH
    _WS_B = _RECORD_DECLARED_LENGTH
    if _WS_A < _WS_B:  # pragma: no cover - N-901-unreachable, verified dead
        _status(file_access, FsReply.ERROR, WeError.RECORD_SIZE_MISMATCH)
    if int(file_access.we_error) == int(
        WeError.RECORD_SIZE_MISMATCH
    ):  # pragma: no cover - unreachable with the frozen copybooks
        # The panel [common/acas022.cbl:L620-L635] splits THREE ways, not two:
        #   * the `display` of the assembled `PL905` diagnostic is the substance, so
        #     ONE record at ERROR - a programming error the caller must stop for.
        #   * the `display PL901` is "PL901 Note error and hit return"
        #     [common/acas022.cbl:L262] - the acknowledgement half, paired with the
        #     `accept` below it. AAP section 0.3.4 drops an acknowledgement pause
        #     ENTIRELY, and quoting its text in a log line is still emitting it, to a
        #     destination where no operator can answer it.
        #   * the `go to ba-rdbms-exit` is CONTROL, preserved as `return False`.
        _LOG.error(
            "%s %s%d < Purch-Rec = %d",
            PROG_NAME,
            _PL905,
            _WS_A,
            _WS_B,
        )
        if dal_common.sw_testing == 1:
            ca_process_logs(file_access, dal_common)
        return False
    # The six credential moves [common/acas022.cbl:L641-L646], in the frozen
    # order: schema, user, password, PORT, host, socket - note the port comes
    # before the host, which is not the order `RDB-Data` declares them in
    # [copybooks/wsfnctn.cob:L57-L62]. `load_rdb_data_once` owns the widths, the
    # truncation and anomaly A-1's first-call-only semantics; duplicating them
    # here would give two answers to one question.
    file_access.rdb_data = load_rdb_data_once(system)
    # The record is untouched by this paragraph; the parameter is present because
    # the COBOL reads its length.
    del purch
    return True


def ba015_test_ends(
    purch: WsPurchRecord,
    file_access: FileAccess,
    dal_common: AcasDalCommonData,
    *,
    system: SystemRecord,
    transport: TransportSecurity | None,
) -> None:
    """``ba015-Test-Ends.`` [common/acas022.cbl:L649-L665].

    This paragraph contains NO ``go to`` of any kind - verified across
    [common/acas022.cbl:L649-L665]. It issues the bridge ``call`` and then FALLS
    THROUGH into ``ba-rdbms-exit`` [common/acas022.cbl:L667], so there is no
    transfer site here to classify under the AAP section 0.4.2 taxonomy; the
    fall-through is made explicit by this function simply returning to
    ``ba_process_rdbms``, which performs the exit next.

    The bridge call, INLINE - there is no ``ba020-*`` paragraph in this handler,
    so no such function exists here either (``N-nobadal``). The call is
    [common/acas022.cbl:L659-L663]::

        call     "purchMT" using File-Access
                                 ACAS-DAL-Common-data

                                 WS-Purch-Record
        end-call.

    with a blank line inside the parameter list, and the handler's own
    ``WS-Purch-Record`` passed where the bridge's linkage names the parameter
    ``Purch-Rec``.

    ANOMALY ``N-cdftodo``. Four comment lines above the call record an unfinished
    design decision [common/acas022.cbl:L652-L657]: "HERE we need a CDF [Compiler
    Directive] to select the correct DAL based on the pre SQL compiler e.g., JCs
    or dbpre or Prima conversions <<<< ? >>>>>  Do this after system testing and
    pre code release." It was never done; the call is hard-wired to the JC
    variant, as the following comment says: "NOW SET UP FOR JC pre-sql compiler
    system."

    THE ERROR CONTRACT [common/acas022.cbl:L665]: "Any errors leave it to caller
    to recover from". Nothing is raised, nothing is retried, nothing is
    translated - the status pair the bridge wrote is what the caller gets.

    Args:
        purch: The caller's record, passed straight through.
        file_access: The ``File-Access`` block, passed straight through.
        dal_common: ``ACAS-DAL-Common-data``, passed straight through.
        system: Supplies the credentials to the bridge's open path.
        transport: The transport policy for that open path.
    """
    purch_mt(
        file_access,
        dal_common,
        purch,
        system_record=system,
        transport=transport,
    )


def ba_rdbms_exit() -> None:
    """``ba-rdbms-exit.`` [common/acas022.cbl:L667-L668].

    ``exit section.`` - and note it IS ``exit section`` here, where ``ca-Exit``
    two paragraphs later is a plain ``exit``
    [common/acas022.cbl:L677]. Preserved as a distinction rather than normalised.
    """
    return


def ca_process_logs(
    file_access: FileAccess, dal_common: AcasDalCommonData
) -> None:
    """``Ca-Process-Logs.`` [common/acas022.cbl:L671-L675].

    The comment sits on the LABEL LINE itself
    [common/acas022.cbl:L671]::

        Ca-Process-Logs.       *> Not called on DAL access as it does it already

    which is the handler's own statement of anomaly
    ``N-bridge-logs-handler-does-not`` and its handler-side half
    ``N-nolog-on-dal``: on the RDB path the bridge logs and the handler must
    not. Accordingly nothing in :func:`ba_process_rdbms`,
    :func:`ba010_test_ws_rec_size` or :func:`ba015_test_ends` calls this - the only
    callers are the flat-file convergence point, the close's second unconditional
    record, and the dead 901 panel, which is where the frozen source calls it from
    [common/acas022.cbl:L412, :L581, :L631].

    Its COBOL body is ``call "fhlogger" using File-Access ACAS-DAL-Common-data``
    [common/acas022.cbl:L674-L675]. Rule R-1 forbids calling a COBOL program, and
    ``common/fhlogger.cbl`` is out of scope per AAP section 0.2.2, so the record it
    would have written is emitted natively.

    Args:
        file_access: The block whose fields make up the record.
        dal_common: Carried for signature fidelity with the COBOL parameter list.
    """
    logging_data = file_access.logging_data
    #  THE SAME ONE ADAPTER the bridge's like-named paragraph uses, so the two
    # render identically and differ only in the program they name. `WS-File-Key` -
    # the supplier code - is withheld (CWE-532), and `Log-File-Rec-Written` is
    # advanced modulo one million rather than left alone.
    log_file_handler_record(
        _LOG,
        program=PROG_NAME,
        paragraph="Ca-Process-Logs",
        log_system=logging_data.ws_log_system,
        log_file_no=logging_data.ws_log_file_no,
        no_paragraph=logging_data.ws_no_paragraph,
        file_function=int(file_access.file_function),
        access_type=int(file_access.access_type),
        fs_reply=int(file_access.fs_reply),
        we_error=int(file_access.we_error),
        sql_err=logging_data.sql_err,
        sql_state=logging_data.sql_state,
        dal_common=dal_common,
    )
    # Falls through into ca-Exit.


def ca_exit() -> None:
    """``ca-Exit.`` [common/acas022.cbl:L677].

    Written on one line as ``ca-Exit.     exit.`` - a plain ``exit``, NOT
    ``exit section``, where ``ba-rdbms-exit`` above it is
    ``exit section`` [common/acas022.cbl:L668]. The bridge's own ``ca-Exit`` is
    spelled the same way [common/purchMT.cbl:L2082].
    """
    return


def aa_process_flat_file(
    system: SystemRecord,
    purch: WsPurchRecord,
    file_access: FileAccess,
    file_defs: FileDefs,
    dal_common: AcasDalCommonData,
    *,
    purchase_file: PurchaseFile | None,
    transport: TransportSecurity | None,
) -> None:
    """``aa-Process-Flat-File Section.`` [common/acas022.cbl:L287].

    The handler's only section header. It declares no statement of its own and
    falls straight through into ``aa010-main`` [common/acas022.cbl:L289], so this
    function exists purely so that rule R-5's paragraph-to-function mapping has an
    entry for the label a reader of the frozen listing will find.

    Note the name: the section is called "Process-Flat-File" and yet it is the
    section that dispatches to the RDB bridge as well
    [common/acas022.cbl:L316-L320]. The name describes what the handler did before
    the SQL migration, not what it does now, and it is not renamed.

    Args:
        system: The ``SYSTEM-REC`` row.
        purch: The caller's record.
        file_access: The ``File-Access`` block.
        file_defs: The file-name block.
        dal_common: The logging switches.
        purchase_file: The ISAM store, when the flat-file path is selected.
        transport: The transport policy for the RDB open path.
    """
    aa010_main(
        system,
        purch,
        file_access,
        file_defs,
        dal_common,
        purchase_file=purchase_file,
        transport=transport,
    )


def aa010_main(
    system: SystemRecord,
    purch: WsPurchRecord,
    file_access: FileAccess,
    file_defs: FileDefs,
    dal_common: AcasDalCommonData,
    *,
    purchase_file: PurchaseFile | None,
    transport: TransportSecurity | None,
) -> None:
    """``aa010-main.`` [common/acas022.cbl:L289-L361].

    The paragraph that decides which store serves the request. Its statements, in
    the frozen order:

    1. The log identity [common/acas022.cbl:L293-L294] - ``WS-Log-System = 4``,
       the only handler in the folder that uses 4, and ``WS-Log-File-No = 11``.
       ANOMALY ``N-logsystem5-meaning``: the legend on that line reads
       ``5=Stock``, matching two siblings and contradicting two others that read
       ``5=Invoice`` [common/acas013.cbl:L298, common/acas015.cbl:L291 against
       common/acas016.cbl:L248, common/acas019.cbl:L240]. Recorded, not resolved.

    2. The key guard [common/acas022.cbl:L298-L312]. Functions 4 and 9 share one
       arm and report ``998``; function 8 has its own arm and reports ``996``.
       ANOMALY ``N-guard-extra-comment``: the ``when 8`` arm carries an
       explanation no sibling has - "1 is only for RDB as Cobol does it on primary
       key" [common/acas022.cbl:L307]. ANOMALY ``N-996-comment``: the comment
       beside the 996 is a verbatim copy of the one beside the 998, so it
       describes the wrong code [common/acas022.cbl:L302 against :L308]. Neither
       is rewritten.

    3. The store branch [common/acas022.cbl:L316-L320], with both maintainer
       comments preserved - "needed for DAL? not JC/dbpre versions" and
       "Can't hurt".

    4. ``perform ba012-Test-WS-Rec-Size-2.`` [common/acas022.cbl:L324] - the
       DIRECT performance that skips ``ba010`` and so leaves the log file number
       at 11 on this path.

    5. ANOMALY ``N-sqlstate-not-cleared`` [common/acas022.cbl:L336]. The clear is
       ``move spaces to SQL-Err SQL-Msg.`` - TWO fields. Three sibling handlers
       clear three, ``SQL-State`` included [common/acas015.cbl:L332,
       common/acas019.cbl:L281], and the BRIDGE clears seven
       [common/purchMT.cbl:L408-L414]. So a stale ``SQL-State`` from a previous
       operation survives into this one on the flat-file path. Reproduced exactly;
       ``SQL-State`` is NOT added.

    6. The commented-out ``move zero to WE-Error / FS-Reply``
       [common/acas022.cbl:L334-L335], each line prefixed with the maintainer's
       ``?``. A deliberate non-initialisation, left as it is - the status pair
       carries the caller's incoming values into the dispatch.

    7. The function dispatch [common/acas022.cbl:L338-L358], with ``when 31``
       FOLDED INTO ``when 3``, and the unconditional
       ``go to aa100-Bad-Function`` beneath "Should never get here but in case :("
       [common/acas022.cbl:L360-L361].

    Args:
        system: The ``SYSTEM-REC`` row; its ``File-System-Used`` field chooses the
            store and its ``RDBMS`` fields supply the credentials.
        purch: The caller's record.
        file_access: The ``File-Access`` block.
        file_defs: The file-name block, carried for linkage fidelity.
        dal_common: The logging switches.
        purchase_file: The ISAM store, required only on the flat-file path.
        transport: The transport policy for the RDB open path.

    Raises:
        PurchaseFileNotSuppliedError: If the flat-file path is selected and no
            store was supplied. Not a COBOL condition - see that class.
    """
    logging_data = file_access.logging_data
    # `move 4 to WS-Log-System.` and `move 11 to WS-Log-File-No.`
    # [common/acas022.cbl:L293-L294].
    logging_data.ws_log_system = int(WS_LOG_SYSTEM)
    logging_data.ws_log_file_no = WS_LOG_FILE_NO_COBOL
    function = int(file_access.file_function)
    key_number = int(logging_data.file_key_no)
    # The key guard [common/acas022.cbl:L298-L312].
    if function in _KEY_GUARDED_READ_FUNCTIONS:
        # `when 4 / when 9` share one arm [common/acas022.cbl:L299-L305].
        if key_number != ONLY_KEY_NUMBER:
            _status(
                file_access, FsReply.ERROR, WeError.FILE_KEY_NO_OUT_OF_RANGE
            )
            aa999_main_exit(file_access, dal_common)  # Class 3.
            return
    elif function == int(FileFunction.DELETE):
        # `when 8` [common/acas022.cbl:L306-L311], with N-guard-extra-comment and
        # N-996-comment.
        if key_number != ONLY_KEY_NUMBER:
            _status(
                file_access, FsReply.ERROR, WeError.DELETE_KEY_OUT_OF_RANGE
            )
            aa999_main_exit(file_access, dal_common)  # Class 3.
            return
    # `if not FS-Cobol-Files-Used` [common/acas022.cbl:L316].
    if int(system.system_data_block.rdbms_flat_statuses.file_system_used) != 0:
        # `move RDBMS-Flat-Statuses to FA-RDBMS-Flat-Statuses`
        # [common/acas022.cbl:L317], commented "needed for DAL? not JC/dbpre
        # versions" - copied because the frozen source copies it, whatever the
        # doubt.
        _copy_rdbms_flat_statuses(system, file_access)
        # `perform ba-Process-RDBMS` [common/acas022.cbl:L318], commented
        # "Can't hurt".
        ba_process_rdbms(
            system,
            purch,
            file_access,
            file_defs,
            dal_common,
            transport=transport,
        )
        # `go to AA-Main-Exit` [common/acas022.cbl:L319] - Class 3. Note the
        # third casing of that label, all upper on this line.
        aa_main_exit()
        return
    # `perform ba012-Test-WS-Rec-Size-2.` [common/acas022.cbl:L324] - DIRECT, so
    # ba010's `move 21` never runs and this path keeps log file 11.
    if not ba012_test_ws_rec_size_2(system, purch, file_access, dal_common):
        # The dead 901 branch's transfer, preserved.
        return
    # [common/acas022.cbl:L334-L335] are COMMENTED OUT; the status pair is NOT
    # zeroed here.
    # `move spaces to SQL-Err SQL-Msg.` [common/acas022.cbl:L336] - TWO fields.
    # N-sqlstate-not-cleared: SQL-State is deliberately left alone.
    logging_data.sql_err = " " * 5
    logging_data.sql_msg = " " * 512
    store = _require_purchase_file(purchase_file, "aa010-main")
    # `evaluate File-Function` [common/acas022.cbl:L338-L358]. Every arm is a
    # `go to`, so each is a call followed by `return` - AAP section 0.4.2 Class 4.
    if function == int(FileFunction.OPEN):
        aa020_process_open(file_access, dal_common, store)
        return
    if function == int(FileFunction.CLOSE):
        aa030_process_close(file_access, dal_common, store)
        return
    if function in _AA_READ_NEXT_FUNCTIONS:
        # `when 3 / when 31` [common/acas022.cbl:L343-L345]. ANOMALY
        # N-read-by-name-is-read-next: code 31 falls through into the code 3 arm
        # and is served by the ordinary read-next paragraph, with no name
        # ordering of any kind. The bridge does NOT do this.
        aa040_process_read_next(file_access, purch, dal_common, store)
        return
    if function == int(FileFunction.READ_INDEXED):
        aa050_process_read_indexed(file_access, purch, dal_common, store)
        return
    if function == int(FileFunction.WRITE):
        aa070_process_write(file_access, purch, dal_common, store)
        return
    if function == int(FileFunction.RE_WRITE):
        # `when 7` precedes `when 8` in the frozen order
        # [common/acas022.cbl:L350-L353], the reverse of the paragraph layout.
        aa090_process_rewrite(file_access, purch, dal_common, store)
        return
    if function == int(FileFunction.DELETE):
        aa080_process_delete(file_access, purch, dal_common, store)
        return
    if function == int(FileFunction.START):
        aa060_process_start(file_access, purch, dal_common, store)
        return
    # `when other` [common/acas022.cbl:L356-L357], commented "6 is spare /
    # unused", and the unconditional `go to aa100-Bad-Function` at
    # [common/acas022.cbl:L361] - two entries to one paragraph
    # (``N-badfunction-falls-through``).
    aa100_bad_function(file_access)
    aa999_main_exit(file_access, dal_common)


def dispatch(
    system: SystemRecord,
    purch: WsPurchRecord,
    file_access: FileAccess,
    file_defs: FileDefs,
    dal_common: AcasDalCommonData,
    *,
    purchase_file: PurchaseFile | None = None,
    transport: TransportSecurity | None = None,
) -> tuple[int, int]:
    """``call "acas022" using ...`` - the file handler for the Purchase ledger.

    The migration contract, from AAP section 0.4.3, in the form the plan states
    it::

        FROM:  call "acas022" using System-Record WS-Purch-Record File-Access
                                    File-Defs ACAS-DAL-Common-data
        TO:    acas022_purch.dispatch(system, purch, file_access, file_defs,
                                      dal_common)

    Five parameters, in the order the frozen ``PROCEDURE DIVISION`` declares them
    [common/acas022.cbl:L278-L284], blank lines inside the parameter list and all.

    WHICH STORE SERVES THE REQUEST is decided by one digit of the system record,
    ``File-System-Used`` [copybooks/wssystem.cob:L112], whose condition names are
    ``FS-Cobol-Files-Used value zero`` and ``FS-MySql-Used value 1``
    [copybooks/wssystem.cob:L113-L114]. Zero takes the ISAM paragraphs, one takes
    the bridge. THE TWO PATHS ARE NOT EQUIVALENT, and this module reproduces six
    documented divergences between them rather than papering over any of them:

    ==============================  =========================  ====================
    Condition                       ISAM path                  RDB path
    ==============================  =========================  ====================
    Invalid function code           ``(99, 999)``              ``(99, 990)``
    Start with a bad access type    ``(0, 998)`` - fs zero!    ``(99, 997)``
    Read-indexed, not found         ``(21, 21)``               ``(23, 0)``
    SQL fields cleared on entry     two                        seven
    ``WS-Log-File-No``              11                         21
    Function code 31                plain read-next            ``ORDER BY``
                                                               ``PURCH-NAME``
    ==============================  =========================  ====================

    Every row of that table is a defect reproduced under rule R-4, and every one
    carries its locator at the site that reproduces it.

    Args:
        system: ``System-Record``. Chooses the store, and supplies the RDB
            credentials on the first call of the run.
        purch: ``WS-Purch-Record``, the caller's copy of the row. Read by the
            write, rewrite, delete and start paths; written by the read paths.
        file_access: ``File-Access``. Carries the function code, the access type
            and the key number in, and the status pair plus the whole
            ``Logging-Data`` sub-block out.
        file_defs: ``File-Defs``. Carried for linkage fidelity - the ISAM path
            takes its file from ``purchase_file`` and the RDB path addresses a
            table, so no path reads it. Recorded as a deliberate omission (R-5).
        dal_common: ``ACAS-DAL-Common-data``, carrying ``SW-Testing`` and
            ``SW-Testing-2``.
        purchase_file: The ISAM store. Keyword-only and not part of the COBOL
            parameter list, because in COBOL the file is an ``FD`` in the
            handler's own ``FILE SECTION`` [common/acas022.cbl:L244] rather than a
            parameter. Required ONLY when the system record selects the flat-file
            path.
        transport: Keyword-only transport policy handed to the bridge's open
            path; likewise not a COBOL parameter.

    Returns:
        The ``(Fs-Reply, We-Error)`` pair. ``file_access`` is authoritative and is
        what a COBOL caller inspects; the tuple is a convenience.

    Raises:
        PurchaseFileNotSuppliedError: Only when the flat-file path is selected and
            no store was supplied.

    Example:
        >>> from acas_posting.records.file_access import FileAccess
        >>> from acas_posting.records.file_defs import FileDefs
        >>> from acas_posting.records.purchase_ledger import WsPurchRecord
        >>> from acas_posting.records.system_record import SystemRecord
        >>> from acas_posting.records.test_data_flags import AcasDalCommonData
        >>> system = SystemRecord()
        >>> system.system_data_block.rdbms_flat_statuses.file_system_used = 1
        >>> block = FileAccess()
        >>> block.file_function = 8                  # fn-delete
        >>> block.logging_data.file_key_no = 2       # not the only key there is
        >>> dispatch(system, WsPurchRecord(), block, FileDefs(),
        ...          AcasDalCommonData())
        (99, 996)
    """
    aa_process_flat_file(
        system,
        purch,
        file_access,
        file_defs,
        dal_common,
        purchase_file=purchase_file,
        transport=transport,
    )
    # `aa-Exit. exit program.` [common/acas022.cbl:L588-L589].
    aa_exit()
    return int(file_access.fs_reply), int(file_access.we_error)
